(window.__bibleBooks=window.__bibleBooks||{})[19]={"1":{"1":"Heureux l'homme qui ne suit pas le conseil des impies, ni dans la voie des égarés ne s'arrête, ni au siège des rieurs ne s'assied,","2":"mais se plaît dans la loi de Yahvé, mais murmure sa loi jour et nuit!","3":"Il est comme un arbre planté auprès des cours d'eau; celui-là portera fruit en son temps et jamais son feuillage ne sèche; tout ce qu'il fait réussit:","4":"rien de tel pour les impies, rien de tel! Mais ils sont comme la bale qu'emporte le vent.","5":"Ainsi, les impies ne tiendront pas au Jugement, ni les égarés, à l'assemblée des justes.","6":"Car Yahvé connaît la voie des justes, mais la voie des impies se perd."},"2":{"1":"Pourquoi ces nations qui remuent, ces peuples qui murmurent en vain?","2":"Des rois de la terre s'insurgent, des princes conspirent contre Yahvé et contre son Messie:","3":"\"Faisons sauter leurs entraves, débarrassons-nous de leurs liens! \"","4":"Celui qui siège dans les cieux s'en amuse, Yahvé les tourne en dérision.","5":"Puis dans sa colère il leur parle, dans sa fureur il les épouvante:","6":"\"C'est moi qui ai sacré mon roi sur Sion, ma montagne sainte.\"","7":"J'énoncerai le décret de Yahvé: Il m'a dit: \"Tu es mon fils, moi, aujourd'hui, je t'ai engendré.","8":"Demande, et je te donne les nations pour héritage, pour domaine les extrémités de la terre;","9":"tu les briseras avec un sceptre de fer, comme vases de potier tu les casseras.\"","10":"Et maintenant, rois, comprenez, corrigez-vous, juges de la terre!","11":"Servez Yahvé avec crainte,","12":"baisez ses pieds avec tremblement; qu'il se fâche, vous vous perdez en chemin: d'un coup flambe sa colère. Heureux qui s'abrite en lui!"},"3":{"1":"Psaume de David. Quand il fuyait devant son fils Absalom.","2":"Yahvé, qu'ils sont nombreux mes oppresseurs, nombreux ceux qui se lèvent contre moi,","3":"nombreux ceux qui disent de mon âme: \"Point de salut pour elle en son Dieu! \"","4":"Mais toi, Yahvé, bouclier qui m'entoures, ma gloire! tu me redresses la tête.","5":"A pleine voix je crie vers Yahvé, il me répond de sa montagne sainte.","6":"Et moi, je me couche et m'endors, je m'éveille: Yahvé est mon soutien.","7":"Je ne crains pas ces gens par milliers qui forment un cercle contre moi.","8":"Lève-toi, Yahvé! Sauve-moi, mon Dieu! Tu frappes à la joue tous mes adversaires, les dents des impies, tu les brises.","9":"De Yahvé, le salut! Sur ton peuple, ta bénédiction!"},"4":{"1":"Du maître de chant. Avec instruments à cordes. Psaume de David.","2":"Quand je crie, réponds-moi, Dieu de ma justice, dans l'angoisse tu m'as mis au large: pitié pour moi, écoute ma prière!","3":"Fils d'homme, jusqu'où s'alourdiront vos coeurs, pourquoi ce goût du rien, cette course à l'illusion?","4":"Sachez-le, pour son ami Yahvé fait merveille, Yahvé écoute quand je crie vers lui.","5":"Frémissez et ne péchez plus, parlez en votre coeur, sur votre couche faites silence.","6":"Offrez des sacrifices de justice et soyez sûrs de Yahvé.","7":"Beaucoup disent: \"Qui nous fera voir le bonheur?\" Fais lever sur nous la lumière de ta face. Yahvé,","8":"tu as mis en mon coeur plus de joie qu'aux jours ou leur froment, leur vin nouveau débordent.","9":"En paix, tout aussitôt, je me couche et je dors: c'est toi, Yahvé, qui m'établis à part, en sûreté."},"5":{"1":"Du maître de chant. Sur les flûtes. Psaume de David.","2":"Ma parole, entends-la, Yahvé, discerne ma plainte,","3":"attentif à la voix de mon appel, ô mon Roi et mon Dieu! C'est toi que je prie,","4":"Yahvé! Au matin tu écoutes ma voix; au matin je fais pour toi les apprêts et je reste aux aguets.","5":"Tu n'es pas un Dieu agréant l'impiété, le méchant n'est pas ton hôte;","6":"non, les arrogants ne tiennent pas devant ton regard. Tu hais tous les malfaisants,","7":"tu fais périr les imposteurs; l'homme de sang et de fraude, Yahvé le hait.","8":"Et moi, par la grandeur de ton amour, j'accède à ta maison; vers ton Temple sacré je me prosterne, pénétré de ta crainte.","9":"Yahvé, guide-moi dans ta justice à cause de ceux qui me guettent, redresse devant moi ton chemin.","10":"Non, rien n'est sûr dans leur bouche, et leur fond n'est que ruine, leur gosier est un sépulcre béant, mielleuse se fait leur langue.","11":"Traite-les en coupables, ô Dieu, qu'ils échouent dans leurs intrigues; pour leurs crimes sans nombre, repousse-les, pour leur révolte contre toi.","12":"Joie pour tous ceux que tu abrites, réjouissance à jamais; tu les protèges, en toi exultent les amants de ton nom.","13":"Toi, tu bénis le juste, Yahvé, comme un bouclier, ta faveur le couronne."},"6":{"1":"Du maître de chant. Sur les instruments à cordes. Sur l'octacorde. Psaume de David.","2":"Yahvé, ne me châtie point dans ta colère, ne me reprends point dans ta fureur.","3":"Pitié pour moi, Yahvé, je suis à bout de force, guéris-moi, Yahvé, mes os sont bouleversés,","4":"mon âme est toute bouleversée. Mais toi, Yahvé, jusques à quand?","5":"Reviens, Yahvé, délivre mon âme, sauve-moi, en raison de ton amour.","6":"Car, dans la mort, nul souvenir de toi: dans le shéol, qui te louerait?","7":"Je me suis épuisé en gémissements, chaque nuit, je baigne ma couche; de mes larmes j'arrose mon lit,","8":"mon oeil est rongé de pleurs. Insolence chez tous mes oppresseurs;","9":"loin de moi, tous les malfaisants! Car Yahvé entend la voix de mes sanglots;","10":"Yahvé entend ma supplication, Yahvé accueillera ma prière.","11":"Tous mes ennemis, confondus, bouleversés, qu'ils reculent, soudain confondus!"},"7":{"1":"Lamentation. De David. Qu'il chanta à Yahvé à propos de Kush le Benjaminite.","2":"Yahvé mon Dieu, en toi j'ai mon abri, sauve-moi de tous mes poursuivants, délivre-moi;","3":"qu'il n'emporte comme un lion mon âme, lui qui déchire, et personne qui délivre!","4":"Yahvé mon Dieu, si j'ai fait cela, laissé la fraude sur mes mains,","5":"si j'ai rendu le mal à mon bienfaiteur, épargné un injuste oppresseur,","6":"que l'ennemi poursuive mon âme et l'atteigne! Qu'il écrase ma vie contre terre et relègue mes entrailles dans la poussière!","7":"Lève-toi, Yahvé, dans ta colère, dresse-toi contre les excès de mes oppresseurs, réveille-toi, mon Dieu. Tu ordonnes le jugement.","8":"Que l'assemblée des nations t'environne, reviens au-dessus d'elle.","9":"(Yahvé est l'arbitre des peuples.) Juge-moi, Yahvé, selon ma justice et selon mon intégrité.","10":"Mets fin à la malice des impies, confirme le juste, toi qui sondes les coeurs et les reins, ô Dieu le juste!","11":"Le bouclier qui me couvre, c'est Dieu, le sauveur des coeurs droits,","12":"Dieu le juste juge, lent à la colère, mais Dieu en tout temps menaçant","13":"pour qui ne revient. Que l'ennemi affûte son épée, qu'il bande son arc et l'apprête,","14":"c'est pour lui qu'il apprête les engins de mort et fait de ses flèches des brandons;","15":"le voici en travail de malice, il a conçu la peine, il enfante le mécompte.","16":"Il ouvre une fosse et la creuse, il tombera dans le trou qu'il a fait;","17":"sa peine reviendra sur sa tête, sa violence lui retombera sur le crâne.","18":"Je rends grâce à Yahvé pour sa justice, je joue pour le Nom du Très-Haut."},"8":{"1":"Du maître de chant. Sur la... de Gat. Psaume de David.","2":"Yahvé, notre Seigneur, qu'il est puissant ton nom par toute la terre! Lui qui redit ta majesté plus haute que les cieux","3":"par la bouche des enfants, des tout petits, tu l'établis, lieu fort, à cause de tes adversaires pour réduire l'ennemi et le rebelle.","4":"A voir ton ciel, ouvrage de tes doigts, la lune et les étoiles, que tu fixas,","5":"qu'est donc le mortel, que tu t'en souviennes, le fils d'Adam, que tu le veuilles visiter?","6":"A peine le fis-tu moindre qu'un dieu; tu le couronnes de gloire et de beauté,","7":"pour qu'il domine sur l'oeuvre de tes mains; tout fut mis par toi sous ses pieds,","8":"brebis et boeufs, tous ensemble, et même les bêtes des champs,","9":"l'oiseau du ciel et les poissons de la mer, quand il va par les sentiers des mers.","10":"Yahvé, notre Seigneur, qu'il est puissant ton nom par toute la terre!"},"9":{"1":"Du maître de chant. Sur hautbois et harpe. Psaume de David.","2":"Je te rends grâce, Yahvé, de tout mon coeur, j'énonce toutes tes merveilles,","3":"j'exulte et me réjouis en toi, je joue pour ton nom, Très-Haut.","4":"Mes ennemis retournent en arrière, ils fléchissent, ils périssent devant ta face,","5":"quand tu m'as rendu sentence et jugement, siégeant sur le trône en juste juge.","6":"Tu as maté les païens, fait périr l'impie, effacé leur nom pour toujours et à jamais;","7":"l'ennemi est achevé, ruines sans fin, tu as renversé des villes, et leur souvenir a péri. Voici,","8":"Yahvé siège pour toujours, il affermit pour le jugement son trône;","9":"lui, il jugera le monde avec justice, prononcera sur les nations avec droiture.","10":"Que Yahvé soit un lieu fort pour l'opprimé, un lieu fort aux temps de détresse!","11":"En toi se confient ceux qui connaissent ton nom, tu n'abandonnes point ceux qui te cherchent, Yahvé.","12":"Jouez pour Yahvé, l'habitant de Sion, racontez parmi les peuples ses hauts faits!","13":"Lui qui s'enquiert du sang se souvient d'eux, il n'oublie pas le cri des malheureux.","14":"Pitié pour moi, Yahvé, vois mon malheur, tu me fais remonter des portes de la mort,","15":"que j'énonce toute ta louange aux portes de la fille de Sion, joyeux de ton salut.","16":"Les païens ont croulé dans la fosse qu'ils ont faite, au filet qu'ils ont tendu, leur pied s'est pris.","17":"Yahvé s'est fait connaître, il a rendu le jugement, il a lié l'impie dans l'ouvrage de ses mains.","18":"Que les impies retournent au shéol, tous ces païens qui oublient Dieu!","19":"Car le pauvre n'est pas oublié jusqu'à la fin, l'espoir des malheureux ne périt pas à jamais.","20":"Dresse-toi, Yahvé, que l'homme ne triomphe, qu'ils soient jugés, les païens, devant ta face!","21":"Jette, Yahvé, sur eux l'épouvante, qu'ils connaissent, les païens, qu'ils sont hommes!"},"10":{"1":"Pourquoi, Yahvé, restes-tu loin, te caches-tu aux temps de détresse?","2":"Sous l'orgueil de l'impie le malheureux est pourchassé, il est pris aux ruses que l'autre a combinées.","3":"L'impie se loue des désirs de son âme, l'homme avide qui bénit méprise Yahvé,","4":"l'impie, arrogant, ne cherche point: \"Pas de Dieu! \" voilà toute sa pensée.","5":"A chaque instant ses démarches aboutissent, tes jugements sont trop hauts pour lui, tous ses rivaux, il souffle sur eux.","6":"Il dit en son coeur: \"Je tiendrai bon d'âge en âge.\" Lui qui n'est pas dans le malheur,","7":"il maudit. Fraude et violence lui emplissent la bouche, sous sa langue peine et méfait;","8":"il est assis à l'affût dans les roseaux, sous les couverts il massacre l'innocent. Des yeux il épie le misérable,","9":"à l'affût, bien couvert, comme un lion dans son fourré, à l'affût pour ravir le malheureux, il ravit le malheureux en le traînant dans son filet.","10":"Il épie, s'accroupit, se tapit, le misérable tombe en son pouvoir;","11":"il dit en son coeur: \"Dieu oublie, il se couvre la face pour ne pas voir jusqu'à la fin.\"","12":"Dresse-toi, Yahvé! O Dieu, lève ta main, n'oublie pas les malheureux!","13":"Pourquoi l'impie blasphème-t-il Dieu, dit-il en son coeur: \"Tu ne chercheras point?\"","14":"Tu as vu, toi, la peine et les pleurs, tu regardes pour les prendre en ta main: à toi le misérable s'abandonne, l'orphelin, toi, tu le secours.","15":"Brise le bras de l'impie, du méchant, tu chercheras son impiété, tu ne la trouveras plus.","16":"Yahvé est roi pour toujours et à jamais, les païens ont disparu de sa terre.","17":"Le désir des humbles, tu l'écoutes, Yahvé, tu affermis leur coeur, tu tends l'oreille,","18":"pour juger l'orphelin et l'opprimé: qu'il cesse de faire peur, l'homme né de la terre!"},"11":{"1":"Du maître de chant. De David. En Yahvé j'ai mon abri. Comment dites-vous à mon âme: \"Fuis à ta montagne, passereau.","2":"\"Vois les impies bander leur arc, ils ajustent leur flèche à la corde pour viser dans l'ombre les coeurs droits;","3":"si les fondations sont ruinées, que peut le juste?\"","4":"Yahvé dans son palais de sainteté, Yahvé, dans les cieux est son trône; ses yeux contemplent le monde, ses paupières éprouvent les fils d'Adam.","5":"Yahvé éprouve le juste et l'impie. Qui aime la violence, son âme le hait.","6":"Il fera pleuvoir sur les impies charbons de feu et soufre et dans leur coupe un vent de flamme pour leur part.","7":"Yahvé est juste, il aime la justice, les coeurs droits contempleront sa face."},"12":{"1":"Du maître de chant. Sur l'octacorde. Psaume de David.","2":"Sauve, Yahvé! c'en est fait de tes amis, les fidèles ont disparu d'entre les fils d'Adam.","3":"On ne fait que mentir, chacun à son prochain, lèvres trompeuses, langage d'un coeur double.","4":"Que Yahvé retranche toute lèvre trompeuse, la langue qui fait de grandes phrases,","5":"ceux qui disent: \"La langue est notre fort, nos lèvres sont pour nous, qui serait notre maître?\"","6":"A cause du malheureux qu'on dépouille, du pauvre qui gémit, maintenant je me lève, déclare Yahvé: j'assurerai le salut à ceux qui en ont soif.","7":"Les paroles de Yahvé sont des paroles sincères, argent natif qui sort de terre, sept fois épuré;","8":"toi, Yahvé, tu y veilleras. Tu le protégeras d'une telle engeance à jamais;","9":"de toutes parts les impies s'en iront, comble d'abjection chez les fils d'Adam."},"13":{"1":"Du maître de chant. Psaume de David.","2":"Jusques à quand, Yahvé, m'oublieras-tu? Jusqu'à la fin? Jusques à quand me vas-tu cacher ta face?","3":"Jusques à quand mettrai-je en mon âme la révolte, en mon coeur le chagrin, de jour et de nuit? Jusques à quand mon adversaire aura-t-il le dessus?","4":"Regarde, réponds-moi, Yahvé mon Dieu! Illumine mes yeux, que dans la mort je ne m'endorme.","5":"Que l'adversaire ne dise: \"Je l'emporte sur lui\", que mes oppresseurs n'exultent à me voir chanceler!","6":"Pour moi, en ton amour je me confie; que mon coeur exulte, admis en ton salut, que je chante à Yahvé pour le bien qu'il m'a fait, que je joue pour le nom de Yahvé le Très-Haut!"},"14":{"1":"Du maître de chant. De David. L'insensé a dit en son coeur: \"Non, plus de Dieu! \" Corrompues, abominables leurs actions; non, plus d'honnête homme.","2":"Des cieux Yahvé se penche vers les fils d'Adam, pour voir s'il en est un de sensé, un qui cherche Dieu.","3":"Tous ils sont dévoyés, ensemble pervertis. Non, il n'est plus d'honnête homme, non, plus un seul.","4":"Ne savent-ils, tous les malfaisants? Ils mangent mon peuple, voilà le pain qu'ils mangent, ils n'invoquent pas Yahvé.","5":"Là, ils seront frappés d'effroi sans cause d'effroi, car Dieu est pour la race du juste:","6":"vous bafouez la révolte du pauvre, mais Yahvé est son abri.","7":"Qui donnera de Sion le salut d'Israël? Lorsque Yahvé ramènera son peuple, allégresse à Jacob et joie pour Israël!"},"15":{"1":"Psaume de David. Yahvé, qui logera sous ta tente, habitera sur ta sainte montagne?","2":"Celui qui marche en parfait, celui qui agit en juste et dit la vérité de son coeur,","3":"sans laisser courir sa langue; qui ne lèse en rien son frère, ne jette pas d'opprobre à son prochain,","4":"méprise du regard le réprouvé, mais honore les craignants de Yahvé; qui jure à ses dépens sans se dédire,","5":"ne prête pas son argent à intérêt, n'accepte rien pour nuire à l'innocent. Qui fait ainsi jamais ne bronchera."},"16":{"1":"A mi-voix. De David. Garde-moi, ô Dieu, mon refuge est en toi.","2":"J'ai dit à Yahvé: C'est toi mon Seigneur, mon bonheur n'est en aucun","3":"de ces démons de la terre. Ceux-là en imposent à tous ceux qui les aiment,","4":"leurs idoles foisonnent, on court à leur suite. Verser leurs libations de sang? Jamais! Faire monter leurs noms sur mes lèvres? Jamais!","5":"Yahvé, ma part d'héritage et ma coupe, c'est toi qui garantis mon lot;","6":"le cordeau me marque un enclos de délices, et l'héritage est pour moi magnifique.","7":"Je bénis Yahvé qui s'est fait mon conseil, et même la nuit, mon coeur m'instruit.","8":"J'ai mis Yahvé devant moi sans relâche; puisqu'il est à ma droite, je ne bronche pas.","9":"Aussi, mon coeur exulte, mes entrailles jubilent, et ma chair reposera en sûreté;","10":"car tu ne peux abandonner mon âme au shéol, tu ne peux laisser ton ami voir la fosse.","11":"Tu m'apprendras le chemin de vie, devant ta face, plénitude de joie, en ta droite, délices éternelles."},"17":{"1":"Prière. De David. Ecoute, Yahvé, la justice, sois attentif à mes cris; prête l'oreille à ma prière, point de fraude sur mes lèvres.","2":"De ta face sortira mon jugement, tes yeux regardent la droiture.","3":"Tu sondes mon coeur, tu me visites la nuit, tu m'éprouves sans rien trouver, aucun murmure en moi: ma bouche n'a point péché","4":"à la façon des hommes. La parole de tes lèvres, moi je l'ai gardée, aux sentiers prescrits","5":"attachant mes pas, à tes traces, que mes pieds ne trébuchent.","6":"Je suis là, je t'appelle, car tu réponds, ô Dieu! Tends l'oreille vers moi, écoute mes paroles,","7":"signale tes grâces, toi qui sauves ceux qui recourent à ta droite contre les assaillants.","8":"Garde-moi comme la prunelle de l'oeil, à l'ombre de tes ailes cache-moi","9":"aux regards de ces impies qui me ravagent; ennemis au fond de l'âme, ils me cernent.","10":"Ils sont enfermés dans leur graisse, ils parlent, l'arrogance à la bouche.","11":"Ils marchent contre moi, maintenant ils m'encerclent, ils ont l'oeil sur moi pour me terrasser.","12":"Leur apparence est d'un lion impatient d'arracher et d'un lionceau tapi dans sa cachette.","13":"Lève-toi, Yahvé, affronte-le, renverse-le, par ton épée délivre mon âme de l'impie,","14":"des mortels, par ta main, Yahvé, des mortels qui, dans la vie, ont leur part de ce monde! Avec tes réserves tu leur rempliras le ventre, leurs fils seront rassasiés et ils laisseront le surplus à leurs enfants.","15":"Moi, dans la justice, je contemplerai ta face, au réveil je me rassasierai de ton image."},"18":{"1":"Du maître de chant. Du serviteur de Yahvé, David, qui adressa à Yahvé les paroles de ce cantique, quand Yahvé l'eut délivré de tous ses ennemis et de la main de Saül. Il dit:","2":"Je t'aime, Yahvé, ma force (mon sauveur, tu m'as sauvé de la violence).","3":"Yahvé est mon roc et ma forteresse, mon libérateur, c'est mon Dieu. Je m'abrite en lui, mon rocher, mon bouclier et ma force de salut, ma citadelle et mon refuge.","4":"J'invoque Yahvé, digne de louange et je suis sauvé de mes ennemis.","5":"Les flots de la Mort m'enveloppaient, les torrents de Bélial m'épouvantaient;","6":"les filets du Shéol me cernaient, les pièges de la Mort m'attendaient.","7":"Dans mon angoisse j'invoquai Yahvé, vers mon Dieu je lançai mon cri; il entendit de son temple ma voix et mon cri parvint à ses oreilles.","8":"Et la terre s'ébranla et chancela, les assises des montagnes frémirent, (sous sa colère elles furent ébranlées);","9":"une fumée monta à ses narines et de sa bouche un feu dévorait (des braises s'y enflammèrent).","10":"Il inclina les cieux et descendit, une sombre nuée sous ses pieds;","11":"il chevaucha un chérubin et vola, il plana sur les ailes du vent.","12":"Il fit des ténèbres son voile, sa tente, ténèbre d'eau, nuée sur nuée;","13":"un éclat devant lui enflammait grêle et braises de feu.","14":"Yahvé tonna des cieux, le Très-Haut donna de la voix;","15":"il décocha ses flèches et les dispersa, il lança les éclairs et les chassa.","16":"Et le lit de la mer apparut, les assises du monde se découvrirent, au grondement de ta menace, Yahvé, au vent du souffle de tes narines.","17":"Il envoie d'en haut et me prend, il me retire des grandes eaux,","18":"il me délivre d'un puissant ennemi, d'adversaires plus forts que moi.","19":"Ils m'attendaient au jour de mon malheur, mais Yahvé fut pour moi un appui;","20":"il m'a dégagé, mis au large, il m'a sauvé, car il m'aime.","21":"Yahvé me rend selon ma justice, selon la pureté de mes mains me rétribue,","22":"car j'ai gardé les voies de Yahvé sans faillir loin de mon Dieu.","23":"Ses jugements sont tous devant moi, ses décrets, je ne les ai pas écartés,","24":"mais je suis irréprochable avec lui, je me garde contre le péché.","25":"Et Yahvé me rétribue selon ma justice, ma pureté qu'il voit de ses yeux.","26":"Tu es fidèle avec le fidèle, sans reproche avec l'irréprochable,","27":"pur avec qui est pur mais rusant avec le fourbe,","28":"toi qui sauves le peuple des humbles, et rabaisses les yeux hautains.","29":"C'est toi, Yahvé, ma lampe, mon Dieu éclaire ma ténèbre;","30":"avec toi je force l'enceinte, avec mon Dieu je saute la muraille.","31":"Dieu, sa voie est sans reproche et la parole de Yahvé sans alliage. Il est, lui, le bouclier de quiconque s'abrite en lui.","32":"Qui donc est Dieu, hors Yahvé? Qui est Rocher, sinon notre Dieu?","33":"Ce Dieu qui me ceint de force et rend ma voie irréprochable,","34":"qui égale mes pieds à ceux des biches et me tient debout sur les hauteurs,","35":"qui instruit mes mains au combat, mes bras à bander l'arc d'airain.","36":"Tu me donnes ton bouclier de salut (ta droite me soutient), tu ne cesses de m'exaucer,","37":"tu élargis mes pas sous moi et mes chevilles n'ont point fléchi.","38":"Je poursuis mes ennemis et les atteins, je ne reviens pas qu'ils ne soient achevés;","39":"je les frappe, ils ne peuvent se relever, ils tombent, ils sont sous mes pieds.","40":"Tu m'as ceint de force pour le combat, tu fais ployer sous moi mes agresseurs;","41":"mes ennemis, tu me fais voir leur dos, ceux qui me haïssent, je les extermine.","42":"Ils crient, et pas de sauveur, vers Yahvé, mais pas de réponse;","43":"je les broie comme poussière au vent, je les foule comme la boue des ruelles.","44":"Tu me délivres des querelles de mon peuple, tu me mets à la tête des nations; le peuple que j'ignorais m'est asservi,","45":"les fils d'étrangers me font leur cour, ils sont tout oreille et m'obéissent;","46":"les fils d'étrangers faiblissent, ils quittent en tremblant leurs réduits.","47":"Vive Yahvé, et béni soit mon rocher, exalté, le Dieu de mon salut,","48":"le Dieu qui me donne les vengeances et prosterne les peuples sous moi!","49":"Me délivrant d'ennemis furieux, tu m'exaltes par-dessus mes agresseurs, tu me libères de l'homme de violence.","50":"Aussi je te louerai, Yahvé, chez les païens, et je veux jouer pour ton nom:","51":"\"Il multiplie pour son roi les délivrances et montre de l'amour pour son oint, pour David et sa descendance à jamais.\""},"19":{"1":"Du maître de chant. Psaume de David.","2":"Les cieux racontent la gloire de Dieu, et l'oeuvre de ses mains, le firmament l'annonce;","3":"le jour au jour en publie le récit et la nuit à la nuit transmet la connaissance.","4":"Non point récit, non point langage, nulle voix qu'on puisse entendre,","5":"mais pour toute la terre en ressortent les lignes et les mots jusqu'aux limites du monde. Là-haut, pour le soleil il dressa une tente,","6":"et lui, comme un époux qui sort de son pavillon, se réjouit, vaillant, de courir sa carrière.","7":"A la limite des cieux il a son lever et sa course atteint à l'autre limite, à sa chaleur rien n'est caché.","8":"La loi de Yahvé est parfaite, réconfort pour l'âme; le témoignage de Yahvé est véridique, sagesse du simple.","9":"Les préceptes de Yahvé sont droits, joie pour le coeur; le commandement de Yahvé est limpide, lumière des yeux.","10":"La crainte de Yahvé est pure, immuable à jamais; les jugements de Yahvé sont vérité, équitables toujours,","11":"désirables plus que l'or, que l'or le plus fin; ses paroles sont douces plus que le miel, que le suc des rayons.","12":"Aussi ton serviteur s'en pénètre, les observer est grand profit.","13":"Mais qui s'avise de ses faux pas? Purifie-moi du mal caché.","14":"Préserve aussi ton serviteur de l'orgueil, qu'il n'ait sur moi nul empire! Alors je serai irréprochable et pur du grand péché.","15":"Agrée les paroles de ma bouche et le murmure de mon coeur, sans trêve devant toi, Yahvé, mon rocher, mon rédempteur!"},"20":{"1":"Du maître de chant. Psaume de David.","2":"Qu'il te réponde, Yahvé, au jour d'angoisse, qu'il te protège, le nom du Dieu de Jacob!","3":"Qu'il t'envoie du sanctuaire un secours et de Sion qu'il te soutienne!","4":"Qu'il se rappelle toutes tes offrandes, ton holocauste, qu'il le trouve savoureux!","5":"Qu'il te donne selon ton coeur et tous tes desseins, qu'il les seconde!","6":"Que nous criions de joie en ton salut, qu'au nom de notre Dieu nous pavoisions! Que Yahvé accomplisse toutes tes requêtes!","7":"Maintenant je connais que Yahvé donne le salut à son messie, des cieux de sainteté il lui répondra par les gestes sauveurs de sa droite.","8":"Aux uns les chars, aux autres les chevaux, à nous d'invoquer le nom de Yahvé notre Dieu.","9":"Eux, ils plient, ils tombent, nous, debout, nous tenons.","10":"Yahvé, sauve le roi, réponds-nous au jour de notre appel."},"21":{"1":"Du maître de chant. Psaume de David.","2":"En ta force, Yahvé, le roi se réjouit; combien ton salut le comble d'allégresse!","3":"Tu lui as accordé le désir de son coeur, tu n'as point refusé le souhait de ses lèvres.","4":"Car tu l'as prévenu de bénédictions de choix, tu as mis sur sa tête une couronne d'or fin;","5":"tu lui as accordé la vie qu'il demandait, longueur de jours, encore et à jamais.","6":"Grande gloire lui fait ton salut, tu as mis sur lui le faste et l'éclat;","7":"oui, tu l'établis en bénédiction pour toujours, tu le réjouis de bonheur près de ta face;","8":"oui, le roi se confie en Yahvé, la grâce du Très-Haut le garde du faux pas.","9":"Ta main trouvera tous tes adversaires, ta droite trouvera tes ennemis;","10":"tu feras d'eux une fournaise au jour de ta face, Yahvé les engloutira dans sa colère, le feu les avalera;","11":"leur fruit, tu l'ôteras de la terre, leur semence, d'entre les fils d'Adam.","12":"Ils ont poussé sur toi le malheur, mûri un plan: ils ne pourront rien.","13":"Oui, tu leur feras tourner le dos, sur eux tu ajusteras ton arc.","14":"Lève-toi, Yahvé, dans ta force! Nous chanterons, nous jouerons pour ta vaillance."},"22":{"1":"Du maître de chant. Sur \"la biche de l'aurore.\" Psaume de David.","2":"Mon Dieu, mon Dieu, pourquoi m'as-tu abandonné? Loin de me sauver, les paroles que je rugis!","3":"Mon Dieu, le jour j'appelle et tu ne réponds pas, la nuit, point de silence pour moi.","4":"Et toi, le Saint, qui habites les louanges d'Israël!","5":"en toi nos pères avaient confiance, confiance, et tu les délivrais,","6":"vers toi ils criaient, et ils échappaient, en toi leur confiance, et ils n'avaient pas honte.","7":"Et moi, ver et non pas homme, risée des gens, mépris du peuple,","8":"tous ceux qui me voient me bafouent, leur bouche ricane, ils hochent la tête:","9":"\"Il s'est remis à Yahvé, qu'il le délivre! qu'il le libère, puisqu'il est son ami! \"","10":"C'est toi qui m'as tiré du ventre, ma confiance près des mamelles de ma mère;","11":"sur toi je fus jeté au sortir des entrailles; dès le ventre de ma mère, mon Dieu c'est toi.","12":"Ne sois pas loin: proche est l'angoisse, point de secours!","13":"Des taureaux nombreux me cernent, de fortes bêtes de Bashân m'encerclent;","14":"contre moi bâille leur gueule, lions lacérant et rugissant.","15":"Comme l'eau je m'écoule et tous mes os se disloquent; mon coeur est pareil à la cire, il fond au milieu de mes viscères;","16":"mon palais est sec comme un tesson, et ma langue collée à ma mâchoire. Tu me couches dans la poussière de la mort.","17":"Des chiens nombreux me cernent, une bande de vauriens m'entoure; comme pour déchiqueter mes mains et mes pieds.","18":"Je peux compter tous mes os, les gens me voient, ils me regardent;","19":"ils partagent entre eux mes habits et tirent au sort mon vêtement.","20":"Mais toi, Yahvé, ne sois pas loin, ô ma force, vite à mon aide;","21":"délivre de l'épée mon âme, de la patte du chien, mon unique;","22":"sauve-moi de la gueule du lion, de la corne du taureau, ma pauvre âme.","23":"J'annoncerai ton nom à mes frères, en pleine assemblée je te louerai:","24":"\"Vous qui craignez Yahvé, louez-le, toute la race de Jacob, glorifiez-le, redoutez-le, toute la race d'Israël.\"","25":"Car il n'a point méprisé, ni dédaigné la pauvreté du pauvre, ni caché de lui sa face, mais, invoqué par lui, il écouta.","26":"De toi vient ma louange dans la grande assemblée, j'accomplirai mes voeux devant ceux qui le craignent.","27":"Les pauvres mangeront et seront rassasiés. Ils loueront Yahvé, ceux qui le cherchent: \"que vive votre coeur à jamais! \"","28":"Tous les lointains de la terre se souviendront et reviendront vers Yahvé; toutes les familles des nations se prosterneront devant lui.","29":"A Yahvé la royauté, au maître des nations!","30":"Oui, devant lui seul se prosterneront tous les puissants de la terre, devant lui se courberont tous ceux qui descendent à la poussière: et pour celui qui ne vit plus,","31":"sa lignée le servira, elle annoncera le Seigneur aux âges","32":"à venir, elle racontera aux peuples à naître sa justice: il l'a faite!"},"23":{"1":"Psaume de David. Yahvé est mon berger, rien ne me manque.","2":"Sur des prés d'herbe fraîche il me parque. Vers les eaux du repos il me mène,","3":"il y refait mon âme; il me guide aux sentiers de justice à cause de son nom.","4":"Passerais-je un ravin de ténèbre, je ne crains aucun mal car tu es près de moi; ton bâton, ta houlette sont là qui me consolent.","5":"Devant moi tu apprêtes une table face à mes adversaires; d'une onction tu me parfumes la tête, ma coupe déborde.","6":"Oui, grâce et bonheur me pressent tous les jours de ma vie; ma demeure est la maison de Yahvé en la longueur des jours."},"24":{"1":"Psaume de David. A Yahvé la terre et sa plénitude, le monde et tout son peuplement;","2":"c'est lui qui l'a fondée sur les mers, et sur les fleuves l'a fixée.","3":"Qui montera sur la montagne de Yahvé? Et qui se tiendra dans son lieu saint?","4":"L'homme aux mains nettes, au coeur pur: son âme ne se porte pas vers des riens, il ne jure pas pour tromper.","5":"Il emportera la bénédiction de Yahvé et la justice du Dieu de son salut.","6":"C'est la race de ceux qui Le cherchent, qui recherchent ta face, Dieu de Jacob.","7":"Portes, levez vos frontons, élevez-vous, portails antiques, qu'il entre, le roi de gloire!","8":"Qui est-il, ce roi de gloire? C'est Yahvé, le fort, le vaillant, Yahvé, le vaillant des combats.","9":"Portes, levez vos frontons, élevez-vous, portails antiques, qu'il entre, le roi de gloire!","10":"Qui est-il, ce roi de gloire? Yahvé Sabaot, c'est lui, le roi de gloire."},"25":{"1":"De David. Vers toi, Yahvé, j'élève mon âme,","2":"ô mon Dieu. En toi je me confie, que je n'aie point honte, que mes ennemis ne se rient de moi!","3":"Pour qui espère en toi, point de honte, mais honte à qui trahit sans raison.","4":"Fais-moi connaître, Yahvé, tes voies, enseigne-moi tes sentiers.","5":"Dirige-moi dans ta vérité, enseigne-moi, c'est toi le Dieu de mon salut. En toi tout le jour j'espère à cause de ta bonté, Yahvé.","6":"Souviens-toi de ta tendresse, Yahvé, de ton amour, car ils sont de toujours.","7":"Ne te souviens pas des égarements de ma jeunesse, mais de moi, selon ton amour souviens-toi!","8":"Droiture et bonté que Yahvé, lui qui remet dans la voie les égarés,","9":"qui dirige les humbles dans la justice, qui enseigne aux malheureux sa voie.","10":"Tous les sentiers de Yahvé sont amour et vérité pour qui garde son alliance et ses préceptes.","11":"A cause de ton nom, Yahvé, pardonne mes torts, car ils sont grands.","12":"Est-il un homme qui craigne Yahvé, il le remet dans la voie qu'il faut prendre;","13":"son âme habitera le bonheur, sa lignée possédera la terre.","14":"Le secret de Yahvé est pour ceux qui le craignent, son alliance, pour qu'ils aient la connaissance.","15":"Mes yeux sont fixés sur Yahvé, car il tire mes pieds du filet.","16":"Tourne-toi vers moi, pitié pour moi, solitaire et malheureux que je suis.","17":"Desserre l'angoisse de mon coeur, hors de mes tourments tire-moi.","18":"Vois mon malheur et ma peine, efface tous mes égarements.","19":"Vois mes ennemis qui foisonnent, de quelle haine violente ils me haïssent.","20":"Garde mon âme, délivre-moi, point de honte pour moi: tu es mon abri.","21":"Qu'intégrité et droiture me protègent, j'espère en toi, Yahvé.","22":"Rachète Israël, ô Dieu, de toutes ses angoisses."},"26":{"1":"De David. Justice pour moi, Yahvé, moi j'ai marché en mon intégrité, je m'appuie sur Yahvé et ne dévie pas.","2":"Scrute-moi, Yahvé, éprouve-moi, passe au feu mes reins et mon coeur:","3":"j'ai devant les yeux ton amour et je marche en ta vérité.","4":"Je n'ai pas été m'asseoir avec le fourbe, chez l'hypocrite je ne veux entrer;","5":"j'ai détesté le parti des méchants, avec l'impie je ne veux m'asseoir.","6":"Je lave mes mains en l'innocence et tourne autour de ton autel, Yahvé,","7":"faisant retentir l'action de grâces, énonçant toutes tes merveilles;","8":"Yahvé, j'aime la beauté de ta maison et le lieu du séjour de ta gloire.","9":"Ne joins pas mon âme aux égarés ni ma vie aux hommes de sang;","10":"ils ont dans les mains l'infamie, leur droite est pleine de profits.","11":"Pour moi je veux marcher en mon intégrité, rachète-moi, pitié pour moi;","12":"mon pied se tient en droit chemin, je te bénis, Yahvé, dans les assemblées."},"27":{"1":"De David. Yahvé est ma lumière et mon salut, de qui aurais-je crainte? Yahvé est le rempart de ma vie, devant qui tremblerais-je?","2":"Quand s'avancent contre moi les méchants pour dévorer ma chair, ce sont eux, mes ennemis, mes adversaires, qui chancellent et succombent.","3":"Qu'une armée vienne camper contre moi, mon coeur est sans crainte; qu'une guerre éclate contre moi, j'ai là ma confiance.","4":"Une chose qu'à Yahvé je demande, la chose que je cherche, c'est d'habiter la maison de Yahvé tous les jours de ma vie, de savourer la douceur de Yahvé, de rechercher son palais.","5":"Car il me réserve en sa hutte un abri au jour de malheur; il me cache au secret de sa tente, il m'élève sur le roc.","6":"Maintenant ma tête s'élève sur mes rivaux qui m'entourent, et je viens sacrifier en sa tente des sacrifices d'acclamation. Je veux chanter, je veux jouer pour Yahvé.","7":"Ecoute, Yahvé, mon cri d'appel, pitié, réponds-moi!","8":"De toi mon coeur a dit: \"Cherche sa face.\" C'est ta face, Yahvé, que je cherche,","9":"ne me cache point ta face. N'écarte pas ton serviteur avec colère; c'est toi mon secours. Ne me laisse pas, ne m'abandonne pas, Dieu de mon salut.","10":"Si mon père et ma mère m'abandonnent, Yahvé m'accueillera.","11":"Enseigne-moi, Yahvé, ta voie, conduis-moi sur un chemin de droiture à cause de ceux qui me guettent;","12":"ne me livre pas à l'appétit de mes adversaires: contre moi se sont levés de faux témoins qui soufflent la violence.","13":"Je le crois, je verrai la bonté de Yahvé sur la terre des vivants.","14":"Espère en Yahvé, prends coeur et prends courage, espère en Yahvé."},"28":{"1":"De David. Vers toi, Yahvé, j'appelle, mon rocher, ne sois pas sourd! que je ne sois, devant ton silence, comme ceux qui descendent à la fosse!","2":"Ecoute la voix de ma prière quand je crie vers toi, quand j'élève les mains, Yahvé, vers ton Saint des Saints.","3":"Ne me traîne pas avec les impies, avec les malfaisants, qui parlent de paix à leur prochain, et le mal est dans leur coeur.","4":"Donne-leur, Yahvé, selon leurs oeuvres et la malice de leurs actes, selon l'ouvrage de leurs mains donne-leur, paie-les de leur salaire.","5":"Ils méconnaissent les oeuvres de Yahvé, l'ouvrage de tes mains: qu'il les abatte et ne les rebâtisse!","6":"Béni soit Yahvé, car il écoute la voix de ma prière!","7":"Yahvé ma force et mon bouclier, en lui mon coeur a foi; j'ai reçu aide, ma chair a refleuri, de tout coeur je rends grâce.","8":"Yahvé, force pour son peuple, forteresse de salut pour son messie.","9":"Sauve ton peuple, bénis ton héritage, conduis-les, porte-les à jamais!"},"29":{"1":"Psaume de David. Rapportez à Yahvé, fils de Dieu, rapportez à Yahvé gloire et puissance,","2":"rapportez à Yahvé la gloire de son nom, adorez Yahvé dans son éclat de sainteté.","3":"Voix de Yahvé sur les eaux le Dieu de gloire tonne; Yahvé sur les eaux innombrables,","4":"voix de Yahvé dans la force, voix de Yahvé dans l'éclat;","5":"voix de Yahvé, elle fracasse les cèdres, Yahvé fracasse les cèdres du Liban,","6":"il fait bondir comme un veau le Liban, et le Siryôn comme un bouvillon.","7":"Voix de Yahvé, elle taille des éclairs de feu;","8":"voix de Yahvé, elle secoue le désert, Yahvé secoue le désert de Cadès.","9":"Voix de Yahvé, elle secoue les térébinthes, elle dépouille les futaies. Dans son palais tout crie: Gloire!","10":"Yahvé a siégé pour le déluge, il a siégé, Yahvé, en roi éternel.","11":"Yahvé donne la puissance à son peuple, Yahvé bénit son peuple dans la paix."},"30":{"1":"Psaume. Cantique pour la dédicace de la Maison de David.","2":"Je t'exalte, Yahvé, qui m'as relevé, tu n'as pas fait rire de moi mes ennemis.","3":"Yahvé mon Dieu, vers toi j'ai crié, tu m'as guéri.","4":"Yahvé, tu as tiré mon âme du shéol, me ranimant d'entre ceux qui descendent à la fosse.","5":"Jouez pour Yahvé, ceux qui l'aiment, louez sa mémoire de sainteté.","6":"Sa colère est d'un instant, sa faveur pour la vie; au soir la visite des larmes, au matin les cris de joie.","7":"Moi, j'ai dit dans mon bonheur: \"Rien à jamais ne m'ébranlera! \"","8":"Yahvé, ta faveur m'a fixé sur de fortes montagnes; tu caches ta face, je suis bouleversé.","9":"Vers toi, Yahvé, j'appelle, à mon Dieu je demande pitié:","10":"Que gagnes-tu à mon sang, à ma descente en la tombe? Te loue-t-elle, la poussière, annonce-t-elle ta vérité?","11":"Ecoute, Yahvé, pitié pour moi! Yahvé, sois mon secours!","12":"Pour moi tu as changé le deuil en une danse, tu dénouas mon sac et me ceignis d'allégresse;","13":"aussi mon coeur te chantera sans plus se taire, Yahvé mon Dieu, je te louerai à jamais."},"31":{"1":"Du maître de chant. Psaume de David.","2":"En toi, Yahvé, j'ai mon abri, Sur moi pas de honte à jamais! En ta justice affranchis-moi, délivre-moi,","3":"tends l'oreille vers moi, hâte-toi! Sois pour moi un roc de force, une maison fortifiée qui me sauve;","4":"car mon rocher, mon rempart, c'est toi, pour ton nom, guide-moi, conduis-moi!","5":"Tire-moi du filet qu'on m'a tendu, car c'est toi ma force;","6":"en tes mains je remets mon esprit, c'est toi qui me rachètes, Yahvé. Dieu de vérité,","7":"tu détestes les servants de vaines idoles; pour moi, je suis sûr de Yahvé:","8":"que j'exulte et jubile en ton amour! Toi qui as vu ma misère, connu l'oppression de mon âme,","9":"tu ne m'as point livré aux mains de l'ennemi, tu as mis au large mes pas.","10":"Pitié pour moi, Yahvé, l'oppression est sur moi! Les pleurs me rongent les yeux, la gorge et les entrailles.","11":"Car ma vie se consume en affliction et mes années en soupirs; ma vigueur succombe à la misère et mes os se rongent.","12":"Tout ce que j'ai d'oppresseurs fait de moi un scandale; pour mes voisins je ne suis que dégoût, un effroi pour mes amis. Ceux qui me voient dans la rue s'enfuient loin de moi,","13":"comme un mort oublié des coeurs, comme un objet de rebut.","14":"J'entends les calomnies des gens, terreur de tous côtés! ils se groupent à l'envi contre moi, complotant de m'ôter la vie.","15":"Et moi, je m'assure en toi, Yahvé, je dis: C'est toi mon Dieu!","16":"Mes temps sont dans ta main, délivre-moi, des mains hostiles qui s'acharnent;","17":"fais luire ta face sur ton serviteur, sauve-moi par ton amour.","18":"Yahvé, pas de honte sur moi qui t'invoque, mais honte sur les impies! Qu'ils aillent muets au shéol;","19":"silence aux lèvres de mensonge qui parlent du juste insolemment avec superbe et mépris!","20":"Qu'elle est grande, Yahvé, ta bonté! Tu la réserves pour qui te craint, tu la dispenses à qui te prend pour abri face aux fils d'Adam.","21":"Tu les caches au secret de ta face, loin des intrigues des hommes; tu les mets à couvert sous la tente, loin de la guerre des langues.","22":"Béni Yahvé qui fit pour moi des merveilles d'amour (en une ville de rempart)!","23":"Et moi je disais en mon trouble: \"Je suis ôté loin de tes yeux! \" Et pourtant tu écoutas la voix de ma prière quand je criai vers toi.","24":"Aimez Yahvé, tous les siens: il garde les fidèles, mais Yahvé rétribue avec usure celui qui fait l'orgueilleux.","25":"Courage, reprenez coeur, vous tous qui espérez Yahvé!"},"32":{"1":"De David. Poème. Heureux qui est absous de son péché, acquitté de sa faute!","2":"Heureux l'homme à qui Yahvé ne compte pas son tort, et dont l'esprit est sans fraude!","3":"Je me taisais, et mes os se consumaient à rugir tout le jour;","4":"la nuit, le jour, ta main pesait sur moi; mon coeur était changé en un chaume au plein feu de l'été.","5":"Ma faute, je te l'ai fait connaître, je n'ai point caché mon tort; j'ai dit: J'irai à Yahvé. Confesser mon péché. Et toi, tu as absous mon tort, pardonné ma faute.","6":"Aussi chacun des tiens te prie à l'heure de l'angoisse. Que viennent à déborder les grandes eaux, elles ne peuvent l'atteindre.","7":"Tu es pour moi un refuge, de l'angoisse tu me gardes, de chants de délivrance tu m'entoures.","8":"Je t'instruirai, je t'apprendrai la route à suivre, les yeux sur toi, je serai ton conseil.","9":"Ne sois pas comme le cheval ou le mulet qui ne comprend ni la rêne ni le frein: qu'on s'avance pour le dompter, rien à faire pour qu'il s'approche de toi!","10":"Nombreux sont les tourments pour l'impie; qui se fie en Yahvé, la grâce l'entoure.","11":"Réjouissez-vous en Yahvé, exultez, les justes, jubilez, tous les coeurs droits."},"33":{"1":"Criez de joie, les justes, pour Yahvé, aux coeurs droits convient la louange.","2":"Rendez grâce à Yahvé sur la harpe, jouez-lui sur la lyre à dix cordes;","3":"chantez-lui un cantique nouveau, de tout votre art accompagnez l'acclamation!","4":"Droite est la parole de Yahvé, et toute son oeuvre est vérité;","5":"il chérit la justice et le droit, de l'amour de Yahvé la terre est pleine.","6":"Par la parole de Yahvé les cieux ont été faits, par le souffle de sa bouche, toute leur armée;","7":"il rassemble l'eau des mers comme une digue, il met en réserve les abîmes.","8":"Qu'elle tremble devant Yahvé, toute la terre, qu'il soit craint de tous les habitants du monde!","9":"Il parle et cela est, il commande et cela existe.","10":"Yahvé déjoue le plan des nations, il empêche les pensées des peuples;","11":"mais le plan de Yahvé subsiste à jamais, les pensées de son coeur, d'âge en âge.","12":"Heureux le peuple dont Yahvé est le Dieu, la nation qu'il s'est choisie en héritage!","13":"Du haut des cieux Yahvé regarde, il voit tous les fils d'Adam;","14":"du lieu de sa demeure il observe tous les habitants de la terre;","15":"lui seul forme le coeur, il discerne tous leurs actes.","16":"Le roi n'est pas sauvé par une grande force, le brave préservé par sa grande vigueur.","17":"Mensonge qu'un cheval pour sauver, avec sa grande force, pas d'issue.","18":"Voici, l'oeil de Yahvé est sur ceux qui le craignent, sur ceux qui espèrent son amour,","19":"pour préserver leur âme de la mort et les faire vivre au temps de la famine.","20":"Notre âme attend Yahvé, notre secours et bouclier, c'est lui;","21":"en lui, la joie de notre coeur, en son nom de sainteté notre foi.","22":"Sur nous soit ton amour, Yahvé, comme notre espoir est en toi."},"34":{"1":"De David. Quand, déguisant sa raison devant Abimélek, il se fit chasser par lui et s'en alla.","2":"Je bénirai Yahvé en tout temps, sa louange sans cesse en ma bouche;","3":"en Yahvé mon âme se loue, qu'ils écoutent, les humbles, qu'ils jubilent!","4":"Magnifiez avec moi Yahvé, exaltons ensemble son nom.","5":"Je cherche Yahvé, il me répond et de toutes mes frayeurs me délivre.","6":"Qui regarde vers lui resplendira et sur son visage point de honte.","7":"Un pauvre a crié, Yahvé écoute, et de toutes ses angoisses il le sauve.","8":"Il campe, l'ange de Yahvé, autour de ses fidèles, et il les dégage.","9":"Goûtez et voyez comme Yahvé est bon; heureux qui s'abrite en lui!","10":"Craignez Yahvé, vous les saints: qui le craint ne manque de rien.","11":"Les jeunes fauves sont dénués, affamés; qui cherche Yahvé ne manque d'aucun bien.","12":"Venez, fils, écoutez-moi, la crainte de Yahvé, je vous l'enseigne.","13":"Où est l'homme qui désire la vie, épris de jours où voir le bonheur?","14":"Garde ta langue du mal, tes lèvres des paroles trompeuses;","15":"Evite le mal, fais le bien, recherche la paix et poursuis-la.","16":"Pour les justes, les yeux de Yahvé, et pour leurs clameurs, ses oreilles;","17":"contre les malfaisants, la face de Yahvé, pour ôter de la terre leur mémoire.","18":"Ils crient, Yahvé écoute, de toutes leurs angoisses il les délivre;","19":"proche est Yahvé des coeurs brisés, il sauve les esprits abattus.","20":"Malheur sur malheur pour le juste, mais de tous Yahvé le délivre;","21":"Yahvé garde tous ses os, pas un ne sera brisé.","22":"Le mal tuera l'impie, qui déteste le juste expiera.","23":"Yahvé rachète l'âme de ses serviteurs, qui s'abrite en lui n'expiera point."},"35":{"1":"De David. Accuse, Yahvé, mes accusateurs, assaille mes assaillants;","2":"prends armure et bouclier et te lève à mon aide;","3":"brandis la lance et la pique contre mes poursuivants. Dis à mon âme: \"C'est moi ton salut.\"","4":"Honte et déshonneur sur ceux-là qui cherchent mon âme! Arrière! qu'ils reculent confondus, ceux qui ruminent mon malheur!","5":"Qu'ils soient de la bale au vent, l'ange de Yahvé les poussant,","6":"que leur chemin soit ténèbre et glissade, l'ange de Yahvé les poursuivant!","7":"Sans raison ils m'ont tendu leur filet, creusé pour moi une fosse,","8":"la ruine vient sur eux sans qu'ils le sachent; le filet qu'ils ont tendu les prendra, dans la fosse ils tomberont.","9":"Et mon âme exultera en Yahvé, jubilera en son salut.","10":"Tous mes os diront: Yahvé, qui est comme toi pour délivrer le petit du plus fort, le pauvre du spoliateur?","11":"Des témoins de mensonge se lèvent, que je ne connais pas. On me questionne,","12":"on me rend le mal pour le bien, ma vie devient stérile.","13":"Et moi, pendant leurs maladies, vêtu d'un sac, je m'humiliais par le jeûne, ma prière revenant dans mon sein,","14":"comme pour un ami, pour un frère, j'allais çà et là; comme en deuil d'une mère, assombri je me courbais.","15":"Ils se rient de ma chute, ils s'attroupent, ils s'attroupent contre moi; des étrangers, sans que je le sache, déchirent sans répit;","16":"si je tombe, ils m'encerclent, ils grincent des dents contre moi.","17":"Seigneur, combien de temps verras-tu cela? Soustrais mon âme à leurs ravages, aux lionceaux mon unique.","18":"Je rendrai grâce dans la grande assemblée, dans un peuple nombreux je te louerai.","19":"Que ne puissent rire de moi ceux qui m'en veulent à tort, ni se faire des clins d'oeil ceux qui me haïssent sans cause!","20":"Ce n'est point de la paix qu'ils parlent aux paisibles de la terre; ils ruminent de perfides paroles,","21":"la bouche large ouverte contre moi; ils disent: Ha! ha! notre oeil a vu!","22":"Tu as vu, Yahvé, ne te tais plus, Seigneur, ne sois pas loin de moi;","23":"éveille-toi, lève-toi, pour mon droit, Seigneur mon Dieu, pour ma cause;","24":"juge-moi selon ta justice, Yahvé mon Dieu, qu'ils ne se rient de moi!","25":"Qu'ils ne disent en leur coeur: Ha! ma foi! qu'ils ne disent: Nous l'avons englouti!","26":"Honte et déshonneur ensemble sur ceux qui rient de mon malheur; que honte et confusion les couvrent, ceux qui se grandissent à mes dépens!","27":"Rires et cris de joie pour ceux-là que réjouit ma justice, ceux-là, qu'ils disent constamment: \"Grand est Yahvé que réjouit la paix de son serviteur! \"","28":"Et ma langue redira ta justice, tout le jour, ta louange."},"36":{"1":"Du maître de chant. Du serviteur de Yahvé. De David.","2":"C'est un oracle pour l'impie que le péché au fond de son coeur; point de crainte de Dieu devant ses yeux.","3":"Il se voit d'un oeil trop flatteur pour découvrir et détester son tort;","4":"les paroles de sa bouche: fraude et méfait! c'est fini d'être un sage. En fait de bien","5":"il rumine le méfait jusque sur sa couche; ils s'obstine dans la voie qui n'est pas bonne, la mauvaise, il n'en démord pas.","6":"Yahvé, dans les cieux ton amour, jusqu'aux nues, ta vérité;","7":"ta justice, comme les montagnes de Dieu, tes jugements, le grand abîme. L'homme et le bétail, tu les secours, Yahvé,","8":"qu'il est précieux, ton amour, ô Dieu! Ainsi, les fils d'Adam: à l'ombre de tes ailes ils ont abri.","9":"Ils s'enivrent de la graisse de ta maison, au torrent de tes délices tu les abreuves;","10":"en toi est la source de vie, par ta lumière nous voyons la lumière.","11":"Garde ton amour à ceux qui te connaissent, et ta justice aux coeurs droits.","12":"Que le pied des superbes ne m'atteigne, que la main des impies ne me chasse!","13":"Les voilà tombés, les malfaisants, abattus sans pouvoir se relever."},"37":{"1":"De David. Ne t'échauffe pas contre les méchants, ne jalouse pas les artisans de fausseté:","2":"vite comme l'herbe ils sont fanés, flétris comme le vert des prés.","3":"Compte sur Yahvé et agis bien, habite la terre et vis tranquille,","4":"mets en Yahvé ta réjouissance: il t'accordera plus que les désirs de ton coeur.","5":"Remets ton sort à Yahvé, compte sur lui, il agira;","6":"il produira ta justice comme le jour, comme le midi ton droit.","7":"Sois calme devant Yahvé et attends-le, ne t'échauffe pas contre le parvenu, l'homme qui use d'intrigues.","8":"Trêve à la colère, renonce au courroux, ne t'échauffe pas, ce n'est que mal;","9":"car les méchants seront extirpés, qui espère Yahvé possédera la terre.","10":"Encore un peu, et plus d'impie, tu t'enquiers de sa place, il n'est plus;","11":"mais les humbles posséderont la terre, réjouis d'une grande paix.","12":"L'impie complote contre le juste et grince des dents contre lui;","13":"le Seigneur se moque de lui, car il voit venir son jour.","14":"Les impies tirent l'épée, ils tendent l'arc, pour égorger l'homme droit, pour renverser le pauvre et le petit;","15":"l'épée leur entrera au coeur et leurs arcs seront brisés.","16":"Mieux vaut un peu pour le juste que tant de fortune pour l'impie;","17":"car les bras de l'impie seront brisés, mais Yahvé soutient les justes.","18":"Yahvé connaît les jours des parfaits, éternel sera leur héritage;","19":"pas de honte pour eux aux mauvais jours, dans la famine ils seront rassasiés.","20":"Cependant les impies périront, eux, les ennemis de Yahvé; ils s'en iront comme la parure des prés, en fumée ils s'en iront.","21":"L'impie emprunte et ne rend pas, le juste a pitié, il donne;","22":"ceux qu'il bénit posséderont la terre, ceux qu'il maudit seront extirpés.","23":"Yahvé mène les pas de l'homme, ils sont fermes et sa marche lui plaît;","24":"quand il tombe, il ne reste pas terrassé, car Yahvé le soutient par la main.","25":"J'étais jeune, et puis j'ai vieilli, je n'ai pas vu le juste abandonné, ni sa lignée cherchant du pain.","26":"Tout le jour il a pitié, il prête, sa lignée sera en bénédiction!","27":"Evite le mal, agis bien, tu auras une habitation pour toujours;","28":"car Yahvé aime le droit, il n'abandonne pas ses amis. Les malfaisants seront détruits à jamais et la lignée des impies extirpée;","29":"les justes posséderont la terre, là ils habiteront pour toujours.","30":"La bouche du juste murmure la sagesse et sa langue dit le droit;","31":"la loi de son Dieu dans son coeur, ses pas ne chancellent point.","32":"L'impie guette le juste et cherche à le faire mourir;","33":"à sa main Yahvé ne l'abandonne, ne le laisse en justice condamner.","34":"Espère Yahvé et observe sa voie, il t'exaltera pour que tu possèdes la terre: tu verras les impies extirpés.","35":"J'ai vu l'impie forcené s'élever comme un cèdre du Liban;","36":"je suis passé, voici qu'il n'était plus, je l'ai cherché, on ne l'a pas trouvé.","37":"Regarde le parfait, vois l'homme droit: il y a pour le pacifique une postérité;","38":"mais les pécheurs seront tous anéantis, la postérité des impies extirpée.","39":"Le salut des justes vient de Yahvé, leur lieu fort au temps de l'angoisse;","40":"Yahvé les aide et les délivre, il les délivrera des impies, il les sauvera quand ils s'abritent en lui."},"38":{"1":"Psaume de David. Pour commémorer.","2":"Yahvé, ne me châtie pas dans ton courroux, ne me reprends pas dans ta fureur.","3":"En moi tes flèches ont pénétré, sur moi ta main s'est abattue,","4":"rien d'intact en ma chair sous ta colère, rien de sain dans mes os après ma faute.","5":"Mes offenses me dépassent la tête, comme un poids trop pesant pour moi;","6":"mes plaies sont puanteur et pourriture à cause de ma folie;","7":"ravagé, prostré, à bout, tout le jour, en deuil, je m'agite.","8":"Mes reins sont pleins de fièvre, plus rien d'intact en ma chair;","9":"brisé, écrasé, à bout, je rugis, tant gronde mon coeur.","10":"Seigneur, tout mon désir est devant toi, pour toi mon soupir n'est point caché;","11":"le coeur me bat, ma force m'abandonne, et la lumière même de mes yeux.","12":"Amis et compagnons s'écartent de ma plaie, mes plus proches se tiennent à distance;","13":"ils posent des pièges, ceux qui traquent mon âme, ils parlent de crime, ceux qui cherchent mon malheur, tout le jour ils ruminent des trahisons.","14":"Et moi, comme un sourd, je n'entends pas, comme un muet qui n'ouvre pas la bouche,","15":"comme un homme qui n'a rien entendu et n'a pas de réplique à la bouche.","16":"C'est toi, Yahvé, que j'espère, c'est toi qui répondras, Seigneur mon Dieu.","17":"J'ai dit: \"Qu'ils ne se gaussent de moi, qu'ils ne gagnent sur moi quand mon pied chancelle! \"","18":"Or, je suis voué à la chute, mon tourment est devant moi sans relâche.","19":"Mon offense, oui, je la confesse, je suis anxieux de ma faute.","20":"Ceux qui m'en veulent sans cause foisonnent, ils sont légion à me haïr à tort,","21":"à me rendre le mal pour le bien, à m'accuser quand je cherche le bien.","22":"Ne m'abandonne pas, Yahvé, mon Dieu, ne sois pas loin de moi;","23":"vite, viens à mon aide, Seigneur, mon salut!"},"39":{"1":"Du maître de chant. De Yedutûn. Psaume de David.","2":"J'ai dit: \"Je garderai ma route, sans laisser ma langue s'égarer, je garderai à la bouche un bâillon, tant que devant moi sera l'impie.\"","3":"Je me suis tu, silence et calme; à voir sa chance, mon tourment s'exaspéra.","4":"Mon coeur brûlait en moi, à force d'y songer le feu flamba et ma langue vint à parler:","5":"\"Fais-moi savoir, Yahvé, ma fin et quelle est la mesure de mes jours, que je sache combien je suis fragile.","6":"Vois, d'un empan tu fis mes jours, ma durée est comme rien devant toi; rien qu'un souffle, tout homme qui se dresse,","7":"rien qu'une ombre, l'humain qui va; rien qu'un souffle, les richesses qu'il entasse, et il ne sait qui les ramassera.\"","8":"Et maintenant, que puis-je attendre, Seigneur? Mon espérance, elle est en toi.","9":"De tous mes péchés délivre-moi, ne me fais point la risée de l'insensé.","10":"Je me tais, je n'ouvre pas la bouche, car c'est toi qui es à l'oeuvre.","11":"Eloigne de moi tes coups, sous les assauts de ta main je me consume.","12":"Reprenant les torts, tu corriges l'homme, comme la teigne, tu ronges ses désirs. Rien qu'un souffle, tous les humains.","13":"Ecoute ma prière, Yahvé, prête l'oreille à mon cri, ne reste pas sourd à mes pleurs. Car je suis l'étranger chez toi, un passant comme tous mes pères.","14":"Détourne ton regard, que je respire, avant que je m'en aille et ne sois plus."},"40":{"1":"Du maître de chant. De David.","2":"J'espérais Yahvé d'un grand espoir, il s'est penché vers moi, il écouta mon cri.","3":"Il me tira du gouffre tumultueux, de la vase du bourbier; il dressa mes pieds sur le roc, affermissant mes pas.","4":"En ma bouche il mit un chant nouveau, louange à notre Dieu; beaucoup verront et craindront, ils auront foi en Yahvé.","5":"Heureux est l'homme, celui-là qui met en Yahvé sa foi, ne tourne pas du côté des rebelles égarés dans le mensonge!","6":"Que de choses tu as faites, toi, Yahvé mon Dieu, tes merveilles, tes projets pour nous: rien ne se mesure à toi! Je veux le publier, le redire: il en est trop pour les dénombrer.","7":"Tu ne voulais sacrifice ni oblation, tu m'as ouvert l'oreille, tu n'exigeais holocauste ni victime,","8":"alors j'ai dit: Voici, je viens. Au rouleau du livre il m'est prescrit","9":"de faire tes volontés; mon Dieu, j'ai voulu ta loi au profond de mes entrailles.","10":"J'ai annoncé la justice de Yahvé dans la grande assemblée; vois, je ne ferme pas mes lèvres, toi, tu le sais.","11":"Je n'ai pas celé ta justice au profond de mon coeur, j'ai dit ta fidélité, ton salut, je n'ai pas caché ton amour et ta vérité à la grande assemblée.","12":"Toi, Yahvé, tu ne fermes pas pour moi tes tendresses! ton amour et ta vérité sans cesse me garderont.","13":"Car les malheurs m'assiègent, à ne pouvoir les dénombrer; mes torts retombent sur moi, je n'y peux plus voir; ils foisonnent plus que les cheveux de ma tête et le coeur me manque.","14":"Daigne, Yahvé, me secourir! Yahvé, vite à mon aide!","15":"Honte et déshonneur sur tous ceux-là qui cherchent mon âme pour la perdre! Arrière! honnis soient-ils, ceux que flatte mon malheur!","16":"qu'ils soient stupéfiés de honte, ceux qui me disent: Ha! ha!","17":"Joie en toi et réjouissance à tous ceux qui te cherchent! qu'ils redisent toujours: \"Dieu est grand! \" ceux qui aiment ton salut!","18":"Et moi, pauvre et malheureux, le Seigneur pense à moi. Toi, mon secours et sauveur, mon Dieu, ne tarde pas."},"41":{"1":"Du maître de chant. Psaume de David.","2":"Heureux qui pense au pauvre et au faible: au jour de malheur, Yahvé le délivre;","3":"Yahvé le garde, il lui rend vie et bonheur sur terre: oh! ne le livre pas à l'appétit de ses ennemis!","4":"Yahvé le soutient sur son lit de douleur; tu refais tout entière la couche où il languit.","5":"Moi, j'ai dit: \"Pitié pour moi, Yahvé! guéris mon âme, car j'ai péché contre toi! \"","6":"Parlant de moi, mes ennemis me malmènent: \"Quand va-t-il mourir et son nom périr?\"","7":"Vient-on me voir, on dit des paroles en l'air, le coeur plein de malice, on déblatère au-dehors.","8":"Tous à l'envi, mes haïsseurs chuchotent contre moi, ils supputent contre moi le malheur qui est sur moi:","9":"\"C'est une plaie d'enfer qui gagne en lui, maintenant qu'il s'est couché, il n'aura plus de lever.\"","10":"Même le confident sur qui je faisais fond et qui mangeait mon pain, se hausse à mes dépens.","11":"Mais toi, Yahvé, pitié pour moi, fais-moi lever, je les paierai de leur dû, ces gens:","12":"par là, je connaîtrai que tu es mon ami, si l'ennemi ne lance plus contre moi son cri;","13":"et moi, que tu soutiens, je resterai indemne, tu m'auras à jamais établi devant ta face.","14":"Béni soit Yahvé, le Dieu d'Israël, depuis toujours jusqu'à toujours. Amen! Amen!"},"42":{"1":"Du maître de chant. Poème. Des fils de Coré.","2":"Comme languit une biche après les eaux vives, ainsi languit mon âme vers toi, mon Dieu.","3":"Mon âme a soif de Dieu, du Dieu vivant; quand irai-je et verrai-je la face de Dieu?","4":"Mes larmes, c'est là mon pain, le jour, la nuit, moi qui tout le jour entends dire: Où est-il, ton Dieu?","5":"Oui, je me souviens, et mon âme sur moi s'épanche, je m'avançais sous le toit du Très-Grand, vers la maison de Dieu, parmi les cris de joie, l'action de grâces, la rumeur de la fête.","6":"Qu'as-tu, mon âme, à défaillir et à gémir sur moi? Espère en Dieu: à nouveau je lui rendrai grâce, le salut de ma face","7":"et mon Dieu! Mon âme est sur moi défaillante, alors je me souviens de toi: depuis la terre du Jourdain et des Hermons, de toi, humble montagne.","8":"L'abîme appelant l'abîme au bruit de tes écluses, la masse de tes flots et de tes vagues a passé sur moi.","9":"Le jour, Yahvé mande sa grâce et même pendant la nuit le chant qu'elle m'inspire est une prière à mon Dieu vivant.","10":"Je dirai à Dieu mon Rocher: pourquoi m'oublies-tu? Pourquoi m'en aller en deuil, accablé par l'ennemi?","11":"Touché à mort dans mes os, mes adversaires m'insultent en me redisant tout le jour: Où est-il, ton Dieu?","12":"Qu'as-tu, mon âme, à défaillir et à gémir sur moi? Espère en Dieu: à nouveau je lui rendrai grâce, le salut de ma face et mon Dieu!"},"43":{"1":"Juge-moi, Dieu, défends ma cause contre des gens sans amour; de l'homme perfide et pervers, délivre-moi.","2":"C'est toi le Dieu de ma force: pourquoi me rejeter? Pourquoi m'en aller en deuil, accablé par l'ennemi?","3":"Envoie ta lumière et ta vérité: elles me guideront, me mèneront à ta montagne sainte, jusqu'en tes Demeures.","4":"Et j'irai vers l'autel de Dieu, jusqu'au Dieu de ma joie. J'exulterai, je te rendrai grâce sur la harpe, Dieu, mon Dieu.","5":"Qu'as-tu, mon âme, à défaillir et à gémir sur moi? Espère en Dieu: à nouveau je lui rendrai grâce, le salut de ma face et mon Dieu!"},"44":{"1":"Du maître de chant. Des fils de Coré. Poème.","2":"O Dieu, nous avons ouï de nos oreilles, nos pères nous ont raconté l'oeuvre que tu fis de leurs jours, aux jours d'autrefois,","3":"et par ta main. Pour les planter, tu expulsas des nations, pour les étendre, tu malmenas des peuples;","4":"ni leur épée ne conquit le pays, ni leur bras n'en fit des vainqueurs, mais ce furent ta droite et ton bras et la lumière de ta face, car tu les aimais.","5":"C'est toi, mon Roi, mon Dieu, qui décidais les victoires de Jacob;","6":"par toi, nous enfoncions nos adversaires, par ton nom, nous piétinions nos agresseurs.","7":"Ni dans mon arc n'était ma confiance, ni mon épée ne me fit vainqueur;","8":"par toi nous vainquions nos adversaires, tu couvrais nos ennemis de honte;","9":"en Dieu nous jubilions tout le jour, célébrant sans cesse ton nom.","10":"Et pourtant, tu nous as rejetés et bafoués, tu ne sors plus avec nos armées;","11":"tu nous fais reculer devant l'adversaire, nos ennemis ont pillé à coeur joie.","12":"Comme animaux de boucherie tu nous livres et parmi les nations tu nous as dispersés;","13":"tu vends ton peuple à vil prix sans t'enrichir à ce marché.","14":"Tu fais de nous l'insulte de nos voisins, fable et risée de notre entourage;","15":"tu fais de nous le proverbe des nations, hochement de tête parmi les peuples.","16":"Tout le jour, mon déshonneur est devant moi et la honte couvre mon visage,","17":"sous les clameurs d'insulte et de blasphème, au spectacle de la haine et de la vengeance.","18":"Tout cela nous advint sans t'avoir oublié, sans avoir trahi ton alliance,","19":"sans que nos coeurs soient revenus en arrière, sans que nos pas aient quitté ton sentier:","20":"tu nous broyas au séjour des chacals, nous couvrant de l'ombre de la mort.","21":"Si nous avions oublié le nom de notre Dieu, tendu les mains vers un dieu étranger,","22":"est-ce que Dieu ne l'eût pas aperçu, lui qui sait les secrets du coeur?","23":"C'est pour toi qu'on nous massacre tout le jour, qu'on nous traite en moutons d'abattoir.","24":"Lève-toi, pourquoi dors-tu, Seigneur? Réveille-toi, ne rejette pas jusqu'à la fin!","25":"Pourquoi caches-tu ta face, oublies-tu notre oppression, notre misère?","26":"Car notre âme est effondrée en la poussière, notre ventre est collé à la terre.","27":"Debout, viens à notre aide, rachète-nous en raison de ton amour!"},"45":{"1":"Du maître de chant. Sur l'air: Des lys... Des fils de Coré. Poème. Chant d'amour.","2":"Mon coeur a frémi de paroles belles: je dis mon oeuvre pour un roi, ma langue est le roseau d'un scribe agile.","3":"Tu es beau, le plus beau des enfants des hommes, la grâce est répandue sur tes lèvres. Aussi tu es béni de Dieu à jamais.","4":"Ceins ton épée sur ta cuisse, vaillant, dans le faste et l'éclat","5":"va, chevauche, pour la cause de la vérité, de la piété, de la justice. Tends la corde sur l'arc, il rend terrible ta droite!","6":"Tes flèches sont aiguës, voici les peuples sous toi, ils perdent coeur, les ennemis du roi.","7":"Ton trône est de Dieu pour toujours et à jamais! Sceptre de droiture, le sceptre de ton règne!","8":"Tu aimes la justice, tu hais l'impiété. C'est pourquoi Dieu, ton Dieu, t'a donné l'onction d'une huile d'allégresse comme à nul de tes rivaux;","9":"ton vêtement n'est plus que myrrhe et aloès. Des palais d'ivoire, les harpes te ravissent.","10":"Parmi tes bien-aimées sont des filles de roi; à ta droite une dame, sous les ors d'Ophir.","11":"Ecoute, ma fille, regarde et tends l'oreille, oublie ton peuple et la maison de ton père,","12":"alors le roi désirera ta beauté: il est ton Seigneur, prosterne-toi devant lui!","13":"La fille de Tyr, par des présents, déridera ton visage, et les peuples les plus riches,","14":"par maint joyau serti d'or. Vêtue","15":"de brocarts, la fille de roi est amenée au-dedans vers le roi, des vierges à sa suite. On amène les compagnes qui lui sont destinées;","16":"parmi joie et liesse, elles entrent au palais.","17":"A la place de tes pères te viendront des fils; tu en feras des princes par toute la terre.","18":"Que je fasse durer ton nom d'âge en âge, que les peuples te louent dans les siècles des siècles."},"46":{"1":"Du maître de chant. Des fils de Coré. Sur le hautbois. Cantique.","2":"Dieu est pour nous refuge et force, secours dans l'angoisse toujours offert.","3":"Aussi ne craindrons-nous si la terre est changée, si les montagnes chancellent au coeur des mers,","4":"lorsque mugissent et bouillonnent leurs eaux et que tremblent les monts à leur soulèvement. (Avec nous, Yahvé Sabaot, citadelle pour nous, le Dieu de Jacob! )","5":"Un fleuve! Ses bras réjouissent la cité de Dieu, il sanctifie les demeures du Très-Haut.","6":"Dieu est en elle; elle ne peut chanceler, Dieu la secourt au tournant du matin;","7":"des peuples mugissaient, des royaumes chancelaient, il a élevé la voix, la terre se dissout.","8":"Avec nous, Yahvé Sabaot, citadelle pour nous, le Dieu de Jacob!","9":"Allez, contemplez les hauts faits de Yahvé, lui qui remplit la terre de stupeurs.","10":"Il met fin aux guerres jusqu'au bout de la terre; l'arc, il l'a rompu, la lance, il l'a brisée, il a brûlé les boucliers au feu.","11":"\"Arrêtez, connaissez que moi je suis Dieu, exalté sur les peuples, exalté sur la terre! \"","12":"Avec nous, Yahvé Sabaot, citadelle pour nous, le Dieu de Jacob!"},"47":{"1":"Du maître de chant. Des fils de Coré.","2":"Tous les peuples, battez des mains, acclamez Dieu en éclats de joie!","3":"C'est Yahvé, le Très-Haut, le redoutable, le grand Roi sur toute la terre.","4":"Il tient des peuples sous notre joug et des nations sous nos pieds.","5":"Il a choisi pour nous notre héritage, l'orgueil de Jacob, qu'il aime.","6":"Dieu monte parmi l'acclamation, Yahvé, aux éclats du cor.","7":"Sonnez pour notre Dieu, sonnez, sonnez pour notre Roi, sonnez!","8":"C'est le roi de toute la terre: sonnez pour Dieu, qu'on l'apprenne!","9":"Dieu, il règne sur les païens, Dieu siège sur son trône de sainteté.","10":"Les princes des peuples s'unissent: c'est le peuple du Dieu d'Abraham. A Dieu sont les pavois de la terre, au plus haut il est monté."},"48":{"1":"Cantique. Psaume. Des fils de Coré.","2":"Grand, Yahvé, et louable hautement dans la ville de notre Dieu, le mont sacré,","3":"superbe d'élan, joie de toute la terre; le mont Sion, coeur de l'Aquilon, cité du grand roi:","4":"Dieu, du milieu de ses palais, s'est révélé citadelle.","5":"Voici, des rois s'étaient ligués, avançant à la fois;","6":"ils virent, et du coup stupéfaits, pris de panique, ils décampèrent.","7":"Là, un tremblement les saisit, un frisson d'accouchée,","8":"ce fut le vent d'est qui brise les vaisseaux de Tarsis.","9":"Comme on nous l'avait dit, nous l'avons vu dans la ville de notre Dieu, dans la ville de Yahvé Sabaot; Dieu l'affermit à jamais.","10":"Nous méditons, Dieu, ton amour au milieu de ton Temple!","11":"Comme ton nom, Dieu, ta louange, jusqu'au bout de la terre! Ta droite est remplie de justice,","12":"le mont Sion jubile; les filles de Juda exultent devant tes jugements.","13":"Longez Sion, parcourez-la, dénombrez ses tours;","14":"que vos coeurs s'attachent à ses murs, détaillez ses palais; pour raconter aux âges futurs","15":"que lui est Dieu, notre Dieu aux siècles des siècles, lui, il nous conduit!"},"49":{"1":"Du maître de chant. Des fils de Coré.","2":"Ecoutez ceci, tous les peuples, prêtez l'oreille, tous les habitants du monde,","3":"gens du commun et gens de condition, riches et pauvres ensemble!","4":"Ma bouche énonce la sagesse, et le murmure de mon coeur, l'intelligence;","5":"je tends l'oreille à quelque proverbe, je résous sur la lyre mon énigme.","6":"Pourquoi craindre aux jours de malheur? La malice me talonne et me cerne:","7":"eux se fient à leur fortune, se prévalent du surcroît de leur richesse.","8":"Mais l'homme ne peut acheter son rachat ni payer à Dieu sa rançon:","9":"il est coûteux, le rachat de son âme, et il manquera toujours","10":"pour que l'homme survive et jamais ne voie la fosse.","11":"Or, il verra mourir les sages, périr aussi le fou et l'insensé, qui laissent à d'autres leur fortune.","12":"Leurs tombeaux sont à jamais leurs maisons, et leurs demeures d'âge en âge; et ils avaient mis leur nom sur leurs terres!","13":"L'homme dans son luxe ne comprend pas, il ressemble au bétail muet.","14":"Ainsi vont-ils, sûrs d'eux-mêmes, et finissent-ils, contents de leur sort.","15":"Troupeau que l'on parque au shéol, la Mort les mène paître, les hommes droits domineront sur eux. Au matin s'évanouit leur image, le shéol, voilà leur résidence!","16":"Mais Dieu rachètera mon âme des griffes du shéol, et me prendra.","17":"Ne crains pas quand l'homme s'enrichit, quand s'accroît la gloire de sa maison.","18":"A sa mort, il n'en peut rien emporter, avec lui ne descends pas sa gloire.","19":"Son âme qu'en sa vie il bénissait -- et l'on te loue d'avoir pris soin de toi --","20":"ira rejoindre la lignée de ses pères qui plus jamais ne verront la lumière.","21":"L'homme dans son luxe ne comprend pas, il ressemble au bétail muet."},"50":{"1":"D'Asaph. Le Dieu des dieux, Yahvé, accuse, il appelle la terre du levant au couchant.","2":"Depuis Sion, beauté parfaite, Dieu resplendit;","3":"il vient, notre Dieu, il ne se taira point. Devant lui, un feu dévore, autour de lui, bourrasque violente;","4":"il appelle les cieux d'en haut et la terre pour juger son peuple.","5":"\"Assemblez devant moi les miens, qui scellèrent mon alliance en sacrifiant.\"","6":"Les cieux annoncent sa justice: \"Dieu, c'est lui le juge! \"","7":"\"Ecoute, mon peuple, j'accuse, Israël, et je t'adjure, moi, Dieu, ton Dieu.","8":"Ce n'est pas tes sacrifices que j'accuse, tes holocaustes constamment devant moi;","9":"je ne prendrai pas de ta maison un taureau, ni de tes bergeries des boucs.","10":"Car tout fauve des forêts est à moi, des animaux sur les montagnes par milliers;","11":"je connais tous les oiseaux des cieux, toute bête des champs est pour moi.","12":"Si j'ai faim, je n'irai pas te le dire, car le monde est à moi et son contenu.","13":"Vais-je manger la chair des taureaux, le sang des boucs, vais-je le boire?","14":"Offre à Dieu un sacrifice d'action de grâces, accomplis tes voeux pour le Très-Haut;","15":"appelle-moi au jour de l'angoisse, je t'affranchirai et tu me rendras gloire.\"","16":"Mais l'impie, Dieu lui déclare: \"Que viens-tu réciter mes commandements, qu'as-tu mon alliance à la bouche,","17":"toi qui détestes la règle et rejettes mes paroles derrière toi?","18":"Si tu vois un voleur, tu fraternises, tu es chez toi parmi les adultères;","19":"tu livres ta bouche au mal et ta langue trame la tromperie.","20":"Tu t'assieds, tu accuses ton frère, tu déshonores le fils de ta mère.","21":"Voilà ce que tu fais, et je me tairais? Penses-tu que je suis comme toi? Je te dénonce et m'explique devant toi.","22":"Prenez bien garde, vous qui oubliez Dieu, que je n'emporte, et personne pour délivrer!","23":"Qui offre l'action de grâces me rend gloire, à l'homme droit, je ferai voir le salut de Dieu.\""},"51":{"1":"Du maître de chant. Psaume de David.","2":"Quand Natân le prophète vint à lui parce qu'il était allé vers Bethsabée.","3":"Pitié pour moi, Dieu, en ta bonté, en ta grande tendresse efface mon péché,","4":"lave-moi tout entier de mon mal et de ma faute purifie-moi.","5":"Car mon péché, moi, je le connais, ma faute est devant moi sans relâche;","6":"contre toi, toi seul, j'ai péché, ce qui est coupable à tes yeux, je l'ai fait. Pour que tu montres ta justice quand tu parles et que paraisse ta victoire quand tu juges.","7":"Vois: mauvais je suis né, pécheur ma mère m'a conçu.","8":"Mais tu aimes la vérité au fond de l'être, dans le secret tu m'enseignes la sagesse.","9":"Ote mes taches avec l'hysope, je serai pur; lave-moi, je serai blanc plus que neige.","10":"Rends-moi le son de la joie et de la fête: qu'ils dansent, les os que tu broyas!","11":"Détourne ta face de mes fautes, et tout mon mal, efface-le.","12":"Dieu, crée pour moi un coeur pur, restaure en ma poitrine un esprit ferme;","13":"ne me repousse pas loin de ta face, ne m'enlève pas ton esprit de sainteté.","14":"Rends-moi la joie de ton salut, assure en moi un esprit magnanime.","15":"Aux pécheurs j'enseignerai tes voies, à toi se rendront les égarés.","16":"Affranchis-moi du sang, Dieu, Dieu de mon salut, et ma langue acclamera ta justice;","17":"Seigneur, ouvre mes lèvres, et ma bouche publiera ta louange.","18":"Car tu ne prends aucun plaisir au sacrifice; un holocauste, tu n'en veux pas."},"52":{"1":"Du maître de chant. Poème. De David.","2":"Quand Doëg l'Edomite vint avertir Saül en lui disant: \"David est entré dans la maison d'Ahimélek.\"","3":"Pourquoi te prévaloir du mal, héros d'infamie, tout le jour","4":"ruminer le crime? Ta langue est un rasoir effilé, artisan d'imposture.","5":"Tu aimes mieux le mal que le bien, le mensonge que la justice;","6":"tu aimes toute parole qui dévore, langue d'imposture.","7":"C'est pourquoi Dieu t'écrasera, te détruira jusqu'à la fin, t'arrachera de la tente, t'extirpera de la terre des vivants.","8":"Ils verront, les justes, ils craindront, ils se riront de lui:","9":"\"Le voilà, l'homme qui n'a pas mis en Dieu sa forteresse, mais se fiait au nombre de ses biens, se faisait fort de son crime! \"","10":"Et moi, comme un olivier verdoyant dans la maison de Dieu, je compte sur l'amour de Dieu toujours et à jamais.","11":"Je veux te rendre grâce à jamais, car tu as agi, et j'espère ton nom, car il est bon, devant ceux qui t'aiment."},"53":{"1":"Du maître de chant. Pour la maladie. Poème. De David.","2":"L'insensé a dit en son coeur: \"Non, plus de Dieu! \" Ils sont faux, corrompus, abominables; non, il n'est plus d'honnête homme.","3":"Des cieux Dieu se penche vers les fils d'Adam, pour voir s'il en est un de sensé, un qui cherche Dieu?","4":"Tous ils ont dévié, ensemble pervertis. Non, il n'est plus d'honnête homme, non, plus un seul.","5":"Le savent-ils, les malfaisants? Ils mangent mon peuple, voilà le pain qu'ils mangent, ils n'invoquent pas Dieu.","6":"Là ils seront frappés d'effroi sans cause d'effroi. Car Dieu disperse les ossements de ton assiégeant, on les bafoue, car Dieu les rejette.","7":"Qui donnera de Sion le salut d'Israël? Lorsque Dieu ramènera son peuple, allégresse à Jacob et joie pour Israël!"},"54":{"1":"Du maître de chant. Sur les instruments à cordes. Poème. De David.","2":"Lorsque les Ziphéens vinrent dire à Saül: \"David n'est-il pas caché parmi nous?\"","3":"O Dieu, par ton nom sauve-moi, par ton pouvoir fais-moi raison;","4":"ô Dieu, entends ma prière, écoute les paroles de ma bouche!","5":"Contre moi ont surgi des orgueilleux, des forcenés pourchassent mon âme, point de place pour Dieu devant eux.","6":"Mais voici Dieu qui vient à mon secours, le Seigneur avec ceux qui soutiennent mon âme.","7":"Que retombe le mal sur ceux qui me guettent, Yahvé, par ta vérité détruis-les!","8":"De grand coeur je t'offrirai le sacrifice, je rendrai grâce à ton nom, car il est bon,","9":"car il m'a délivré de toute angoisse, mes ennemis me sont donnés en spectacle."},"55":{"1":"Du maître de chant. Sur les instruments à cordes. Poème. De David.","2":"Entends, ô Dieu, ma prière, ne te dérobe pas à ma supplique,","3":"donne-moi audience, réponds-moi, je divague en ma plainte. Je frémis","4":"sous les cris de l'ennemi, sous les huées de l'impie; ils me chargent de crimes, avec rage ils m'accusent.","5":"Mon coeur se tord en moi, les affres de la mort tombent sur moi;","6":"crainte et tremblement me pénètrent, un frisson m'étreint.","7":"Et je dis: Qui me donnera des ailes comme à la colombe, que je m'envole et me pose?","8":"Voici, je m'enfuirais au loin, je gîterais au désert.","9":"J'aurais bientôt un asile contre le vent de calomnie, et l'ouragan","10":"qui dévore, Seigneur, et le flux de leur langue. Je vois en effet la violence et la discorde en la ville;","11":"de jour et de nuit elles tournent en haut de ses remparts. Crime et peine sont au-dedans","12":"la ruine est au-dedans; jamais de sa grand-place ne s'éloignent fraude et tyrannie.","13":"Si encore un ennemi m'insultait, je pourrais le supporter; si contre moi s'élevait mon rival, je pourrais me dérober.","14":"Mais toi, un homme de mon rang, mon ami, mon intime,","15":"à qui m'unissait une douce intimité dans la maison de Dieu! Qu'ils s'en aillent dans le tumulte,","16":"que sur eux fonde la Mort, qu'ils descendent vivants au shéol, car le mal est chez eux, dans leur logis.","17":"Pour moi, vers Dieu j'appelle et Yahvé me sauve;","18":"le soir et le matin et à midi je me plains et frémis. Il entend mon cri,","19":"il rachète dans la paix mon âme de la guerre qu'on me fait: ils sont en procès avec moi.","20":"Or Dieu entendra, il les humiliera, lui qui trône dès l'origine; pour eux, point d'amendement: ils ne craignent pas Dieu.","21":"Il étend les mains contre ses alliés, il a violé son pacte;","22":"plus onctueuse que la crème est sa bouche et son coeur fait la guerre; ses discours sont plus doux que l'huile et ce sont des épées nues.","23":"Décharge sur Yahvé ton fardeau et lui te subviendra, il ne peut laisser à jamais chanceler le juste.","24":"Et toi, ô Dieu, tu les pousses dans le puits du gouffre, les hommes de sang et de fraude, avant la moitié de leurs jours. Et moi je compte sur toi."},"56":{"1":"Du maître de chant. Sur \"l'oppression des princes lointains.\" De David. A mi-voix. Quand les Philistins s'emparèrent de lui à Gat.","2":"Pitié pour moi, ô Dieu, on me harcèle, tout le jour des assaillants me pressent.","3":"Ceux qui me guettent me harcèlent tout le jour: ils sont nombreux ceux qui m'assaillent là-haut.","4":"Le jour où je crains, moi je compte sur toi.","5":"Sur Dieu dont je loue la parole, sur Dieu je compte et ne crains plus, que me fait à moi la chair?","6":"Tout le jour ils s'en prennent à mes paroles, contre moi tous leurs pensers vont à mal;","7":"ils s'ameutent, se cachent, épient mes traces, comme pour surprendre mon âme.","8":"A cause du forfait, rejette-les, dans ta colère, ô Dieu, abats les peuples!","9":"Tu as compté, toi, mes déboires, recueille mes larmes dans ton outre!","10":"Alors mes ennemis reculeront le jour où j'appelle. Je le sais, Dieu est pour moi.","11":"Sur Dieu dont je loue la parole, sur Yahvé dont je loue la parole,","12":"sur Dieu je compte et ne crains plus, que me fait à moi un homme?","13":"A ma charge, ô Dieu, les voeux que je t'ai faits, j'acquitte envers toi les actions de grâces;","14":"car tu sauvas mon âme de la mort pour que je marche à la face de Dieu dans la lumière des vivants."},"57":{"1":"Du maître de chant. \"Ne détruis pas.\" De David. A mi-voix. Quand il s'enfuit de devant Saül dans la caverne.","2":"Pitié pour moi, ô Dieu, pitié pour moi, en toi s'abrite mon âme, à l'ombre de tes ailes je m'abrite, tant que soit passé le fléau.","3":"J'appelle vers Dieu le Très-Haut, le Dieu qui a tout fait pour moi;","4":"que des cieux il envoie et me sauve, qu'il confonde celui qui me harcèle,","5":"Mon âme est couchée parmi les lions, qui dévorent les fils d'Adam; leurs dents, une lance et des flèches, leur langue, une épée acérée.","6":"O Dieu, élève-toi sur les cieux! Sur toute la terre, ta gloire!","7":"Ils tendaient un filet sous mes pas, mon âme était courbée; ils creusaient devant moi une trappe, ils sont tombés dedans.","8":"Mon coeur est prêt, ô Dieu, mon coeur est prêt; je veux chanter, je veux jouer pour toi!","9":"éveille-toi, ma gloire; éveille-toi, harpe, cithare, que j'éveille l'aurore!","10":"Je veux te louer chez les peuples, Seigneur, jouer pour toi dans les pays;","11":"grand jusqu'aux cieux ton amour, jusqu'aux nues, ta vérité.","12":"O Dieu, élève-toi sur les cieux. Sur toute la terre, ta gloire!"},"58":{"1":"Du maître de chant. \"Ne détruis pas.\" De David. A mi-voix.","2":"Est-il vrai, êtres divins, que vous disiez la justice, que vous jugiez selon le droit les fils d'Adam?","3":"Mais non! de coeur vous fabriquez le faux, de vos mains, sur terre, vous pesez l'arbitraire.","4":"Ils sont dévoyés dès le sein, les impies, égarés dès le ventre, ceux qui disent l'erreur;","5":"ils ont du venin comme un venin de serpent, sourds comme l'aspic qui se bouche l'oreille","6":"de peur d'entendre la voix des enchanteurs, du charmeur expert en charmes.","7":"O Dieu, brise en leur bouche leurs dents, arrache les crocs des lionceaux, Yahvé.","8":"Qu'ils s'écoulent comme les eaux qui s'en vont, comme l'herbe qu'on piétine, qu'ils se fanent!","9":"Comme la limace qui s'en va fondant ou l'avorton de la femme qui ne voit pas le soleil!","10":"Avant qu'ils ne poussent en épines comme la ronce: verte ou brûlée, que la Colère en tempête l'emporte!","11":"Joie pour le juste de voir la vengeance: il lavera ses pieds dans le sang de l'impie.","12":"Et l'on dira: oui, il est un fruit pour le juste; oui, il est un Dieu qui juge sur terre."},"59":{"1":"Du maître de chant. \"Ne détruis pas.\" De David. A mi-voix. Quand Saül envoya surveiller sa maison pour le mettre à mort.","2":"Délivre-moi de mes ennemis, mon Dieu, contre mes agresseurs protège-moi,","3":"délivre-moi des ouvriers de mal, des hommes de sang sauve-moi.","4":"Voici qu'ils guettent mon âme, des puissants s'en prennent à moi; sans péché ni faute en moi, Yahvé,","5":"sans aucun tort, ils accourent et se préparent. Réveille-toi, sois devant moi et regarde,","6":"et toi, Yahvé, Dieu Sabaot, Dieu d'Israël, lève-toi pour visiter tous ces païens, sans pitié pour tous ces traîtres malfaisants!","7":"Ils reviennent au soir, ils grognent comme un chien, ils rôdent par la ville.","8":"Voici qu'ils déblatèrent à pleine bouche, sur leurs lèvres sont des épées: \"Y a-t-il quelqu'un qui entende?\"","9":"Toi, Yahvé, tu t'en amuses, tu te ris de tous les païens;","10":"ô ma force, vers toi je regarde. Oui, c'est Dieu ma citadelle,","11":"le Dieu de mon amour vient à moi, Dieu me fera voir ceux qui me guettent.","12":"Ne les massacre pas, que mon peuple n'oublie, fais-en par ta puissance des errants, des pourchassés, ô notre bouclier, Seigneur!","13":"Péché sur leur bouche, la parole de leurs lèvres: qu'ils soient donc pris à leur orgueil, pour le blasphème, pour le mensonge qu'ils débitent.","14":"Détruis en ta colère, détruis, qu'ils ne soient plus! Et qu'on sache que c'est Dieu le Maître en Jacob, jusqu'aux bouts de la terre!","15":"Ils reviennent au soir, ils grognent comme un chien, ils rôdent par la ville;","16":"les voici en chasse pour manger, tant qu'ils n'ont pas leur soûl, ils grondent.","17":"Et moi, je chanterai ta force, j'acclamerai ton amour au matin; tu as été pour moi une citadelle, un refuge au jour de mon angoisse.","18":"O ma force, pour toi je jouerai; oui, c'est Dieu ma citadelle, le Dieu de mon amour."},"60":{"1":"Du maître de chant. Sur \"Un lys est le précepte.\" A mi-voix. De David. Pour apprendre.","2":"Quand il lutta avec Aram Naharayim et Aram de Coba, et que Joab revint pour battre Edom dans la vallée du Sel,12.000 hommes.","3":"Dieu, tu nous as rejetés, rompus, tu étais irrité, reviens à nous!","4":"Tu as fait trembler la terre, tu l'as fendue; guéris ses brèches, car elle chancelle!","5":"Tu en fis voir de dures à ton peuple, tu nous fis boire du vin de vertige;","6":"tu donnas à tes fidèles le signal de leur débâcle sous le tir de l'arc.","7":"Pour que soient délivrés tes bien-aimés, sauve par ta droite, et réponds-nous.","8":"Dieu a parlé dans son sanctuaire: \"J'exulte, je partage Sichem, j'arpente la vallée de Sukkot.","9":"\"A moi Galaad, à moi Manassé, Ephraïm, l'armure de ma tête, Juda, mon bâton de commandement,","10":"\"Moab, le bassin où je me lave! sur Edom, je jette ma sandale. Crie donc victoire contre moi, Philistie! \"","11":"Qui me mènera dans une ville forte, qui me conduira jusqu'en Edom,","12":"sinon toi, Dieu, qui nous as rejetés, Dieu qui ne sors plus avec nos armées?","13":"Porte-nous secours dans l'oppression: néant, le salut de l'homme!","14":"Avec Dieu, nous ferons des prouesses, et lui piétinera nos oppresseurs."},"61":{"1":"Du maître de chant. Sur les instruments à cordes. De David.","2":"Ecoute, ô Dieu, mes cris, sois attentif à ma prière.","3":"Du bout de la terre vers toi j'appelle, le coeur me manque. Au rocher qui s'élève loin de moi, conduis-moi.","4":"Car tu es pour moi un abri, une tour forte devant l'ennemi.","5":"Qu'à jamais je loge sous ta tente et m'abrite au couvert de tes ailes!","6":"Car toi, ô Dieu, tu écoutes mes voeux: tu accordes le domaine de ceux qui craignent ton nom.","7":"Aux jours du roi ajoute les jours; ses années: génération sur génération.","8":"Qu'il trône à jamais devant la face de Dieu! Assigne Amour et Fidélité pour le garder.","9":"Alors je jouerai sans fin pour ton nom, accomplissant mes voeux jour après jour."},"62":{"1":"Du maître de chant... Yedutûn. Psaume de David.","2":"En Dieu seul le repos pour mon âme, de lui mon salut;","3":"lui seul mon rocher, mon salut, ma citadelle, je ne bronche pas.","4":"Jusques à quand vous ruer sur un homme et l'abattre, vous tous, comme une muraille qui penche, une clôture qui croule?","5":"Duperie seulement, leurs projets, leur plaisir est de séduire; le mensonge à la bouche, ils bénissent, au-dedans ils maudissent.","6":"En Dieu seul repose-toi, mon âme, de lui vient mon espoir;","7":"lui seul mon rocher, mon salut, ma citadelle, je ne bronche pas;","8":"en Dieu mon salut et ma gloire, le rocher de ma force. En Dieu mon abri,","9":"fiez-vous à lui, peuple, en tout temps, devant lui épanchez votre coeur, Dieu nous est un abri!","10":"Un souffle seulement, les fils d'Adam, un mensonge, les fils d'homme; sur la balance s'ils montaient ensemble, ils seraient moins qu'un souffle.","11":"N'allez pas vous fier à la violence, vous essoufflant en rapines; aux richesses quand elles s'accroissent n'attachez pas votre coeur!","12":"Une fois Dieu a parlé, deux fois, j'ai entendu. Ceci: que la force est à Dieu,","13":"à toi, Seigneur, l'amour; et cela: toi, tu paies l'homme selon ses oeuvres."},"63":{"1":"Psaume de David. Quand il était dans le désert de Juda.","2":"Dieu, c'est toi mon Dieu, je te cherche, mon âme a soif de toi, après toi languit ma chair, terre sèche, altérée, sans eau.","3":"Oui, au sanctuaire je t'ai contemplé, voyant ta puissance et ta gloire.","4":"Meilleur que la vie, ton amour; mes lèvres diront ton éloge.","5":"Oui, je veux te bénir en ma vie, à ton nom, élever les mains;","6":"comme de graisse et de moelle se rassasie mon âme, lèvres jubilantes, louange en ma bouche.","7":"Quand je songe à toi sur ma couche, au long des veilles je médite sur toi,","8":"toi qui fus mon secours, et je jubile à l'ombre de tes ailes;","9":"mon âme se presse contre toi, ta droite me sert de soutien.","10":"Mais ceux qui poussent mon âme à sa perte, qu'ils descendent au profond de la terre!","11":"Qu'on les livre au tranchant de l'épée, qu'ils deviennent la part des chacals!","12":"Et le roi se réjouira en Dieu; qui jure par lui en tirera louange quand les menteurs auront la bouche fermée."},"64":{"1":"Du maître de chant. Psaume de David.","2":"Ecoute, ô Dieu, la voix de ma plainte, contre la peur de l'ennemi garde ma vie;","3":"à la bande des méchants cache-moi, à la meute des ouvriers de mal!","4":"Eux qui aiguisent leur langue comme une épée, ils ajustent leur flèche, parole amère,","5":"pour tirer en cachette sur l'innocent, ils tirent soudain et ne craignent rien.","6":"Ils s'encouragent dans leur méchante besogne, ils calculent pour tendre des pièges, ils disent: \"Qui les verra","7":"et scrutera nos secrets?\" Il les scrute, celui qui scrute le fond de l'homme et le coeur profond.","8":"Dieu a tiré une flèche, soudaines ont été leurs blessures;","9":"il les fit choir à cause de leur langue, tous ceux qui les voient hochent la tête.","10":"Tout homme alors craindra, il publiera l'oeuvre de Dieu, et son action, il la comprendra.","11":"Le juste aura sa joie en Yahvé et son refuge en lui; ils s'en loueront, tous les coeurs droits."},"65":{"1":"Du maître de chant. Psaume de David. Cantique.","2":"A toi la louange est due, ô Dieu, dans Sion; que pour toi le voeu soit acquitté:","3":"tu écoutes la prière. Jusqu'à toi vient toute chair","4":"avec ses oeuvres de péché; nos fautes sont plus fortes que nous, mais toi, tu les effaces.","5":"Heureux ton élu, ton familier, il demeure en tes parvis. Rassasions-nous des biens de ta maison, des choses saintes de ton Temple.","6":"Tu nous réponds en prodiges de justice, Dieu de notre salut, espoir des extrémités de la terre et des îles lointaines;","7":"toi qui maintiens les montagnes par ta force, qui te ceins de puissance,","8":"qui apaises le fracas des mers, le fracas de leurs flots. Les peuples sont en rumeur,","9":"pris d'effroi, les habitants des bouts du monde; tes signes font jubiler les portes du matin et du soir.","10":"Tu visites la terre et la fais regorger, tu la combles de richesses. Le ruisseau de Dieu est rempli d'eau, tu prépares les épis. Ainsi tu la prépares:","11":"arrosant ses sillons, aplanissant ses mottes, tu la détrempes d'averses, tu bénis son germe.","12":"Tu couronnes l'année de tes bontés, sur tes ornières la graisse ruisselle;","13":"ils ruissellent, les pacages du désert, les collines sont bordées d'allégresse;","14":"les prairies se revêtent de troupeaux, les vallées se drapent de froment, les cris de joie, ô les chansons!"},"66":{"1":"Du maître de chant. Cantique. Psaume. Acclamez Dieu, toute la terre,","2":"chantez à la gloire de son nom, rendez-lui sa louange de gloire,","3":"dites à Dieu: Que tu es redoutable! A la mesure de ta force, tes oeuvres. Tes ennemis se font tes flatteurs;","4":"toute la terre se prosterne devant toi, elle te chante, elle chante pour ton nom.","5":"Venez, voyez les gestes de Dieu, redoutable en hauts faits pour les fils d'Adam:","6":"il changea la mer en terre ferme, on passa le fleuve à pied sec. Là, notre joie en lui,","7":"souverain de puissance éternelle! Les yeux sur les nations, il veille, sur les rebelles pour qu'ils ne se relèvent.","8":"Peuples, bénissez notre Dieu, donnez une voix à sa louange,","9":"lui qui rend notre âme à la vie, et préserve nos pieds du faux pas.","10":"Tu nous as éprouvés, ô Dieu, épurés comme on épure l'argent;","11":"tu nous as fait tomber dans le filet, tu as mis sur nos reins une étreinte;","12":"tu fis chevaucher à notre tête un mortel; nous passions par le feu et par l'eau, puis tu nous as fait reprendre haleine.","13":"Je viens en ta maison avec des holocaustes, j'acquitte envers toi mes voeux,","14":"ceux qui m'ouvrirent les lèvres, que prononçait ma bouche en mon angoisse.","15":"Je t'offrirai de gras holocaustes avec la fumée des béliers, je le ferai avec des taureaux et des boucs.","16":"Venez, écoutez, que je raconte, vous tous les craignant-dieu, ce qu'il a fait pour mon âme.","17":"Vers lui ma bouche a crié, l'éloge déjà sur ma langue.","18":"Si j'avais vu de la malice en mon coeur, le Seigneur ne m'eût point écouté.","19":"Et pourtant Dieu m'a écouté, attentif à la voix de ma prière.","20":"Béni soit Dieu qui n'a pas écarté ma prière ni son amour loin de moi."},"67":{"1":"Du maître de chant. Sur les instruments à cordes.","2":"Que Dieu nous prenne en grâce et nous bénisse, faisant luire sur nous sa face!","3":"Sur la terre on connaîtra tes voies, parmi toutes les nations, ton salut.","4":"Que les peuples te rendent grâce, ô Dieu, que les peuples te rendent grâce tous!","5":"Que les nations jubilent et chantent, car tu juges le monde avec justice, tu juges les peuples en droiture, sur la terre tu gouvernes les nations.","6":"Que les peuples te rendent grâce, ô Dieu, que les peuples te rendent grâce tous!","7":"La terre a donné son produit, Dieu, notre Dieu, nous bénit.","8":"Que Dieu nous bénisse et qu'il soit craint de tous les lointains de la terre!"},"68":{"1":"Du maître de chant. De David.","2":"Que Dieu se lève, et ses ennemis se dispersent, et ses adversaires fuient devant sa face.","3":"Comme se dissipe la fumée, tu les dissipes; comme fond la cire en face du feu, ils périssent, les impies, en face de Dieu.","4":"Mais les justes jubilent devant la face de Dieu, ils exultent et dansent de joie.","5":"Chantez à Dieu, jouez pour son nom, frayez la route au Chevaucheur des nuées, jubilez en Yahvé, dansez devant sa face.","6":"Père des orphelins, justicier des veuves, c'est Dieu dans son lieu de sainteté;","7":"Dieu donne à l'isolé le séjour d'une maison, il ouvre aux captifs la porte du bonheur, mais les rebelles demeurent sur un sol aride.","8":"O Dieu, quand tu sortis à la face de ton peuple, quand tu foulas le désert,","9":"la terre trembla, les cieux mêmes fondirent en face de Dieu, en face de Dieu, le Dieu d'Israël.","10":"Tu répandis, ô Dieu, une pluie de largesses, ton héritage exténué, toi, tu l'affermis;","11":"ta famille trouva un séjour, celui-là qu'en ta bonté, ô Dieu, tu préparais au pauvre.","12":"Le Seigneur a donné un ordre, c'est l'annonce d'une armée innombrable.","13":"Et les chefs d'armée détalaient, détalaient, la belle du foyer partage le butin.","14":"Alors que vous reposez entre les deux murets, les ailes de la Colombe se couvrent d'argent, et ses plumes d'un reflet d'or vert;","15":"quand Shaddaï disperse les rois, c'est par elle qu'il neige sur le Mont-sombre.","16":"Montagne de Dieu, la montagne de Bashân! Montagne sourcilleuse, la montagne de Bashân!","17":"Pourquoi jalouser, montagnes sourcilleuses, la montagne que Dieu a désirée pour séjour? Oui, Yahvé y demeurera jusqu'à la fin.","18":"Les équipages de Dieu sont des milliers de myriades; le Seigneur est venu du Sinaï au sanctuaire.","19":"Tu as gravi la hauteur, capturé des captifs, reçu des hommes en tribut, même les rebelles, pour que Yahvé Dieu ait une demeure.","20":"Béni soit le Seigneur de jour en jour! Il prend charge de nous, le Dieu de notre salut.","21":"Le Dieu que nous avons est un Dieu de délivrances, au Seigneur Yahvé sont les issues de la mort;","22":"mais Dieu défonce la tête de ses ennemis, le crâne chevelu du criminel qui rôde.","23":"Le Seigneur a dit: \"De Bashân je fais revenir, je fais revenir des abîmes de la mer,","24":"afin que tu enfonces ton pied dans le sang, que la langue de tes chiens ait sa part d'ennemis.\"","25":"On a vu tes processions, ô Dieu, les processions de mon Dieu, de mon roi, au sanctuaire:","26":"les chantres marchaient devant, les musiciens derrière, les jeunes filles au milieu, battant du tambourin.","27":"En choeurs, ils bénissaient Dieu: c'est Yahvé, dès l'origine d'Israël.","28":"Benjamin était là, le cadet ouvrant la marche; les princes de Juda en robes multicolores, les princes de Zabulon, les princes de Nephtali.","29":"Commande, ô mon Dieu, selon ta puissance, la puissance, ô Dieu, que tu as mise en oeuvre pour nous,","30":"depuis ton Temple au-dessus de Jérusalem. Vers toi viendront les rois, apportant des présents.","31":"Menace la bête des roseaux, la bande de taureaux avec les peuples de veaux, qui s'humilie, avec des lingots d'argent! Disperse les peuples qui aiment la guerre.","32":"Depuis l'Egypte, des grands viendront, l'Ethiopie tendra les mains vers Dieu.","33":"Royaumes de la terre, chantez à Dieu, jouez pour","34":"le Chevaucheur des cieux, des cieux antiques.","35":"Reconnaissez la puissance de Dieu. Sur Israël sa splendeur, dans les nues sa puissance:","36":"redoutable est Dieu depuis son sanctuaire. C'est lui, le Dieu d'Israël, qui donne au peuple force et puissance. Béni soit Dieu!"},"69":{"1":"Du maître de chant. Sur l'air: Des lys... De David.","2":"Sauve-moi, ô Dieu, car les eaux me sont entrées jusqu'à l'âme.","3":"J'enfonce dans la bourbe du gouffre, et rien qui tienne; je suis entré dans l'abîme des eaux et le flot me submerge.","4":"Je m'épuise à crier, ma gorge brûle, mes yeux sont consumés d'attendre mon Dieu.","5":"Plus nombreux que les cheveux de la tête, ceux qui me haïssent sans cause; ils sont puissants ceux qui me détruisent, ceux qui m'en veulent à tort. (Ce que je n'ai pas pris, devrai-je le rendre?)","6":"O Dieu, tu sais ma folie, mes offenses sont à nu devant toi.","7":"Qu'ils ne rougissent pas de moi, ceux qui t'espèrent, Yahvé Sabaot! Qu'ils n'aient pas honte de moi, ceux qui te cherchent, Dieu d'Israël!","8":"C'est pour toi que je souffre l'insulte, que la honte me couvre le visage,","9":"que je suis un étranger pour mes frères, un inconnu pour les fils de ma mère;","10":"car le zèle de ta maison me dévore, l'insulte de tes insulteurs tombe sur moi.","11":"Que j'afflige mon âme par le jeûne et l'on m'en fait un sujet d'insulte;","12":"que je prenne un sac pour vêtement et pour eux je deviens une fable,","13":"le conte des gens assis à la porte et la chanson des buveurs de boissons fortes.","14":"Et moi, t'adressant ma prière, Yahvé, au temps favorable, en ton grand amour, Dieu, réponds-moi en la vérité de ton salut.","15":"Tire-moi du bourbier, que je n'enfonce, que j'échappe à mes adversaires, à l'abîme des eaux!","16":"Que le flux des eaux ne me submerge, que le gouffre ne me dévore, que la bouche de la fosse ne me happe!","17":"Réponds-moi, Yahvé: car ton amour est bonté; en ta grande tendresse regarde vers moi;","18":"à ton serviteur ne cache point ta face, l'oppression est sur moi, vite, réponds-moi;","19":"approche de mon âme, venge-la, à cause de mes ennemis, rachète-moi.","20":"Toi, tu connais mon insulte, ma honte et mon affront. Devant toi tous mes oppresseurs.","21":"L'insulte m'a brisé le coeur, jusqu'à défaillir. J'espérais la compassion, mais en vain, des consolateurs, et je n'en ai pas trouvé.","22":"Pour nourriture ils m'ont donné du poison, dans ma soif ils m'abreuvaient de vinaigre.","23":"Que devant eux leur table soit un piège et leur abondance un traquenard;","24":"que leurs yeux s'enténèbrent pour ne plus voir, fais qu'à tout instant les reins leur manquent!","25":"Déverse sur eux ton courroux, que le feu de ta colère les atteigne;","26":"que leur enclos devienne un désert, que leurs tentes soient sans habitants:","27":"ils s'acharnent sur celui que tu frappes, ils rajoutent aux blessures de ta victime.","28":"Charge-les, tort sur tort, qu'ils n'aient plus d'accès à ta justice;","29":"qu'ils soient rayés du livre de vie, retranchés du compte des justes.","30":"Et moi, courbé, blessé, que ton salut, Dieu, me redresse!","31":"Je louerai le nom de Dieu par un cantique, je le magnifierai par l'action de grâces;","32":"cela plaît à Yahvé plus qu'un taureau, une forte bête avec corne et sabot.","33":"Ils ont vu, les humbles, ils jubilent; chercheurs de Dieu, que vive votre coeur!","34":"Car Yahvé exauce les pauvres, il n'a pas méprisé ses captifs.","35":"Que l'acclament le ciel et la terre, la mer et tout ce qui s'y remue!","36":"Car Dieu sauvera Sion, il rebâtira les villes de Juda, là, on habitera, on possédera;","37":"la lignée de ses serviteurs en hérite et les amants de son nom y demeurent."},"70":{"1":"Du maître de chant. De David. Pour commémorer.","2":"O Dieu, vite à mon secours, Yahvé, à mon aide!","3":"Honte et déshonneur sur ceux-là qui cherchent mon âme! Arrière! honnis soient-ils, ceux que flatte mon malheur;","4":"qu'ils reculent couverts de honte, ceux qui disent: Ha! Ha!","5":"Joie en toi et réjouissance à tous ceux qui te cherchent: qu'ils redisent toujours: \"Dieu est grand! \" ceux qui aiment ton salut!","6":"Et moi, pauvre et malheureux! ô Dieu, viens vite! Toi, mon secours et mon sauveur, Yahvé, ne tarde pas!"},"71":{"1":"En toi, Yahvé, j'ai mon abri, sur moi pas de honte à jamais!","2":"En ta justice défends-moi, délivre-moi, tends vers moi l'oreille et sauve-moi.","3":"Sois pour moi un roc hospitalier, toujours accessible; tu as décidé de me sauver, car mon rocher, mon rempart, c'est toi.","4":"Mon Dieu, délivre-moi de la main de l'impie, de la poigne du fourbe et du violent.","5":"Car c'est toi mon espoir, Seigneur, Yahvé, ma foi dès ma jeunesse.","6":"Sur toi j'ai mon appui dès le sein, toi ma part dès les entrailles de ma mère, en toi ma louange sans relâche.","7":"Pour beaucoup je tenais du prodige, mais toi, tu es mon sûr abri.","8":"Ma bouche est remplie de ta louange, tout le jour, de ta splendeur.","9":"Ne me rejette pas au temps de ma vieillesse, quand décline ma vigueur, ne m'abandonne pas.","10":"Car mes ennemis parlent de moi, ceux qui guettent mon âme se concertent:","11":"\"Dieu l'a abandonné, pourchassez-le, empoignez-le, il n'a personne pour le défendre.\"","12":"Dieu, ne sois pas loin de moi, mon Dieu, vite à mon aide.","13":"Honte et ruine sur ceux-là qui attaquent mon âme; que l'insulte et l'infamie les couvrent, ceux qui cherchent mon malheur!","14":"Et moi, sans relâche espérant, j'ajouterai à ta louange;","15":"ma bouche racontera ta justice, tout le jour, ton salut.","16":"Je viendrai dans la puissance de Yahvé, pour rappeler ta justice, la seule.","17":"O Dieu, tu m'as instruit dès ma jeunesse, et jusqu'ici j'annonce tes merveilles.","18":"Or, vieilli, chargé d'années, ô Dieu, ne m'abandonne pas, que j'annonce ton bras aux âges à venir, ta puissance","19":"et ta justice, ô Dieu, jusqu'aux nues! Toi qui as fait de grandes choses, ô Dieu, qui est comme toi?","20":"Toi qui m'as fait tant voir de maux et de détresses, tu reviendras me faire vivre. Tu reviendras me tirer des abîmes de la terre,","21":"tu nourriras mon grand âge, tu viendras me consoler.","22":"Or moi, je te rendrai grâce sur la lyre, en ta vérité, mon Dieu, je jouerai pour toi sur la harpe, Saint d'Israël.","23":"Que jubilent mes lèvres, quand je jouerai pour toi, et mon âme que tu as rachetée!","24":"Or ma langue tout le jour murmure ta justice: honte et déshonneur sur ceux-là qui cherchent mon malheur!"},"72":{"1":"De Salomon. O Dieu, donne au roi ton jugement, au fils de roi ta justice,","2":"qu'il rende à ton peuple sentence juste et jugement à tes petits.","3":"Montagnes, apportez, et vous collines, la paix au peuple. Avec justice","4":"il jugera le petit peuple, il sauvera les fils de pauvres, il écrasera leurs bourreaux.","5":"Il durera sous le soleil et la lune siècle après siècle;","6":"il descendra comme la pluie sur le regain, comme la bruine mouillant la terre.","7":"En ses jours justice fleurira et grande paix jusqu'à la fin des lunes;","8":"il dominera de la mer à la mer, du Fleuve jusqu'aux bouts de la terre.","9":"Devant lui se courbera la Bête, ses ennemis lécheront la poussière;","10":"les rois de Tarsis et des îles rendront tribut. Les rois de Saba et de Seba feront offrande;","11":"tous les rois se prosterneront devant lui, tous les païens le serviront.","12":"Car il délivre le pauvre qui appelle et le petit qui est sans aide;","13":"compatissant au faible et au pauvre, il sauve l'âme des pauvres.","14":"De l'oppression, de la violence, il rachète leur âme, leur sang est précieux à ses yeux.","15":"(Qu'il vive et que lui soit donné l'or de Saba! ) On priera pour lui sans relâche, tout le jour, on le bénira.","16":"Foisonne le froment sur la terre, qu'il ondule au sommet des montagnes, comme le Liban quand il éveille ses fruits et ses fleurs, comme l'herbe de la terre!","17":"Soit béni son nom à jamais, qu'il dure sous le soleil! Bénies seront en lui toutes les races de la terre, que tous les païens le disent bienheureux!","18":"Béni soit Yahvé, le Dieu d'Israël, qui seul a fait des merveilles;","19":"béni soit à jamais son nom de gloire, toute la terre soit remplie de sa gloire! Amen! Amen!","20":"Fin des prières de David, fils de Jessé."},"73":{"1":"D'Asaph. Mais enfin, Dieu est bon pour Israël, le Seigneur pour les hommes au coeur pur.","2":"Un peu plus, mon pied bronchait, un rien, et mes pas glissaient,","3":"envieux que j'étais des arrogants en voyant le bien-être des impies.","4":"Pour eux, point de tourments, rien n'entame leur riche prestance;","5":"de la peine des hommes ils sont absents, avec Adam ils ne sont point frappés.","6":"C'est pourquoi l'orgueil est leur collier, la violence, le vêtement qui les couvre;","7":"la malice leur sort de la graisse, l'artifice leur déborde du coeur.","8":"Ils ricanent, ils prônent le mal, hautement ils prônent la force;","9":"leur bouche s'arroge le ciel et leur langue va bon train sur la terre.","10":"C'est pourquoi mon peuple va vers eux: des eaux d'abondance leur adviennent.","11":"Ils disent: \"Comment Dieu saurait-il? Chez le Très-Haut y a-t-il connaissance?\"","12":"Voyez-le: ce sont des impies, et, tranquilles toujours, ils entassent!","13":"Mais enfin pourquoi aurais-je gardé un coeur pur, lavant mes mains en l'innocence?","14":"Quand j'étais frappé tout le jour, et j'avais mon châtiment chaque matin,","15":"si j'avais dit: \"Je vais parler comme eux\", j'aurais trahi la race de tes fils.","16":"Alors j'ai réfléchi pour comprendre: quelle peine c'était à mes yeux!","17":"jusqu'au jour où j'entrai aux sanctuaires divins, où je pénétrai leur destin.","18":"Mais enfin, tu en as fait des choses trompeuses, tu les fais tomber dans le chaos.","19":"Ah! que soudain ils font horreur, disparus, achevés par l'épouvante!","20":"Comme un songe au réveil, Seigneur, en t'éveillant, tu méprises leur image.","21":"Alors que s'aigrissait mon coeur et que j'avais les reins percés,","22":"moi, stupide, je ne comprenais pas, j'étais une brute près de toi.","23":"Et moi, qui restais près de toi, tu m'as saisi par ma main droite;","24":"par ton conseil tu me conduiras, et derrière la gloire tu m'attireras.","25":"Qui donc aurais-je dans le ciel? Avec toi, je suis sans désir sur la terre.","26":"Et ma chair et mon coeur sont consumés: roc de mon coeur, ma part, Dieu à jamais!","27":"Voici: qui s'éloigne de toi périra, tu extirpes ceux qui te sont adultères.","28":"Pour moi, approcher Dieu est mon bien, j'ai placé dans le Seigneur mon refuge, afin de raconter toutes tes oeuvres."},"74":{"1":"Poème. D'Asaph. Pourquoi, ô Dieu, rejeter jusqu'à la fin, fumer de colère contre le troupeau de ton bercail?","2":"Rappelle-toi ton assemblée que tu as acquise dès l'origine, que tu rachetas, tribu de ton héritage, et ce mont Sion où tu fis ta demeure.","3":"Elève tes pas vers ce chaos sans fin: il a tout saccagé, l'ennemi, au sanctuaire;","4":"dans le lieu de tes assemblées ont rugi tes adversaires, ils ont mis leurs insignes au fronton de l'entrée, des insignes","5":"qu'on ne connaissait pas. Leurs cognées en plein bois,","6":"abattant les vantaux, et par la hache et par la masse ils martelaient;","7":"ils ont livré au feu ton sanctuaire, profané jusqu'à terre la demeure de ton nom.","8":"Ils ont dit en leur coeur: \"Ecrasons-les d'un coup! \" Ils ont brûlé dans le pays tout lieu d'assemblée sainte.","9":"Nos signes ont cessé, il n'est plus de prophètes, et nul parmi nous ne sait jusques à quand.","10":"Jusques à quand, ô Dieu, blasphémera l'oppresseur? L'ennemi va-t-il outrager ton nom jusqu'à la fin?","11":"Pourquoi retires-tu ta main, tiens-tu ta droite cachée en ton sein?","12":"Pourtant, ô Dieu, mon roi dès l'origine, l'auteur des délivrances au milieu du pays,","13":"toi qui fendis la mer par ta puissance, qui brisas les têtes des monstres sur les eaux;","14":"toi qui fracassas les têtes de Léviathan pour en faire la pâture des bêtes sauvages,","15":"toi qui ouvris la source et le torrent, toi qui desséchas des fleuves intarissables;","16":"à toi le jour, et à toi la nuit, toi qui agenças la lumière et le soleil,","17":"toi qui posas toutes les limites de la terre, l'été et l'hiver, c'est toi qui les formas.","18":"Rappelle-toi, Yahvé, l'ennemi blasphème, un peuple insensé outrage ton nom.","19":"Ne livre pas à la bête l'âme de ta tourterelle, la vie de tes malheureux, ne l'oublie pas jusqu'à la fin.","20":"Regarde vers l'alliance. Ils sont pleins, les antres du pays, repaires de violence.","21":"Que l'opprimé ne rentre pas couvert de honte, que le pauvre et le malheureux louent ton nom!","22":"Lève-toi, ô Dieu, plaide ta cause, rappelle-toi l'insensé qui te blasphème tout le jour!","23":"N'oublie pas le vacarme de tes adversaires, la clameur de tes ennemis, qui va toujours montant!"},"75":{"1":"Du maître de chant. \"Ne détruis pas.\" Psaume. D'Asaph. Cantique.","2":"A toi nous rendons grâce, ô Dieu, nous rendons grâce, en invoquant ton nom, en racontant tes merveilles.","3":"\"Au moment que j'aurai décidé, je ferai, moi, droite justice;","4":"la terre s'effondre et tous ses habitants; j'ai fixé, moi, ses colonnes.","5":"\"J'ai dit aux arrogants: Pas d'arrogance! aux impies: Ne levez pas le front,","6":"ne levez pas si haut votre front, ne parlez pas en raidissant l'échine.\"","7":"Car ce n'est plus du levant au couchant, ce n'est plus au désert des montagnes","8":"qu'en vérité, Dieu le juge, abaisse l'un ou élève l'autre:","9":"Yahvé a en main une coupe, et c'est de vin fermenté qu'est rempli le breuvage; il en versera, ils en suceront la lie, ils boiront, tous les impies de la terre.","10":"Et moi, j'annoncerai à jamais, je jouerai pour le Dieu de Jacob;","11":"je briserai la vigueur des impies; et la vigueur du juste se dressera."},"76":{"1":"Du maître de chant. Sur les instruments à cordes. Psaume. D'Asaph. Cantique.","2":"En Juda Dieu est connu, en Israël grand est son nom;","3":"sa tente s'est fixée en Salem et sa demeure en Sion;","4":"là, il a brisé les éclairs de l'arc, le bouclier, l'épée et la guerre.","5":"Lumineux que tu es, et célèbre pour les monceaux de butin","6":"qu'on leur a pris; les braves ont dormi leur sommeil, tous ces guerriers, les bras leur ont manqué;","7":"sous ta menace, Dieu de Jacob, char et cheval se sont figés.","8":"Toi, toi le terrible! Qui tiendra devant ta face, sous le coup de ta fureur?","9":"Des cieux tu fais entendre la sentence, la terre a peur et se tait","10":"quand Dieu se lève pour le jugement, pour sauver tous les humbles de la terre.","11":"La colère de l'homme te rend gloire, des réchappés de la Colère, tu te ceindras;","12":"faites des voeux, acquittez-les à Yahvé votre Dieu, ceux qui l'entourent, faites offrande au Terrible;","13":"il coupe le souffle des princes, terrible aux rois de la terre."},"77":{"1":"Du maître de chant... Yedutûn. D'Asaph.","2":"Vers Dieu ma voix: je crie, vers Dieu ma voix: il m'entend.","3":"Au jour d'angoisse j'ai cherché le Seigneur; la nuit, j'ai tendu la main sans relâche, mon âme a refusé d'être consolée.","4":"Je me souviens de Dieu et je gémis, je médite et le souffle me manque.","5":"Tu as retenu les paupières de mes yeux, je suis troublé, je ne puis parler;","6":"j'ai pensé aux jours d'autrefois, d'années séculaires","7":"je me souviens; je murmure dans la nuit en mon coeur, je médite et mon esprit interroge:","8":"Est-ce pour les siècles que le Seigneur rejette, qu'il cesse de se montrer favorable?","9":"Son amour est-il épuisé jusqu'à la fin, achevée pour les âges des âges la Parole?","10":"Est-ce que Dieu oublie d'avoir pitié, ou de colère ferme-t-il ses entrailles?","11":"Et je dis: \"Voilà ce qui me blesse: elle est changée, la droite du Très-Haut.\"","12":"Je me souviens des hauts faits de Yahvé, oui, je me souviens d'autrefois, de tes merveilles,","13":"je me murmure toute ton oeuvre, et sur tes hauts faits je médite:","14":"O Dieu, saintes sont tes voies! quel dieu est grand comme Dieu?","15":"Toi, le Dieu qui fait merveille, tu fis savoir parmi les peuples ta force;","16":"par ton bras tu rachetas ton peuple, les enfants de Jacob et de Joseph.","17":"Les eaux te virent, ô Dieu, les eaux te virent et furent bouleversées, les abîmes aussi s'agitaient.","18":"Les nuées déversèrent les eaux, les nuages donnèrent de la voix, tes flèches aussi filaient.","19":"Voix de ton tonnerre en son roulement. Tes éclairs illuminaient le monde, la terre s'agitait et tremblait.","20":"Sur la mer fut ton chemin, ton sentier sur les eaux innombrables. Et tes traces, nul ne les connut.","21":"Tu guidas comme un troupeau ton peuple par la main de Moïse et d'Aaron."},"78":{"1":"Poème. D'Asaph. Ecoute, ô mon peuple, ma loi; tends l'oreille aux paroles de ma bouche;","2":"j'ouvre la bouche en paraboles, j'évoque du passé les mystères.","3":"Nous l'avons entendu et connu, nos pères nous l'ont raconté;","4":"nous ne le tairons pas à leurs enfants, nous le raconterons à la génération qui vient: les titres de Yahvé et sa puissance, ses merveilles telles qu'il les fit;","5":"il établit un témoignage en Jacob, il mit une loi en Israël; il avait commandé à nos pères de le faire connaître à leurs enfants,","6":"que la génération qui vient le connaisse, les enfants qui viendront à naître. Qu'ils se lèvent, qu'ils racontent à leurs enfants,","7":"qu'ils mettent en Dieu leur espoir, qu'ils n'oublient pas les hauts faits de Dieu, et ses commandements, qu'ils les observent;","8":"qu'ils ne soient pas, à l'exemple de leurs pères, une génération de révolte et de bravade, génération qui n'a point le coeur sûr et dont l'esprit n'est point fidèle à Dieu.","9":"Les fils d'Ephraïm, tireurs d'arc, se retournèrent, le jour du combat;","10":"ils ne gardaient pas l'alliance de Dieu, ils refusaient de marcher dans sa loi;","11":"ils avaient oublié ses hauts faits, ses merveilles qu'il leur donna de voir:","12":"devant leurs pères il fit merveille en terre d'Egypte, aux champs de Tanis.","13":"Il fendit la mer et les transporta, il dressa les eaux comme une digue;","14":"il les guida de jour par la nuée, par la lueur d'un feu toute la nuit;","15":"il fendit les rochers au désert, il les abreuva à la mesure du grand abîme;","16":"du roc il fit sortir des ruisseaux et descendre les eaux en torrents.","17":"Mais de plus belle ils péchaient contre lui et bravaient le Très-Haut dans le lieu sec;","18":"ils tentèrent Dieu dans leur coeur, demandant à manger à leur faim.","19":"Or ils parlèrent contre Dieu; ils dirent: \"Est-il capable, Dieu, de dresser une table au désert?","20":"\"Voici qu'il frappe le rocher, les eaux coulent, les torrents s'échappent: mais du pain, est-il capable d'en donner, ou de fournir de la viande à son peuple?\"","21":"Alors Yahvé entendit, il s'emporta; un feu flamba contre Jacob, et puis la Colère monta contre Israël,","22":"car ils étaient sans foi en Dieu, ils étaient sans confiance en son salut.","23":"Aux nuées d'en haut il commanda, il ouvrit les battants des cieux;","24":"pour les nourrir il fit pleuvoir la manne, il leur donna le froment des cieux;","25":"du pain des Forts l'homme se nourrit, il leur envoya des vivres à satiété.","26":"Il fit lever dans les cieux le vent d'est, il fit venir par sa puissance le vent du sud,","27":"il fit pleuvoir sur eux la viande comme poussière, la volaille comme sable des mers,","28":"il en fit tomber au milieu de son camp, tout autour de sa demeure.","29":"Ils mangèrent et furent bien rassasiés, il leur servit ce qu'ils désiraient;","30":"eux n'étaient pas revenus de leur désir, leur manger encore en la bouche,","31":"que la colère de Dieu monta contre eux: il massacrait parmi les robustes, abattait les cadets d'Israël.","32":"Malgré tout, ils péchèrent encore, ils n'eurent pas foi en ses merveilles.","33":"Il consuma en un souffle leurs jours, leurs années en une panique.","34":"Quand il les massacrait, ils le cherchaient, ils revenaient, s'empressaient près de lui.","35":"Ils se souvenaient: Dieu leur rocher, Dieu le Très-Haut, leur rédempteur!","36":"Mais ils le flattaient de leur bouche, mais de leur langue ils lui mentaient,","37":"leur coeur n'était pas sûr envers lui, ils étaient sans foi en son alliance.","38":"Lui alors, dans sa tendresse, effaçait les torts au lieu de dévaster; sans se lasser, il revenait de sa colère au lieu de réveiller tout son courroux.","39":"Il se souvenait: eux, cette chair, souffle qui s'en va et ne revient pas.","40":"Que de fois ils le bravèrent au désert, l'offensèrent parmi les solitudes!","41":"Ils revenaient tenter Dieu, affliger le Saint d'Israël,","42":"sans nul souvenir de sa main, ni du jour qu'il les sauva de l'adversaire.","43":"Lui qui en Egypte mit ses signes, ses miracles aux champs de Tanis,","44":"fit tourner en sang leurs fleuves, leurs ruisseaux pour les priver de boire.","45":"Il leur envoya des taons qui dévoraient, des grenouilles qui les infestaient;","46":"il livra au criquet leurs récoltes et leur labeur à la sauterelle;","47":"il massacra par la grêle leur vigne et leurs sycomores par la gelée;","48":"il remit à la grêle leur bétail et leurs troupeaux aux éclairs.","49":"Il lâcha sur eux le feu de sa colère, emportement et fureur et détresse, un envoi d'anges de malheur;","50":"il fraya un sentier à sa colère. Il n'exempta pas leur âme de la mort, à la peste il remit leur vie;","51":"il frappa tout premier-né en Egypte, la fleur de la race aux tentes de Cham.","52":"Il poussa comme des brebis son peuple, les mena comme un troupeau dans le désert;","53":"il les guida sûrement, ils furent sans crainte, leurs ennemis, la mer les recouvrit.","54":"Il les amena vers son saint territoire, la montagne que sa droite a conquise;","55":"il chassa devant eux les païens, il leur marqua au cordeau un héritage; il installa sous leurs tentes les tribus d'Israël.","56":"Ils tentaient, ils bravaient Dieu le Très-Haut, se refusaient à garder ses témoignages;","57":"ils déviaient, ils trahissaient comme leurs pères, se retournaient comme un arc infidèle;","58":"ils l'indignaient avec leurs hauts lieux, par leurs idoles ils le rendaient jaloux.","59":"Dieu entendit et s'emporta, il rejeta tout à fait Israël;","60":"il délaissa la demeure de Silo, la tente où il demeurait chez les hommes.","61":"Il livra sa force à la captivité, aux mains de l'ennemi sa splendeur;","62":"il remit son peuple à l'épée, contre son héritage il s'emporta.","63":"Ses cadets, le feu les dévora, ses vierges n'eurent pas de chant de noces;","64":"ses prêtres tombèrent sous l'épée, ses veuves ne firent pas de lamentations.","65":"Il s'éveilla comme un dormeur, le Seigneur, comme un vaillant terrassé par le vin,","66":"il frappa ses ennemis au dos, les livra pour toujours à la honte.","67":"Il rejeta la tente de Joseph, il n'élut pas la tribu d'Ephraïm;","68":"il élut la tribu de Juda, la montagne de Sion qu'il aime.","69":"Il bâtit comme les hauteurs son sanctuaire, comme la terre qu'il fonda pour toujours.","70":"Il élut David son serviteur, il le tira des parcs à moutons,","71":"de derrière les brebis mères il l'appela pour paître Jacob son peuple et Israël son héritage;","72":"il les paissait d'un coeur parfait, et d'une main sage les guidait."},"79":{"1":"D'Asaph. Dieu, ils sont venus, les païens, dans ton héritage, ils ont souillé ton Temple sacré; ils ont fait de Jérusalem un tas de ruines,","2":"ils ont livré le cadavre de tes serviteurs en pâture à l'oiseau des cieux, la chair des tiens aux bêtes de la terre.","3":"Ils ont versé le sang comme de l'eau alentour de Jérusalem, et pas un fossoyeur.","4":"Nous voici l'insulte de nos voisins, fable et risée de notre entourage.","5":"Jusques à quand, Yahvé, ta colère? Jusqu'à la fin? Ta jalousie brûlera-t-elle comme un feu?","6":"Déverse ta fureur sur les païens, eux qui ne te connaissent pas, et sur les royaumes, ceux-là qui n'invoquent pas ton nom.","7":"Car ils ont dévoré Jacob et dévasté sa demeure.","8":"Ne retiens pas contre nous les fautes des ancêtres, hâte-toi, préviens-nous par ta tendresse, nous sommes à bout de force;","9":"aide-nous, Dieu de notre salut, par égard pour la gloire de ton nom; efface, Yahvé, nos péchés, délivre-nous, à cause de ton nom.","10":"Pourquoi les païens diraient-ils: \"Où est leur Dieu?\" Que sous nos yeux les païens connaissent la vengeance du sang de tes serviteurs, qui fut versé!","11":"Que vienne devant toi la plainte du captif, par ton bras puissant, épargne les clients de la mort!","12":"Fais retomber sept fois sur nos voisins, à pleine mesure, leur insulte, l'insulte qu'ils t'ont faite, Seigneur.","13":"Et nous, ton peuple, le troupeau de ton bercail, nous te rendrons grâce à jamais et d'âge en âge publierons ta louange."},"80":{"1":"Du maître de chant. Sur l'air: Des lys sont les préceptes. D'Asaph.","2":"Pasteur d'Israël, écoute, toi qui mènes Joseph comme un troupeau; toi qui sièges sur les Chérubins, resplendis","3":"devant Ephraïm, Benjamin et Manassé, réveille ta vaillance et viens à notre secours.","4":"Dieu, fais-nous revenir, fais luire ta face et nous serons sauvés.","5":"Jusques à quand, Yahvé Dieu Sabaot, prendras-tu feu contre la prière de ton peuple?","6":"Tu l'as nourri d'un pain de larmes, abreuvé de larmes à triple mesure;","7":"tu fais de nous une question pour nos voisins et nos ennemis se moquent de nous.","8":"Dieu Sabaot, fais-nous revenir, fais luire ta face et nous serons sauvés.","9":"Il était une vigne: tu l'arraches d'Egypte, tu chasses des nations pour la planter;","10":"devant elle tu fais place nette, elle prend racine et remplit le pays.","11":"Les montagnes étaient couvertes de son ombre, et de ses pampres les cèdres de Dieu;","12":"elle étendait ses sarments jusqu'à la mer et du côté du Fleuve ses rejetons.","13":"Pourquoi as-tu rompu ses clôtures, et tout passant du chemin la grappille,","14":"le sanglier des forêts la ravage et la bête des champs la dévore?","15":"Dieu Sabaot, reviens enfin, observe des cieux et vois, visite cette vigne:","16":"protège-la, celle que ta droite a plantée.","17":"Ils l'ont brûlée par le feu comme une ordure, au reproche de ta face ils périront.","18":"Ta main soit sur l'homme de ta droite, le fils d'Adam que tu as confirmé!","19":"Jamais plus nous n'irons loin de toi; rends-nous la vie, qu'on invoque ton nom.","20":"Yahvé Dieu Sabaot, fais-nous revenir, fais luire ta face et nous serons sauvés."},"81":{"1":"Du maître de chant. Sur la... de Gat. D'Asaph.","2":"Criez de joie pour Dieu notre force, acclamez le Dieu de Jacob.","3":"Ouvrez le concert, frappez le tambourin, la douce harpe ainsi que la lyre;","4":"sonnez du cor au mois nouveau, à la pleine lune, au jour de notre fête.","5":"Car Israël a une loi, un jugement du Dieu de Jacob,","6":"un témoignage qu'il mit en Joseph quand il sortit contre la terre d'Egypte. Un langage inconnu se fait entendre:","7":"\"Du fardeau j'ai déchargé son épaule, ses mains ont lâché le couffin;","8":"dans la détresse tu as crié, je t'ai sauvé. Je te répondis caché dans l'orage, je t'éprouvai aux eaux de Meriba.","9":"Ecoute, mon peuple, je t'adjure, ô Israël, si tu pouvais m'écouter!","10":"Qu'il n'y ait point chez toi un dieu d'emprunt, n'adore pas un dieu étranger;","11":"c'est moi, Yahvé, ton Dieu, qui t'ai fait monter de la terre d'Egypte, ouvre large ta bouche, et je l'emplirai.","12":"Mon peuple n'a pas écouté ma voix, Israël ne s'est pas rendu à moi;","13":"je les laissai à leur coeur endurci, ils marchaient ne suivant que leur conseil.","14":"Ah! si mon peuple m'écoutait, si dans mes voies marchait Israël,","15":"en un instant j'abattrais ses adversaires et contre ses oppresseurs tournerais ma main.","16":"Les ennemis de Yahvé l'aduleraient, et leur temps serait à jamais révolu.","17":"Je l'aurais nourri de la fleur du froment, je t'aurais rassasié avec le miel du rocher.\""},"82":{"1":"D'Asaph. Dieu se dresse au conseil divin, au milieu des dieux il juge:","2":"\"Jusques à quand jugerez-vous faussement, soutiendrez-vous les prestiges des impies?","3":"Jugez pour le faible et l'orphelin, au malheureux, à l'indigent rendez justice;","4":"libérez le faible et le pauvre, de la main des impies délivrez-les.","5":"Sans savoir, sans comprendre, ils vont par la ténèbre, toute l'assise de la terre s'ébranle.","6":"Moi, j'ai dit: Vous, des dieux, des fils du Très-Haut, vous tous?","7":"Mais non! comme l'homme vous mourrez, comme un seul, ô princes, vous tomberez.\"","8":"Lève-toi, ô Dieu, juge la terre, car tu domines sur toutes les nations."},"83":{"1":"Cantique. D'Asaph.","2":"O Dieu, ne reste pas muet, plus de repos, plus de silence, ô Dieu!","3":"Voici, tes adversaires grondent, tes ennemis lèvent la tête.","4":"Contre ton peuple ils trament un complot, conspirent contre tes protégés","5":"et disent: \"Venez, retranchons-les des nations, qu'on n'ait plus souvenir du nom d'Israël! \"","6":"Ils conspirent tous d'un seul coeur, contre toi ils scellent une alliance:","7":"les tentes d'Edom et les Ismaélites, Moab et les Hagrites,","8":"Gébal, Ammon, Amaleq, la Philistie avec les gens de Tyr;","9":"même Assur s'est joint à eux, il prête main-forte aux fils de Lot.","10":"Fais d'eux comme de Madiân et de Sisera, comme de Yabîn au torrent de Qishôn;","11":"ils furent détruits à En-Dor, ils ont servi de fumier à la glèbe.","12":"Traite leurs princes comme Oreb et Zéeb, comme Zébah et Calmunna, tous leurs chefs,","13":"eux qui disaient: A nous l'empire sur les demeures de Dieu!","14":"Mon Dieu, traite-les comme une roue d'acanthe, comme un fétu en proie au vent.","15":"Comme un feu dévore une forêt, comme la flamme embrase les montagnes,","16":"ainsi poursuis-les de ta bourrasque, par ton ouragan remplis-les d'épouvante.","17":"Couvre leur face de honte, qu'ils cherchent ton nom, Yahvé!","18":"Sur eux la honte et l'épouvante pour toujours, la confusion et la perdition,","19":"et qu'ils le sachent: toi seul as nom Yahvé, Très-Haut sur toute la terre."},"84":{"1":"Du maître de choeur. Sur la... de Gat. Des fils de Coré.","2":"Que tes demeures sont désirables, Yahvé Sabaot!","3":"Mon âme soupire et languit après les parvis de Yahvé, mon coeur et ma chair crient de joie vers le Dieu vivant.","4":"Le passereau même a trouvé une maison, et l'hirondelle un nid pour elle, où elle pose ses petits: tes autels, Yahvé Sabaot, mon Roi et mon Dieu.","5":"Heureux les habitants de ta maison, ils te louent sans cesse.","6":"Heureux les hommes dont la force est en toi, qui gardent au coeur les montées.","7":"Quand ils passent au val du Baumier, où l'on ménage une fontaine, surcroît de bénédiction, la pluie d'automne les enveloppe.","8":"Ils marchent de hauteur en hauteur, Dieu leur apparaît dans Sion.","9":"Yahvé Dieu Sabaot, écoute ma prière, prête l'oreille, Dieu de Jacob;","10":"ô Dieu notre bouclier, vois, regarde la face de ton messie.","11":"Mieux vaut un jour en tes parvis que mille à ma guise, rester au seuil dans la maison de mon Dieu qu'habiter la tente de l'impie.","12":"Car Yahvé Dieu est rempart et bouclier, il donne grâce et gloire; Yahvé ne refuse pas le bonheur à ceux qui marchent en parfaits.","13":"Yahvé Sabaot, heureux qui se fie en toi!"},"85":{"1":"Du maître de chant. Des fils de Coré.","2":"Ta complaisance, Yahvé, est pour ta terre, tu fais revenir les captifs de Jacob;","3":"tu lèves les torts de ton peuple, tu couvres toute sa faute;","4":"tu retires tout ton emportement, tu reviens de l'ardeur de ta colère.","5":"Fais-nous revenir, Dieu de notre salut, apaise ton ressentiment contre nous!","6":"Seras-tu pour toujours irrité contre nous, garderas-tu ta colère d'âge en âge?","7":"Ne reviendras-tu pas nous vivifier, et ton peuple en toi se réjouira?","8":"Fais-nous voir, Yahvé, ton amour, que nous soit donné ton salut!","9":"J'écoute. Que dit Dieu? Ce que dit Yahvé, c'est la paix pour son peuple et ses amis, pourvu qu'ils ne reviennent à leur folie.","10":"Proche est son salut pour qui le craint, et la Gloire habitera notre terre.","11":"Amour et Vérité se rencontrent, Justice et Paix s'embrassent;","12":"Vérité germera de la terre, et des cieux se penchera la Justice;","13":"Yahvé lui-même donnera le bonheur et notre terre donnera son fruit;","14":"Justice marchera devant lui et de ses pas tracera un chemin."},"86":{"1":"Prière. De David. Tends l'oreille, Yahvé, réponds-moi, pauvre et malheureux que je suis;","2":"garde mon âme, car je suis ton ami, sauve ton serviteur qui se fie en toi. Tu es mon Dieu,","3":"pitié pour moi, Seigneur, c'est toi que j'appelle tout le jour;","4":"réjouis l'âme de ton serviteur, quand j'élève mon âme vers toi, Seigneur.","5":"Seigneur, tu es pardon et bonté, plein d'amour pour tous ceux qui t'appellent;","6":"Yahvé, entends ma prière, attentif à la voix de ma plainte.","7":"Au jour de l'angoisse, je t'appelle, car tu me réponds, Seigneur;","8":"entre les dieux, pas un comme toi, rien qui ressemble à tes oeuvres.","9":"Tous les païens viendront t'adorer, Seigneur, et rendre gloire à ton nom;","10":"car tu es grand et tu fais des merveilles, toi, Dieu, et toi seul.","11":"Enseigne-moi, Yahvé, tes voies, afin que je marche en ta vérité, rassemble mon coeur pour craindre ton nom.","12":"Je te rends grâce de tout mon coeur, Seigneur mon Dieu, à jamais je rendrai gloire à ton nom,","13":"car ton amour est grand envers moi, tu as tiré mon âme du tréfonds du shéol.","14":"O Dieu, des orgueilleux ont surgi contre moi, une bande de forcenés pourchasse mon âme, point de place pour toi devant eux.","15":"Mais toi, Seigneur, Dieu de tendresse et de pitié, lent à la colère, plein d'amour et de vérité,","16":"tourne-toi vers moi, pitié pour moi! Donne à ton serviteur ta force et ton salut au fils de ta servante,","17":"fais pour moi un signe de bonté. Ils verront, mes ennemis, et rougiront, car toi, Yahvé, tu m'aides et me consoles."},"87":{"1":"Des fils de Coré. Psaume. Cantique. Sa fondation sur les montagnes saintes,","2":"Yahvé la chérit, préférant les portes de Sion à toute demeure de Jacob.","3":"Il parle de toi pour ta gloire, cité de Dieu:","4":"\"Je compte Rahab et Babylone parmi ceux qui me connaissent, voyez Tyr, la Philistie ou l'Ethiopie, un tel y est né.\"","5":"Mais de Sion l'on dira: \"Tout homme y est né\" et celui qui l'affermit, c'est le Très-Haut.","6":"Yahvé inscrit au registre les peuples: \"Un tel y est né\",","7":"et les princes, comme les enfants. Tous font en toi leur demeure."},"88":{"1":"Cantique. Psaume. Des fils de Coré. Du maître de chant. Pour la maladie. Pour l'affliction. Poème. De Hémân l'indigène.","2":"Yahvé, Dieu de mon salut, lorsque je crie la nuit devant toi,","3":"que jusqu'à toi vienne ma prière, prête l'oreille à mes sanglots.","4":"Car mon âme est rassasiée de maux et ma vie est au bord du shéol;","5":"déjà compté comme descendu dans la fosse, je suis un homme fini:","6":"congédié chez les morts, pareil aux tués qui gisent dans la tombe, eux dont tu n'as plus souvenir et qui sont retranchés de ta main.","7":"Tu m'as mis au tréfonds de la fosse, dans les ténèbres, dans les abîmes;","8":"sur moi pèse ta colère, tu déverses toutes tes vagues.","9":"Tu as éloigné de moi mes compagnons, tu as fait de moi une horreur pour eux; je suis enfermé et ne puis sortir,","10":"mon oeil est usé par le malheur. Je t'appelle, Yahvé, tout le jour, je tends les mains vers toi:","11":"\"Pour les morts fais-tu des merveilles, les ombres se lèvent-elles pour te louer?","12":"Parle-t-on de ton amour dans la tombe, de ta vérité au lieu de perdition?","13":"Connaît-on dans la ténèbre tes merveilles et ta justice au pays de l'oubli...?\"","14":"Et moi, je crie vers toi, Yahvé, le matin, ma prière te prévient;","15":"pourquoi, Yahvé, repousses-tu mon âme, caches-tu loin de moi ta face?","16":"Malheureux et mourant dès mon enfance, j'ai enduré tes effrois, je suis à bout;","17":"sur moi ont passé tes colères, tes épouvantes m'ont réduit à rien.","18":"Elles me cernent comme l'eau tout le jour, se referment sur moi toutes ensemble.","19":"Tu éloignes de moi amis et proches; ma compagnie, c'est la ténèbre."},"89":{"1":"Poème. D'Etân l'indigène.","2":"L'amour de Yahvé à jamais je le chante, d'âge en âge ma parole annonce ta vérité.","3":"Car tu as dit: l'amour est bâti à jamais, les cieux, tu fondes en eux ta vérité.","4":"\"J'ai fait une alliance avec mon élu, j'ai juré à David mon serviteur:","5":"A tout jamais j'ai fondé ta lignée, je te bâtis d'âge en âge un trône.\"","6":"Les cieux rendent grâce pour ta merveille, Yahvé, pour ta vérité, dans l'assemblée des saints.","7":"Qui donc en les nues se compare à Yahvé, s'égale à Yahvé parmi les fils des dieux?","8":"Dieu redoutable au conseil des saints, grand et terrible à tout son entourage,","9":"Yahvé, Dieu Sabaot, qui est comme toi? Yahvé puissant, que ta vérité entoure!","10":"C'est toi qui maîtrises l'orgueil de la mer, quand ses flots se soulèvent, c'est toi qui les apaises;","11":"c'est toi qui fendis Rahab comme un cadavre, dispersas tes adversaires par ton bras de puissance.","12":"A toi le ciel, à toi aussi la terre, le monde et son contenu, c'est toi qui les fondas;","13":"le nord et le midi, c'est toi qui les créas, le Tabor et l'Hermon à ton nom crient de joie.","14":"A toi ce bras et sa prouesse, puissante est ta main, sublime est ta droite;","15":"Justice et Droit sont l'appui de ton trône, Amour et Vérité marchent devant ta face.","16":"Heureux le peuple qui sait l'acclamation! Yahvé, à la clarté de ta face ils iront;","17":"en ton nom ils jubilent tout le jour, en ta justice ils s'exaltent.","18":"L'éclat de leur puissance, c'est toi, dans ta faveur tu exaltes notre vigueur;","19":"car à Yahvé est notre bouclier; à lui, Saint d'Israël, est notre roi.","20":"Jadis, en vision, tu as parlé et tu as dit à tes amis: \"J'ai prêté assistance à un preux, j'ai exalté un cadet de mon peuple.","21":"J'ai trouvé David mon serviteur, je l'ai oint de mon huile sainte;","22":"pour lui ma main sera ferme, mon bras aussi le rendra fort.","23":"L'adversaire ne pourra le tromper, le pervers ne pourra l'accabler;","24":"j'écraserai devant lui ses agresseurs, ses ennemis, je les frapperai.","25":"Ma vérité et mon amour avec lui, par mon nom s'exaltera sa vigueur;","26":"j'établirai sa main sur la mer et sur les fleuves sa droite.","27":"Il m'appellera: Toi, mon père, mon Dieu et le rocher de mon salut!","28":"si bien que j'en ferai l'aîné, le très-haut sur les rois de la terre.","29":"A jamais je lui garde mon amour, mon alliance est pour lui véridique;","30":"j'ai pour toujours établi sa lignée, et son trône comme les jours des cieux.","31":"Si ses fils abandonnent ma loi, ne marchent pas selon mes jugements,","32":"s'ils profanent mes préceptes et ne gardent pas mes commandements,","33":"je visiterai avec des verges leur péché, avec des coups leur méfait,","34":"mais sans retirer de lui mon amour, sans faillir dans ma vérité.","35":"Point ne profanerai mon alliance, ne dédirai le souffle de mes lèvres;","36":"une fois j'ai juré par ma sainteté: mentir à David, jamais!","37":"Sa lignée à jamais sera, et son trône comme le soleil devant moi,","38":"comme est fondée la lune à jamais, témoin véridique dans la nue.\"","39":"Mais toi, tu as rejeté et répudié, tu t'es emporté contre ton oint;","40":"tu as renié l'alliance de ton serviteur, tu as profané jusqu'à terre son diadème.","41":"Tu as fait brèche à toutes ses clôtures, tu as mis en ruines ses lieux forts;","42":"tous les passants du chemin l'ont pillé, ses voisins en ont fait une insulte.","43":"Tu as donné la haute main à ses agresseurs, tu as mis en joie tous ses adversaires;","44":"tu as brisé son épée contre le roc, tu ne l'as pas épaulé dans le combat.","45":"Tu as ôté son sceptre de splendeur, renversé son trône jusqu'à terre;","46":"tu as écourté les jours de sa jeunesse, étalé sur lui la honte.","47":"Jusques à quand, Yahvé, seras-tu caché? Jusqu'à la fin? Brûlera-t-elle comme un feu, ta colère?","48":"Souviens-toi de moi: quelle est ma durée? Pour quel néant as-tu créé les fils d'Adam?","49":"Qui donc vivra sans voir la mort, soustraira son âme à la griffe du shéol?","50":"Où sont les prémices de ton amour, Seigneur? Tu as juré à David sur ta vérité.","51":"Souviens-toi, Seigneur, de l'insulte à ton serviteur: je reçois en mon sein tous les traits des peuples;","52":"ainsi tes adversaires, Yahvé, ont insulté, ainsi insulté les traces de ton oint!","53":"Béni soit Yahvé à jamais! Amen! Amen!"},"90":{"1":"Prière. De Moïse, homme de Dieu. Seigneur, tu as été pour nous un refuge d'âge en âge.","2":"Avant que les montagnes fussent nées, enfantés la terre et le monde, de toujours à toujours tu es Dieu.","3":"Tu fais revenir le mortel à la poussière en disant: \"Revenez, fils d'Adam! \"","4":"Car mille ans sont à tes yeux comme le jour d'hier qui passe, comme une veille dans la nuit.","5":"Tu les submerges de sommeil, ils seront le matin comme l'herbe qui pousse;","6":"le matin, elle fleurit et pousse, le soir, elle se flétrit et sèche.","7":"Par ta colère, nous sommes consumés, par ta fureur, épouvantés.","8":"Tu as mis nos torts devant toi, nos secrets sous l'éclat de ta face.","9":"Sous ton courroux tous nos jours déclinent, nous consommons nos années comme un soupir.","10":"Le temps de nos années, quelque 70 ans, si la vigueur y est; mais leur grand nombre n'est que peine et mécompte, car elles passent vite, et nous nous envolons.","11":"Qui sait la force de ta colère et, te craignant, connaît ton courroux?","12":"Fais-nous savoir comment compter nos jours, que nous venions de coeur à la sagesse!","13":"Reviens, Yahvé! Jusques à quand? Prends en pitié tes serviteurs.","14":"Rassasie-nous de ton amour au matin, nous serons dans la joie et le chant tous les jours.","15":"Rends-nous en joies tes jours de châtiment et les années où nous connûmes le malheur.","16":"Paraisse ton oeuvre pour tes serviteurs, ta splendeur soit sur leurs enfants!","17":"La douceur du Seigneur soit sur nous! Confirme l'ouvrage de nos mains!"},"91":{"1":"Qui habite le secret d'Elyôn passe la nuit à l'ombre de Shaddaï,","2":"disant à Yahvé: Mon abri, ma forteresse, mon Dieu sur qui je compte!","3":"C'est lui qui t'arrache au filet de l'oiseleur qui s'affaire à détruire;","4":"il te couvre de ses ailes, tu as sous son pennage un abri. Armure et bouclier, sa vérité.","5":"Tu ne craindras ni les terreurs de la nuit, ni la flèche qui vole de jour,","6":"ni la peste qui marche en la ténèbre, ni le fléau qui dévaste à midi.","7":"Qu'il en tombe mille à tes côtés et 10.000 à ta droite, toi, tu restes hors d'atteinte.","8":"Il suffit que tes yeux regardent, tu verras le salaire des impies,","9":"toi qui dis: Yahvé mon abri! et qui fais d'Elyôn ton refuge.","10":"Le malheur ne peut fondre sur toi, ni la plaie approcher de ta tente:","11":"il a pour toi donné ordre à ses anges de te garder en toutes tes voies.","12":"Sur leurs mains ils te porteront pour qu'à la pierre ton pied ne heurte;","13":"sur le fauve et la vipère tu marcheras, tu fouleras le lionceau et le dragon.","14":"Puisqu'il s'attache à moi, je l'affranchis, je l'exalte puisqu'il connaît mon nom.","15":"Il m'appelle et je lui réponds: \"Je suis près de lui dans la détresse, je le délivre et je le glorifie,","16":"de longs jours je veux le rassasier et je ferai qu'il voie mon salut."},"92":{"1":"Cantique. Pour le jour du sabbat.","2":"Il est bon de rendre grâce à Yahvé, de jouer pour ton nom, Très-Haut,","3":"de publier au matin ton amour, ta fidélité au long des nuits,","4":"sur la lyre à dix cordes et la cithare, avec un murmure de harpe.","5":"Tu m'as réjoui, Yahvé, par tes oeuvres, devant l'ouvrage de tes mains je m'écrie:","6":"\"Que tes oeuvres sont grandes, Yahvé, combien profonds tes pensers! \"","7":"L'homme stupide ne sait pas, cela, l'insensé n'y comprends rien.","8":"S'ils poussent comme l'herbe, les impies, s'ils fleurissent, tous les malfaisants, c'est pour être abattus à jamais,","9":"mais toi, tu es élevé pour toujours, Yahvé.","10":"Voici: tes ennemis périssent, tous les malfaisants se dispersent;","11":"tu me donnes la vigueur du taureau, tu répands sur moi l'huile fraîche;","12":"mon oeil a vu ceux qui m'épiaient, mes oreilles ont entendu les méchants.","13":"Le juste poussera comme un palmier, il grandira comme un cèdre du Liban.","14":"Plantés dans la maison de Yahvé, ils pousseront dans les parvis de notre Dieu.","15":"Dans la vieillesse encore ils portent fruit, ils restent frais et florissants,","16":"pour publier que Yahvé est droit: mon Rocher, en lui rien de faux."},"93":{"1":"Yahvé règne, il est vêtu de majesté, il est vêtu, enveloppé de puissance. Oui, le monde est stable; point ne bronchera.","2":"Ton trône est établi dès l'origine, depuis toujours, tu es.","3":"Les fleuves déchaînent, ô Yahvé, les fleuves déchaînent leur voix, les fleuves déchaînent leur fracas;","4":"plus que la voix des eaux innombrables, plus superbe que le ressac de la mer; superbe est Yahvé dans les hauteurs.","5":"Ton témoignage est véridique entièrement; la sainteté est l'ornement de ta maison, Yahvé, en la longueur des jours."},"94":{"1":"Dieu des vengeances, Yahvé, Dieu des vengeances, parais!","2":"Lève-toi, juge de la terre, retourne aux orgueilleux leur salaire!","3":"Jusques à quand les impies, Yahvé, jusques à quand les impies triomphant?","4":"Ils déblatèrent, ils ont le verbe haut, ils se rengorgent, tous les malfaisants.","5":"Et ton peuple, Yahvé, qu'ils écrasent, et ton héritage qu'ils oppriment,","6":"la veuve et l'étranger, ils les égorgent, et l'orphelin, ils l'assassinent!","7":"Et ils disent: \"Yahvé ne voit pas, le Dieu de Jacob ne prend pas garde.\"","8":"Prenez garde, stupides entre tous! insensés, quand aurez-vous l'intelligence?","9":"Lui qui planta l'oreille n'entendrait pas? S'il a façonné l'oeil, il ne verrait pas?","10":"Lui qui reprend les peuples ne punirait pas? Lui qui enseigne à l'homme le savoir,","11":"Yahvé sait les pensées de l'homme et qu'elles sont du vent.","12":"Heureux l'homme que tu reprends, Yahvé, et que tu enseignes par ta loi,","13":"pour lui donner le repos aux mauvais jours, tant que se creuse une fosse pour l'impie.","14":"Car Yahvé ne délaisse point son peuple, son héritage, point ne l'abandonne;","15":"le jugement revient vers la justice, tous les coeurs droits lui font cortège.","16":"Qui se lève pour moi contre les méchants, qui siège pour moi contre les malfaisants?","17":"Si Yahvé ne me venait en aide, bientôt mon âme habiterait le silence.","18":"Quand je dis: \"Mon pied chancelle\", ton amour, Yahvé, me soutient;","19":"dans l'excès des soucis qui m'envahissent, tes consolations délectent mon âme.","20":"Es-tu l'allié d'un tribunal de perdition, érigeant en loi le désordre?","21":"On s'attaque à la vie du juste, et le sang innocent, on le condamne.","22":"Mais Yahvé est pour moi une citadelle, et mon Dieu, le rocher de mon refuge;","23":"il retourne contre eux leur méfait et pour leur malice il les fait taire, il les fait taire, Yahvé notre Dieu!"},"95":{"1":"Venez, crions de joie pour Yahvé, acclamons le Rocher de notre salut;","2":"approchons de sa face en rendant grâce, au son des musiques acclamons-le.","3":"Car c'est un Dieu grand que Yahvé, un Roi grand par-dessus tous les dieux;","4":"en sa main sont les creux de la terre et les hauts des montagnes sont à lui;","5":"à lui la mer, c'est lui qui l'a faite, la terre ferme, ses mains l'ont façonnée.","6":"Entrez, courbons-nous, prosternons-nous; à genoux devant Yahvé qui nous a faits!","7":"Car c'est lui notre Dieu, et nous le peuple de son bercail, le troupeau de sa main. Aujourd'hui si vous écoutiez sa voix!","8":"\"N'endurcissez pas vos coeurs comme à Meriba, comme au jour de Massa dans le désert,","9":"où vos pères m'éprouvaient, me tentaient, alors qu'ils me voyaient agir!","10":"40 ans cette génération m'a dégoûté et je dis: Toujours ces coeurs errants, ces gens-là n'ont pas connu mes voies.","11":"Alors j'ai juré en ma colère: jamais ils ne parviendront à mon repos.\""},"96":{"1":"Chantez à Yahvé un chant nouveau! Chantez à Yahvé, toute la terre!","2":"Chantez à Yahvé, bénissez son nom! Proclamez jour après jour son salut,","3":"racontez aux païens sa gloire, à tous les peuples ses merveilles!","4":"Grand, Yahvé, et louable hautement, redoutable, lui, par-dessus tous les dieux!","5":"Néant, tous les dieux des nations. C'est Yahvé qui fit les cieux;","6":"devant lui, splendeur et majesté, dans son sanctuaire, puissance et beauté.","7":"Rapportez à Yahvé, familles des peuples, rapportez à Yahvé gloire et puissance,","8":"rapportez à Yahvé la gloire de son nom. Présentez l'oblation, entrez en ses parvis,","9":"adorez Yahvé dans son éclat de sainteté. Tremblez devant lui, toute la terre.","10":"Dites chez les païens: \"Yahvé règne.\" Le monde est stable, point ne bronchera. Sur les peuples il prononce avec droiture.","11":"Joie au ciel! exulte la terre! Que gronde la mer, et sa plénitude!","12":"Que jubile la campagne, et tout son fruit, que tous les arbres des forêts crient de joie,","13":"à la face de Yahvé, car il vient, car il vient pour juger la terre; il jugera le monde en justice et les peuples en sa vérité."},"97":{"1":"Yahvé règne! Exulte la terre, que jubilent les îles nombreuses!","2":"Ténèbre et Nuée l'entourent, Justice et Droit sont l'appui de son trône.","3":"Un feu devant lui s'avance et dévore à l'entour ses rivaux;","4":"ses éclairs illuminent le monde, la terre voit et chavire.","5":"Les montagnes fondent comme la cire devant le Maître de toute la terre;","6":"les cieux proclament sa justice et tous les peuples voient sa gloire.","7":"Honte aux servants des idoles, eux qui se vantent de vanités; prosternez-vous devant lui, tous les dieux.","8":"Sion entend et jubile, les filles de Juda exultent à cause de tes jugements, Yahvé.","9":"Car toi, tu es Yahvé, Très-Haut sur toute la terre, surpassant de beaucoup tous les dieux.","10":"Yahvé aime qui déteste le mal, il garde les âmes des siens et de la main des impies les délivre.","11":"La lumière se lève pour le juste, et pour l'homme au coeur droit, la joie.","12":"Justes, jubilez en Yahvé, louez sa mémoire de sainteté."},"98":{"1":"Chantez à Yahvé un chant nouveau, car il a fait des merveilles; le salut lui vint de sa droite, de son bras de sainteté.","2":"Yahvé a fait connaître son salut, aux yeux des païens révélé sa justice,","3":"se rappelant son amour et sa fidélité pour la maison d'Israël. Tous les lointains de la terre ont vu le salut de notre Dieu.","4":"Acclamez Yahvé, toute la terre, éclatez en cris de joie!","5":"Jouez pour Yahvé sur la harpe, au son des instruments;","6":"au son de la trompette et du cor acclamez à la face du roi Yahvé.","7":"Gronde la mer et sa plénitude, le monde et son peuplement;","8":"que tous les fleuves battent des mains et les montagnes crient de joie,","9":"à la face de Yahvé, car il vient pour juger la terre, il jugera le monde en justice et les peuples en droiture."},"99":{"1":"Yahvé règne, les peuples tremblent; il siège sur les Chérubins, la terre chancelle;","2":"dans Sion Yahvé est grand. Il s'exalte, lui, par-dessus tous les peuples;","3":"qu'ils célèbrent ton nom grand et redoutable: il est saint, lui,","4":"et puissant. Le roi qui aime le jugement, c'est toi; tu as fondé droiture, jugement et justice, en Jacob c'est toi qui agis.","5":"Exaltez Yahvé notre Dieu, prosternez-vous vers son marchepied: lui, il est saint.","6":"Moïse, Aaron parmi ses prêtres, et Samuel, appelant son nom, en appelaient à Yahvé: et lui, il leur répondait.","7":"Dans la colonne de nuée, il parlait avec eux; eux gardaient ses témoignages, la Loi qu'il leur donna.","8":"Yahvé notre Dieu, toi, tu leur répondais, Dieu de pardon que tu étais pour eux, mais te vengeant de leurs méfaits.","9":"Exaltez Yahvé notre Dieu, prosternez-vous vers sa sainte montagne: saint est Yahvé notre Dieu."},"100":{"1":"Pour l'action de grâces. Acclamez Yahvé, toute la terre,","2":"servez Yahvé dans l'allégresse, venez à lui avec des chants de joie!","3":"Sachez-le, c'est Yahvé qui est Dieu, il nous a faits et nous sommes à lui, son peuple et le troupeau de son bercail.","4":"Venez à ses portiques en rendant grâce, à ses parvis en chantant louange, rendez-lui grâce, bénissez son nom!","5":"Il est bon, Yahvé, éternel est son amour, et d'âge en âge, sa vérité."},"101":{"1":"De David. Psaume. Je chanterai amour et jugement, pour toi, Yahvé, je jouerai;","2":"j'avancerai dans la voie des parfaits: quand viendras-tu vers moi? Je suivrai la perfection de mon coeur dans ma maison;","3":"point de place devant mes yeux pour rien de vil. Je hais les façons des dévoyés, elles n'ont sur moi nulle prise;","4":"loin de moi le coeur tortueux, le méchant, je l'ignore.","5":"Qui dénigre en secret son prochain, celui-là, je le fais taire; l'oeil hautain, le coeur enflé, je ne puis les souffrir.","6":"J'ai les yeux sur les fidèles du pays, qu'ils demeurent avec moi; celui qui marche dans la voie des parfaits sera mon servant.","7":"Point de demeure en ma maison pour le faiseur de tromperie; le diseur de mensonges ne tient pas devant mes yeux.","8":"Au matin, je les fais taire, tous les impies du pays, pour retrancher de la ville de Yahvé tous les malfaisants."},"102":{"1":"Prière pour un malheureux qui dans son accablement répand sa plainte devant Yahvé.","2":"Yahvé, entends ma prière, que mon cri vienne jusqu'à toi;","3":"ne cache pas loin de moi ta face au jour où l'angoisse me tient; incline vers moi ton oreille, au jour où je t'appelle, vite, réponds-moi!","4":"Car mes jours s'en vont en fumée, mes os brûlent comme un brasier;","5":"battu comme l'herbe, mon coeur sèche et j'oublie de manger mon pain;","6":"à force de crier ma plainte, ma peau s'est collée à mes os.","7":"Je ressemble au hibou du désert, je suis pareil à la hulotte des ruines;","8":"je veille et je gémis, comme l'oiseau solitaire sur le toit;","9":"tout le jour mes ennemis m'outragent, ceux qui me louaient maudissent par moi.","10":"La cendre est le pain que je mange, je mêle à ma boisson mes larmes,","11":"devant ta colère et ta fureur, car tu m'as soulevé puis rejeté;","12":"mes jours sont comme l'ombre qui décline, et moi comme l'herbe je sèche.","13":"Mais toi, Yahvé, tu trônes à jamais; d'âge en âge, mémoire de toi!","14":"Toi, tu te lèveras, attendri pour Sion, car il est temps de la prendre en pitié, car l'heure est venue;","15":"car tes serviteurs en chérissent les pierres, pris de pitié pour sa poussière.","16":"Et les païens craindront le nom de Yahvé, et tous les rois de la terre, ta gloire;","17":"quand Yahvé rebâtira Sion, il sera vu dans sa gloire;","18":"il se tournera vers la prière du spolié, il n'aura pas méprisé sa prière.","19":"On écrira ceci pour l'âge à venir et un peuple nouveau louera Dieu:","20":"il s'est penché du haut de son sanctuaire, Yahvé, et des cieux a regardé sur terre,","21":"afin d'écouter le soupir du captif, de libérer les clients de la mort,","22":"pour répandre dans Sion le nom de Yahvé, sa louange dans Jérusalem,","23":"quand se joindront peuples et royaumes pour rendre un culte à Yahvé.","24":"En chemin ma force a fléchi; le petit nombre de mes jours,","25":"fais-le-moi savoir, ne me prends pas à la moitié de mes jours, d'âge en âge vont tes années.","26":"Depuis longtemps tu as fondé la terre, et les cieux sont l'ouvrage de tes mains;","27":"eux périssent, toi tu restes, tous comme un vêtement ils s'usent, comme un habit qu'on change, tu les changes;","28":"mais toi, le même, sans fin sont tes années.","29":"Les fils de tes serviteurs auront une demeure et leur lignée subsistera devant toi."},"103":{"1":null},"104":{"1":"Bénis Yahvé, mon âme. Yahvé, mon Dieu, tu es si grand! Vêtu de faste et d'éclat,","2":"drapé de lumière comme d'un manteau, tu déploies les cieux comme une tente,","3":"tu bâtis sur les eaux tes chambres hautes; faisant des nuées ton char, tu t'avances sur les ailes du vent;","4":"tu prends les vents pour messagers, pour serviteurs un feu de flammes.","5":"Tu poses la terre sur ses bases, inébranlable pour les siècles des siècles.","6":"De l'abîme tu la couvres comme d'un vêtement, sur les montagnes se tenaient les eaux.","7":"A ta menace, elles prennent la fuite, à la voix de ton tonnerre, elles s'échappent;","8":"elles sautent les montagnes, elles descendent les vallées vers le lieu que tu leur as assigné;","9":"tu mets une limite à ne pas franchir, qu'elles ne reviennent couvrir la terre.","10":"Dans les ravins tu fais jaillir les sources, elles cheminent au milieu des montagnes;","11":"elles abreuvent toutes les bêtes des champs, les onagres y calment leur soif;","12":"l'oiseau des cieux séjourne près d'elles, sous la feuillée il élève la voix.","13":"De tes chambres hautes, tu abreuves les montagnes; la terre se rassasie du fruit de tes oeuvres;","14":"tu fais croître l'herbe pour le bétail et les plantes à l'usage des humains, pour qu'ils tirent le pain de la terre","15":"et le vin qui réjouit le coeur de l'homme, pour que l'huile fasse luire les visages et que le pain fortifie le coeur de l'homme.","16":"Les arbres de Yahvé se rassasient, les cèdres du Liban qu'il a plantés;","17":"c'est là que nichent les passereaux, sur leur cime la cigogne a son gîte;","18":"aux chamois, les hautes montagnes, aux damans, l'abri des rochers.","19":"Il fit la lune pour marquer les temps, le soleil connaît son coucher.","20":"Tu poses la ténèbre, c'est la nuit, toutes les bêtes des forêts s'y remuent.","21":"Les lionceaux rugissent après la proie et réclament à Dieu leur manger.","22":"Quand se lève le soleil, ils se retirent et vont à leurs repaires se coucher;","23":"l'homme sort pour son ouvrage, faire son travail jusqu'au soir.","24":"Que tes oeuvres sont nombreuses, Yahvé! toutes avec sagesse tu les fis, la terre est remplie de ta richesse.","25":"Voici la grande mer aux vastes bras, et là le remuement sans nombre des animaux petits et grands,","26":"là des navires se promènent et Léviathan que tu formas pour t'en rire.","27":"Tous ils espèrent de toi que tu donnes en son temps leur manger;","28":"tu leur donnes, eux, ils ramassent, tu ouvres la main, ils se rassasient.","29":"Tu caches ta face, ils s'épouvantent, tu retires leur souffle, ils expirent, à leur poussière ils retournent.","30":"Tu envoies ton souffle, ils sont créés, tu renouvelles la face de la terre.","31":"A jamais soit la gloire de Yahvé, que Yahvé se réjouisse en ses oeuvres!","32":"Il regarde la terre, elle tremble, il touche les montagnes, elles fument!","33":"Je veux chanter à Yahvé tant que je vis, je veux jouer pour mon Dieu tant que je dure.","34":"Puisse mon langage lui plaire, moi, j'ai ma joie en Yahvé!","35":"Que les pécheurs disparaissent de la terre, les impies, qu'il n'en soit jamais plus! Bénis Yahvé, mon âme."},"105":{"1":"Alleluia! Rendez grâce à Yahvé, criez son nom, annoncez parmi les peuples ses hauts faits;","2":"chantez-le, jouez pour lui, récitez toutes ses merveilles;","3":"tirez gloire de son nom de sainteté, joie pour les coeurs qui cherchent Yahvé!","4":"Recherchez Yahvé et sa force, sans relâche poursuivez sa face;","5":"rappelez-vous quelles merveilles il a faites, ses miracles et les jugements de sa bouche.","6":"Lignée d'Abraham son serviteur, enfants de Jacob son élu,","7":"c'est lui Yahvé notre Dieu: sur toute la terre ses jugements.","8":"Il se rappelle à jamais son alliance, parole promulguée pour mille générations,","9":"pacte conclu avec Abraham, serment qu'il fit à Isaac.","10":"Il l'érigea en loi pour Jacob, pour Israël en alliance à jamais,","11":"disant: \"Je te donne une terre, Canaan, votre part d'héritage.\"","12":"Tant qu'on put les compter, peu nombreux, étrangers au pays,","13":"tant qu'ils allaient de nation en nation, d'un royaume à un peuple différent,","14":"il ne laissa personne les opprimer, à cause d'eux il châtia des rois:","15":"\"Ne touchez pas à qui m'est consacré; à mes prophètes ne faites pas de mal.\"","16":"Il appela sur le pays la famine, il brisa leur bâton, le pain;","17":"il envoya devant eux un homme, Joseph vendu comme esclave.","18":"On affligea ses pieds d'entraves, on lui passa les fers au cou;","19":"le temps passa, son oracle s'accomplit, la parole de Yahvé le justifia.","20":"Le roi envoya l'élargir, le maître des peuples, lui ouvrir;","21":"il l'établit seigneur sur sa maison, maître de toute sa richesse,","22":"pour instruire à son gré ses princes; de ses anciens il fit des sages.","23":"Israël passa en Egypte, Jacob séjourna au pays de Cham.","24":"Il fit croître son peuple abondamment, le fortifia plus que ses adversaires;","25":"changeant leur coeur, il les fit haïr son peuple et ruser avec ses serviteurs.","26":"Il envoya son serviteur Moïse, Aaron qu'il s'était choisi;","27":"ils firent chez eux les signes qu'il avait dits, des miracles au pays de Cham.","28":"Il envoya la ténèbre et enténébra, mais ils bravèrent ses ordres.","29":"Il changea leurs eaux en sang et fit périr leurs poissons.","30":"Leur pays grouilla de grenouilles jusque dans les chambres des rois;","31":"il dit, et les insectes passèrent, les moustiques sur toute la contrée.","32":"Il leur donna pour pluie la grêle, flammes de feu sur leur pays;","33":"il frappa leur vigne et leur figuier, il brisa les arbres de leur contrée.","34":"Il dit, et les sauterelles passèrent, les criquets, et ils étaient sans nombre,","35":"et ils mangèrent toute herbe en leur pays et ils mangèrent le fruit de leur terroir.","36":"Il frappa tout premier-né dans leur pays, toute la fleur de leur race;","37":"il les fit sortir avec or et argent, et pas un dans leurs tribus ne trébuchait.","38":"L'Egypte se réjouit de leur sortie, elle en était saisie de terreur;","39":"il déploya une nuée pour les couvrir, un feu pour éclairer de nuit.","40":"Ils demandèrent, il fit passer les cailles, du pain des cieux il les rassasia;","41":"il ouvrit le rocher, les eaux jaillirent, dans le lieu sec elles coulaient comme un fleuve.","42":"Se rappelant sa parole sacrée envers Abraham son serviteur,","43":"il fit sortir son peuple dans l'allégresse, parmi les cris de joie, ses élus.","44":"Il leur donna les terres des païens, du labeur des nations ils héritèrent,","45":"en sorte qu'ils gardent ses décrets et qu'ils observent ses lois."},"106":{"1":"Alleluia! Rendez grâce à Yahvé, car il est bon, car éternel est son amour!","2":"Qui dira les prouesses de Yahvé, fera retentir toute sa louange?","3":"Heureux qui observe le droit, qui pratique en tout temps la justice!","4":"Souviens-toi de moi, Yahvé, par amour de ton peuple, visite-moi par ton salut,","5":"que je voie le bonheur de tes élus, joyeux de la joie de ton peuple, glorieux avec ton héritage!","6":"Nous avons failli avec nos pères, nous avons dévié, renié;","7":"nos pères en Egypte n'ont pas compris tes merveilles. Ils n'eurent pas souvenir de ton grand amour, ils bravèrent le Très-Haut à la mer des Joncs.","8":"Il les sauva à cause de son nom, pour faire connaître sa prouesse.","9":"Il menaça la mer des Joncs, elle sécha, il les mena sur l'abîme comme au désert,","10":"les sauva de la main de l'ennemi, les racheta de la main de l'adversaire.","11":"Et les eaux recouvrirent leurs oppresseurs, pas un d'entre eux n'échappa.","12":"Alors ils eurent foi en ses paroles, ils chantèrent sa louange.","13":"Ils coururent oublier ses actions, ils n'attendirent pas même son projet;","14":"ils brûlaient de désir dans le désert, ils tentaient Dieu parmi les solitudes.","15":"Il leur accorda leur demande: il envoya la fièvre dans leur âme;","16":"ils jalousèrent Moïse dans le camp, Aaron le saint de Yahvé.","17":"La terre s'ouvre, elle avale Datân et recouvre la bande d'Abiram;","18":"un feu s'allume contre leur bande, une flamme embrase les renégats.","19":"Ils fabriquèrent un veau en Horeb, se prosternèrent devant une fonte;","20":"ils échangèrent leur gloire pour l'image du boeuf mangeur d'herbe.","21":"Ils oubliaient Dieu qui les sauvait, l'auteur de grandes choses en Egypte,","22":"de merveilles en terre de Cham, d'épouvantes sur la mer des Joncs.","23":"Il parlait de les supprimer, si ce n'est que Moïse son élu se tint sur la brèche devant lui pour détourner son courroux de détruire.","24":"Ils refusèrent une terre de délices, ils n'eurent pas foi en sa parole;","25":"ils murmurèrent sous leurs tentes, ils n'écoutèrent pas la voix de Yahvé.","26":"Il leva la main sur eux, pour les abattre au désert,","27":"pour abattre leur lignée chez les païens, pour les parsemer dans les pays.","28":"Ils se mirent au joug de Baal-Péor et mangèrent les sacrifices des morts.","29":"Ils l'indignèrent par leurs pratiques, un fléau éclata contre eux.","30":"Alors se lève Pinhas, il tranche, alors s'arrête le fléau;","31":"justice lui en est rendue d'âge en âge et pour toujours.","32":"Ils le fâchèrent aux eaux de Meriba; mal en prit à Moïse par leur faute,","33":"car ils aigrirent son esprit et ses lèvres parlèrent trop vite.","34":"Ils ne supprimèrent pas les peuples, ceux que Yahvé leur avait dits,","35":"et ils se mêlaient aux païens, ils apprenaient leurs manières d'agir.","36":"Ils en servaient les idoles, elles devenaient pour eux un piège!","37":"Ils avaient sacrifié leurs fils et leurs filles aux démons.","38":"Ils versaient le sang innocent, le sang de leurs fils et de leurs filles qu'ils sacrifiaient aux idoles de Canaan, et le pays fut profané de sang.","39":"Ils se souillaient par leurs actions, ils se prostituaient par leurs pratiques;","40":"Yahvé prit feu contre son peuple, il eut en horreur son héritage.","41":"Il les livra aux mains des païens, leurs ennemis devinrent leurs maîtres;","42":"leurs adversaires furent leurs tyrans, ils furent courbés sous leur main.","43":"Mainte et mainte fois il les délivra, mais eux par bravade se révoltaient et s'enfonçaient dans leur tort;","44":"il eut un regard pour leur détresse alors qu'il entendait leur cri.","45":"Il se souvint pour eux de son alliance, il s'émut selon son grand amour;","46":"il leur donna d'apitoyer tous ceux qui les tenaient captifs.","47":"Sauve-nous, Yahvé notre Dieu, rassemble-nous du milieu des païens afin de rendre grâce à ton saint nom, de nous féliciter en ta louange.","48":"Béni soit Yahvé le Dieu d'Israël depuis toujours jusqu'à toujours! Et tout le peuple dira: Amen!"},"107":{"1":"Alleluia Rendez grâce à Yahvé, car il est bon, car éternel est son amour!","2":"Ils le diront, les rachetés de Yahvé, qu'il racheta de la main de l'oppresseur,","3":"qu'il rassembla du milieu des pays, orient et occident, nord et midi.","4":"Ils erraient au désert, dans les solitudes, sans trouver le chemin d'une ville habitée;","5":"ils avaient faim, surtout ils avaient soif, leur âme en eux défaillait.","6":"Et ils criaient vers Yahvé dans la détresse, de leur angoisse il les a délivrés,","7":"acheminés par un droit chemin pour aller vers la ville habitée.","8":"Qu'ils rendent grâce à Yahvé de son amour, de ses merveilles pour les fils d'Adam!","9":"Il rassasia l'âme avide, l'âme affamée, il la combla de biens.","10":"Habitants d'ombre et de ténèbre, captifs de la misère et des fers,","11":"pour avoir bravé l'ordre de Dieu et méprisé le projet du Très-Haut,","12":"il ploya leur coeur sous la peine, ils succombaient, et pas un pour les aider.","13":"Et ils criaient vers Yahvé dans la détresse, de leur angoisse il les a délivrés,","14":"il les tira de l'ombre et la ténèbre et il rompit leurs entraves.","15":"Qu'ils rendent grâce à Yahvé de son amour, de ses merveilles pour les fils d'Adam!","16":"Car il brisa les portes d'airain, les barres de fer, il les fracassa.","17":"Insensés, sur les chemins du péché, misérables à cause de leurs fautes,","18":"tout aliment les dégoûtait, ils touchaient aux portes de la mort.","19":"Et ils criaient vers Yahvé dans la détresse, de leur angoisse il les a délivrés.","20":"Il envoya sa parole, il les guérit, à la fosse il arracha leur vie.","21":"Qu'ils rendent grâce à Yahvé de son amour, de ses merveilles pour les fils d'Adam!","22":"Qu'ils sacrifient des sacrifices d'action de grâces, qu'ils répètent ses oeuvres en chants de joie!","23":"Descendus en mer sur des navires, ils faisaient négoce parmi les grandes eaux;","24":"ceux-là ont vu les oeuvres de Yahvé, ses merveilles parmi les abîmes.","25":"Il dit et fit lever un vent de bourrasque qui souleva les flots;","26":"montant aux cieux, descendant aux gouffres, sous le mal leur âme fondait;","27":"tournoyant, titubant comme un ivrogne, leur sagesse était toute engloutie.","28":"Et ils criaient vers Yahvé dans la détresse, de leur angoisse il les a délivrés.","29":"Il ramena la bourrasque au silence et les flots se turent.","30":"Ils se réjouirent de les voir s'apaiser, il les mena jusqu'au port de leur désir.","31":"Qu'ils rendent grâce à Yahvé de son amour, de ses merveilles pour les fils d'Adam!","32":"Qu'ils l'exaltent dans l'assemblée du peuple, au conseil des anciens qu'ils le louent!","33":"Il changeait les fleuves en désert, et les sources d'eau en soif,","34":"un pays de fruits en saline, à cause de la malice des habitants.","35":"Mais il changea le désert en nappe d'eau, une terre sèche en source d'eau;","36":"là il fit habiter les affamés, et ils fondèrent une ville habitée.","37":"Ils ensemencent des champs, plantent des vignes, et font du fruit à récolter.","38":"Il les bénit et ils croissent beaucoup, il ne laisse pas diminuer leur bétail.","39":"Ils étaient diminués, défaillants, sous l'étreinte des maux et des peines;","40":"déversant le mépris sur les princes, il les perdait en un chaos sans chemin.","41":"Mais il relève le pauvre de sa misère, il multiplie comme un troupeau les familles;","42":"les coeurs droits voient et se réjouissent, tout ce qui ment a la bouche fermée.","43":"Est-il un sage? Qu'il observe ces choses et comprenne l'amour de Yahvé!"},"108":{"1":"Cantique. Psaume de David.","2":"Mon coeur est prêt, ô Dieu, -- je veux chanter, je veux jouer! -- allons, ma gloire,","3":"éveille-toi, harpe, cithare, que j'éveille l'aurore!","4":"Je veux te louer chez les peuples, Yahvé, jouer pour toi dans les pays;","5":"grand par-dessus les cieux ton amour, jusqu'aux nues, ta vérité.","6":"O Dieu, élève-toi sur les cieux. Sur toute la terre, ta gloire!","7":"Pour que soient délivrés tes bien-aimés, sauve par ta droite et réponds-nous.","8":"Dieu a parlé en son sanctuaire: \"J'exulte, je partage Sichem, j'arpente la vallée du Sukkot.","9":"\"A moi Galaad, à moi Manassé, Ephraïm, l'armure de ma tête, Juda, mon bâton de commandement,","10":"\"Moab, le bassin où je me lave! sur Edom, je jette ma sandale, contre la Philistie je crie victoire.\"","11":"Qui me mènera dans une ville forte, qui me conduira jusqu'en Edom,","12":"sinon Dieu, toi qui nous as rejetés, Dieu qui ne sors plus avec nos armées.","13":"Porte-nous secours dans l'oppression: néant, le salut de l'homme!","14":"Avec Dieu nous ferons des prouesses, et lui piétinera nos oppresseurs."},"109":{"1":"Du maître de chant. De David. Psaume. Dieu de ma louange, ne te tais plus!","2":"Bouche méchante et bouche d'imposture s'ouvrent contre moi. On me parle une langue de mensonge,","3":"de paroles de haine on m'entoure, on m'attaque sans raison.","4":"Pour prix de mon amitié, on m'accuse, et je ne suis que prière;","5":"on amène sur moi le malheur pour prix du bienfait, la haine pour prix de mon amitié.","6":"\"Suscite contre lui le méchant, que se dresse à sa droite l'accusateur;","7":"du jugement qu'il sorte coupable, que sa prière soit tenue pour péché!","8":"Que les jours lui soient écourtés, qu'un autre prenne sa charge;","9":"que ses enfants deviennent orphelins et sa femme, une veuve!","10":"Ses fils, qu'ils errent et qu'ils errent, qu'ils mendient et qu'on les chasse de leurs ruines;","11":"que l'usurier rafle tout son bien, que l'étranger pille son revenu!","12":"Que pas un ne lui reste charitable, que pas un n'ait pitié de ses orphelins,","13":"que soit retranchée sa descendance, qu'en une génération soit effacé leur nom!","14":"Que Yahvé se souvienne du tort de ses pères, que le péché de sa mère ne soit pas effacé;","15":"qu'ils soient devant Yahvé constamment, pour qu'il retranche de la terre leur souvenir! \"","16":"Lui ne s'est pas souvenu d'être charitable: il pourchassait le pauvre et le malheureux, jusqu'à la mort, l'homme au coeur brisé.","17":"Il aimait la malédiction: elle vient à lui! Il ne goûtait pas la bénédiction: elle le quitte!","18":"Il revêtait la malédiction comme un manteau: elle entre au fond de lui comme de l'eau, et comme de l'huile dans ses os.","19":"Qu'elle lui soit un vêtement qui l'enveloppe, une ceinture qui l'enserre constamment!","20":"Tel soit, de par Yahvé, le salaire de mes accusateurs qui profèrent le mal sur mon âme!","21":"Mais toi, Yahvé, agis pour moi selon ton nom, délivre-moi, car ton amour est bonté.","22":"Pauvre et malheureux que je suis, mon coeur est blessé au fond de moi;","23":"comme l'ombre qui décline je m'en vais, on m'a secoué comme la sauterelle.","24":"A tant jeûner mes genoux fléchissent, ma chair est amaigrie faute d'huile;","25":"on a fait de moi une insulte, ceux qui me voient hochent la tête.","26":"Aide-moi, Yahvé mon Dieu, sauve-moi selon ton amour:","27":"qu'ils le sachent, c'est là ta main, toi, Yahvé, voilà ton oeuvre!","28":"Eux maudissent, et toi tu béniras, ils attaquent, honte sur eux, et joie pour ton serviteur!","29":"Qu'ils soient vêtus d'infamie, ceux qui m'accusent, enveloppés de leur honte comme d'un manteau!","30":"Grandes grâces à Yahvé sur mes lèvres, louange à lui parmi la multitude;","31":"car il se tient à la droite du pauvre pour sauver de ses juges son âme."},"110":{"1":"De David. Psaume. Oracle de Yahvé à mon Seigneur: \"Siège à ma droite, tant que j'aie fait de tes ennemis l'escabeau de tes pieds.\"","2":"Ton sceptre de puissance, Yahvé l'étendra: depuis Sion, domine jusqu'au coeur de l'ennemi.","3":"A toi le principat au jour de ta naissance, les honneurs sacrés dès le sein, dès l'aurore de ta jeunesse.","4":"Yahvé l'a juré, il ne s'en dédira point: \"Tu es prêtre à jamais selon l'ordre de Melchisédech.\"","5":"A ta droite, Seigneur, il abat les rois au jour de sa colère;","6":"il fait justice des nations, entassant des cadavres, il abat les têtes sur l'immensité de la terre.","7":"Au torrent il s'abreuve en chemin, c'est pourquoi il redresse la tête."},"111":{"1":"Alleluia! Je rends grâce à Yahvé de tout coeur dans le cercle des justes et l'assemblée.","2":"Grandes sont les oeuvres de Yahvé, dignes d'étude pour qui les aime.","3":"Faste et splendeur, son ouvrage; sa justice demeure à jamais.","4":"Il laisse un mémorial de ses merveilles. Yahvé est tendresse et pitié.","5":"Il donne à qui le craint la nourriture, il se souvient de son alliance pour toujours.","6":"Il fait voir à son peuple la vertu de ses oeuvres, en lui donnant l'héritage des nations.","7":"Justice et vérité, les oeuvres de ses mains, fidélité, toutes ses lois,","8":"établies pour toujours et à jamais, accomplies avec droiture et vérité.","9":"Il envoie la délivrance à son peuple, il déclare pour toujours son alliance; saint et redoutable est son nom.","10":"Principe du savoir: la crainte de Yahvé; bien avisés tous ceux qui s'y tiennent. Sa louange demeure à jamais."},"112":{"1":"Alleluia! Heureux l'homme qui craint Yahvé, et se plaît fort à ses préceptes!","2":"Sa lignée sera puissante sur la terre, et bénie la race des hommes droits.","3":"Opulence et bien-être en sa maison; sa justice demeure à jamais.","4":"Il se lève en la ténèbre, lumière des coeurs droits, pitié, tendresse et justice.","5":"Bienheureux l'homme qui prend pitié et prête, qui règle ses affaires avec droiture.","6":"Non, jamais il ne chancelle, en mémoire éternelle sera le juste.","7":"Il ne craint pas d'annonces de malheur, ferme est son coeur, confiant en Yahvé;","8":"son coeur est assuré, il ne craint pas: à la fin il toisera ses oppresseurs.","9":"Il fait largesse, il donne aux pauvres; sa justice demeure à jamais, sa vigueur rehausse son prestige.","10":"L'impie le voit et s'irrite, il grince des dents et dépérit. Le désir des impies va se perdre."},"113":{"1":"Alleluia! Louez, serviteurs de Yahvé, louez le nom de Yahvé!","2":"Béni soit le nom de Yahvé, dès maintenant et à jamais!","3":"Du lever du soleil à son coucher, loué soit le nom de Yahvé!","4":"Plus haut que tous les peuples, Yahvé! plus haut que tous les cieux, sa gloire!","5":"Qui est comme Yahvé notre Dieu, lui qui s'élève pour siéger","6":"et s'abaisse pour voir cieux et terre?","7":"De la poussière il relève le faible, du fumier il retire le pauvre,","8":"pour l'asseoir au rang des princes, au rang des princes de son peuple.","9":"Il assied la stérile en sa maison, mère en ses fils heureuse."},"114":{"1":"Alleluia! Quand Israël sortit d'Egypte, la maison de Jacob, de chez un peuple barbare,","2":"Juda lui devint un sanctuaire, et Israël, son domaine.","3":"La mer voit et s'enfuit, le Jourdain retourne en arrière;","4":"les montagnes sautent comme des béliers et les collines comme des agneaux.","5":"Qu'as-tu, mer, à t'enfuir, Jourdain, à retourner en arrière,","6":"et vous, montagnes, à sauter comme des béliers, collines, comme des agneaux?","7":"Tremble, terre, devant la face du Maître, devant la face du Dieu de Jacob,","8":"qui change le rocher en étang et le caillou en source."},"115":{"1":"Non pas à nous, Yahvé, non pas à nous, mais à ton nom rapporte la gloire, pour ton amour et pour ta vérité!","2":"Que les païens ne disent: \"Où est leur Dieu?\"","3":"Notre Dieu, il est dans les cieux, tout ce qui lui plaît, il le fait.","4":"Leurs idoles, or et argent, une oeuvre de main d'homme!","5":"Elles ont une bouche et ne parlent pas, elles ont des yeux et ne voient pas,","6":"elles ont des oreilles et n'entendent pas, elles ont un nez et ne sentent pas.","7":"Leurs mains, mais elles ne touchent point, leurs pieds, mais ils ne marchent point, de leur gosier, pas un murmure!","8":"Comme elles, seront ceux qui les firent, quiconque met en elles sa foi.","9":"Maison d'Israël, mets ta foi en Yahvé, lui, leur secours et bouclier!","10":"Maison d'Aaron, mets ta foi en Yahvé, lui, leur secours et bouclier!","11":"Ceux qui craignent Yahvé, ayez foi en Yahvé, lui, leur secours et bouclier!","12":"Yahvé se souvient de nous, il bénira, il bénira la maison d'Israël, il bénira la maison d'Aaron,","13":"il bénira ceux qui craignent Yahvé, les petits avec les grands.","14":"Que Yahvé vous fasse croître, vous et vos enfants!","15":"Bénis soyez-vous de Yahvé qui a fait le ciel et la terre!","16":"Le ciel, c'est le ciel de Yahvé, la terre, il l'a donnée aux fils d'Adam.","17":"Non, les morts ne louent point Yahvé, ni tous ceux qui descendent au Silence;","18":"mais nous, les vivants, nous bénissons Yahvé dès maintenant et à jamais."},"116":{"1":"Alleluia! J'aime, lorsque Yahvé entend le cri de ma prière,","2":"lorsqu'il tend l'oreille vers moi, le jour où j'appelle.","3":"Les lacets de la mort m'enserraient, les filets du shéol; l'angoisse et l'affliction me tenaient,","4":"j'appelai le nom de Yahvé. De grâce, Yahvé, délivre mon âme!","5":"Yahvé a pitié, il est juste, notre Dieu est tendresse;","6":"Yahvé protège les simples, je faiblissais, il m'a sauvé.","7":"Retourne, mon âme, à ton repos, car Yahvé t'a fait du bien.","8":"Il a gardé mon âme de la mort, mes yeux des larmes et mes pieds du faux pas:","9":"je marcherai à la face de Yahvé sur la terre des vivants.","10":"Je crois lors même que je dis: \"Je suis trop malheureux\",","11":"moi qui ai dit dans mon trouble: \"Tout homme n'est que mensonge.\"","12":"Comment rendrai-je à Yahvé tout le bien qu'il m'a fait?","13":"J'élèverai la coupe du salut, j'appellerai le nom de Yahvé.","14":"J'accomplirai mes voeux envers Yahvé, oui, devant tout son peuple!","15":"Elle coûte aux yeux de Yahvé, la mort de ses amis.","16":"De grâce, Yahvé, je suis ton serviteur, je suis ton serviteur fils de ta servante, tu as défait mes liens.","17":"Je t'offrirai le sacrifice d'action de grâces, j'appellerai le nom de Yahvé.","18":"J'accomplirai mes voeux envers Yahvé, oui, devant tout son peuple,","19":"dans les parvis de la maison de Yahvé, au milieu de toi, Jérusalem!"},"117":{"1":"Alleluia! Louez Yahvé, tous les peuples, fêtez-le, tous les pays!","2":"Fort est son amour pour nous, pour toujours sa vérité."},"118":{"1":"Alleluia! Rendez grâce à Yahvé, car il est bon, car éternel est son amour!","2":"Qu'elle le dise, la maison d'Israël: éternel est son amour!","3":"Qu'elle le dise, la maison d'Aaron: éternel est son amour!","4":"Qu'ils le disent, ceux qui craignent Yahvé: éternel est son amour!","5":"De mon angoisse, j'ai crié vers Yahvé, il m'exauça, me mit au large.","6":"Yahvé est pour moi, plus de crainte, que me fait l'homme, à moi?","7":"Yahvé est pour moi, mon aide entre tous, j'ai toisé mes ennemis.","8":"Mieux vaut s'abriter en Yahvé que se fier en l'homme;","9":"mieux vaut s'abriter en Yahvé que se fier aux puissants.","10":"Les païens m'ont tous entouré, au nom de Yahvé je les sabre;","11":"ils m'ont entouré, enserré, au nom de Yahvé je les sabre;","12":"ils m'ont entouré comme des guêpes, ils ont flambé comme feu de ronces, au nom de Yahvé je les sabre.","13":"On m'a poussé, poussé pour m'abattre, mais Yahvé me vient en aide;","14":"ma force et mon chant, c'est Yahvé, il fut pour moi le salut.","15":"Clameurs de joie et de salut sous les tentes des justes: \"La droite de Yahvé a fait prouesse,","16":"la droite de Yahvé a le dessus, la droite de Yahvé a fait prouesse! \"","17":"Non, je ne mourrai pas, je vivrai et publierai les oeuvres de Yahvé;","18":"il m'a châtié et châtié, Yahvé, à la mort il ne m'a pas livré.","19":"Ouvrez-moi les portes de justice, j'entrerai, je rendrai grâce à Yahvé!","20":"C'est ici la porte de Yahvé, les justes entreront.","21":"Je te rends grâce, car tu m'as exaucé, tu fus pour moi le salut.","22":"La pierre qu'ont rejetée les bâtisseurs est devenue la tête de l'angle;","23":"c'est là l'oeuvre de Yahvé, ce fut merveille à nos yeux.","24":"Voici le jour que fit Yahvé, pour nous allégresse et joie.","25":"De grâce, Yahvé, donne le salut! De grâce, Yahvé, donne la victoire!","26":"Béni soit au nom de Yahvé celui qui vient! Nous vous bénissons de la maison de Yahvé.","27":"Yahvé est Dieu, il nous illumine. Serrez vos cortèges, rameaux en main, jusqu'aux cornes de l'autel.","28":"C'est toi mon Dieu, je te rends grâce, mon Dieu, je t'exalte; je te rends grâce, car tu m'as exaucé, tu fus pour moi le salut.","29":"Rendez grâce à Yahvé, car il est bon, car éternel est son amour!"},"120":{"1":"Cantique des montées. Vers Yahvé, quand l'angoisse me prend, je crie, il me répond.","2":"Yahvé, délivre-moi des lèvres fausses, de la langue perfide!","3":"Que va-t-il te donner, et quoi encore, langue perfide?","4":"Les flèches du batailleur, qu'on aiguise à la braise des genêts.","5":"Malheur à moi de vivre en Méshek, d'habiter les tentes de Qédar!","6":"Mon âme a trop vécu parmi des gens qui haïssent la paix.","7":"Moi, si je parle de paix, eux sont pour la guerre."},"121":{"1":"Cantique pour les montées. Je lève les yeux vers les monts: d'où viendra mon secours?","2":"Le secours me vient de Yahvé qui a fait le ciel et la terre.","3":"Qu'il ne laisse broncher ton pied! qu'il ne dorme, ton gardien!","4":"Vois, il ne dort ni ne sommeille, le gardien d'Israël.","5":"Yahvé est ton gardien, ton ombrage, Yahvé, à ta droite.","6":"De jour, le soleil ne te frappe, ni la lune en la nuit.","7":"Yahvé te garde de tout mal, il garde ton âme.","8":"Yahvé te garde au départ, au retour, dès lors et à jamais."},"122":{"1":"Cantique des montées. De David. J'étais joyeux que l'on me dise: Allons à la maison de Yahvé!","2":"Enfin nos pieds s'arrêtent dans tes portes, Jérusalem!","3":"Jérusalem, bâtie comme une ville où tout ensemble fait corps,","4":"Là où montent les tribus, les tribus de Yahvé, est pour Israël une raison de rendre grâce au nom de Yahvé.","5":"Car ils sont là, les sièges du jugement, les sièges de la maison de David.","6":"Appelez la paix sur Jérusalem: que reposent tes tentes!","7":"Advienne la paix dans tes murs: repos en tes palais!","8":"Pour l'amour de mes frères, de mes amis, laisse-moi dire: paix sur toi!","9":"Pour l'amour de la maison de Yahvé notre Dieu, je prie pour ton bonheur!"},"123":{"1":"Cantique des montées. Vers toi j'ai les yeux levés, qui te tiens au ciel;","2":"les voici comme les yeux des serviteurs vers la main de leur maître. Comme les yeux de la servante vers la main de sa maîtresse, ainsi nos yeux vers Yahvé notre Dieu, tant qu'il nous prenne en pitié.","3":"Pitié pour nous, Yahvé, pitié pour nous, trop de mépris nous rassasie;","4":"notre âme est par trop rassasiée des sarcasmes des satisfaits! (Le mépris est pour les orgueilleux! )"},"119":{"1":"Heureux, impeccables en leur voie, ceux qui marchent dans la loi de Yahvé!","2":"Heureux, gardant son témoignage, ceux qui le cherchent de tout coeur,","3":"et qui sans commettre de mal, marchent dans ses voies!","4":"Toi, tu promulgues tes préceptes, à observer entièrement.","5":"Puissent mes voies se fixer à observer tes volontés.","6":"Alors je n'aurai nulle honte en revoyant tous tes commandements.","7":"Je te rendrai grâce en droiture de coeur, instruit de tes justes jugements.","8":"Tes volontés, je les veux observer, ne me délaisse pas entièrement.","9":"Comment, jeune, garder pur son chemin? A observer ta parole.","10":"De tout mon coeur c'est toi que je cherche, ne m'écarte pas de tes commandements.","11":"Dans mon coeur j'ai conservé tes promesses pour ne point faillir envers toi.","12":"Béni que tu es Yahvé, apprends-moi tes volontés!","13":"De mes lèvres je les ai tous énumérés, les jugements de ta bouche.","14":"Dans la voie de ton témoignage j'ai ma joie plus qu'en toute richesse.","15":"Sur tes préceptes je veux méditer et regarder à tes chemins.","16":"Je trouve en tes volontés mes délices, je n'oublie pas ta parole.","17":"Sois bon pour ton serviteur et je vivrai, j'observerai ta parole.","18":"Ouvre mes yeux: je regarderai aux merveilles de ta loi.","19":"Etranger que je suis sur la terre, ne me cache pas tes commandements.","20":"Mon âme se consume à désirer en tout temps tes jugements.","21":"Tu t'en prends aux superbes, aux maudits, qui sortent de tes commandements.","22":"Décharge-moi de l'insulte et du mépris, car je garde ton témoignage.","23":"Que des princes tiennent séance et parlent contre moi, ton serviteur médite tes volontés.","24":"Ton témoignage, voilà mes délices, tes volontés, mes conseillers.","25":"Mon âme est collée à la poussière, vivifie-moi selon ta parole.","26":"J'énumère mes voies, tu me réponds, apprends-moi tes volontés.","27":"Fais-moi comprendre la voie de tes préceptes, je méditerai sur tes merveilles.","28":"Mon âme se fond de chagrin, relève-moi selon ta parole.","29":"Détourne-moi de la voie de mensonge, fais-moi la grâce de ta loi.","30":"J'ai choisi la voie de vérité, je me conforme à tes jugements.","31":"J'adhère à ton témoignage, Yahvé, ne me déçois pas.","32":"Je cours sur la voie de tes commandements, car tu as mis mon coeur au large.","33":"Enseigne-moi, Yahvé, la voie de tes volontés, je la veux garder en récompense.","34":"Fais-moi comprendre et que je garde ta loi, que je l'observe de tout coeur.","35":"Guide-moi au chemin de tes commandements, car j'ai là mon plaisir.","36":"Infléchis mon coeur vers ton témoignage, et non point vers le gain.","37":"Libère mes yeux des images de rien, vivifie-moi par ta parole.","38":"Tiens ta promesse à ton serviteur, afin qu'on te craigne.","39":"Libère-moi de l'insulte qui m'épouvante, tes jugements sont les bienvenus.","40":"Voici, j'ai désiré tes préceptes, vivifie-moi par ta justice.","41":"Que me vienne ton amour, Yahvé, ton salut selon ta promesse!","42":"Que je riposte à l'insulte par la parole, car je compte sur ta parole.","43":"N'ôte pas de ma bouche la parole de vérité, car j'espère en tes jugements.","44":"J'observerai ta loi sans relâche pour toujours et à jamais.","45":"Je serai au large en ma démarche, car je cherche tes préceptes.","46":"Devant les rois je parlerai de ton témoignage, et n'aurai nulle honte.","47":"Tes commandements ont fait mes délices, je les ai beaucoup aimés.","48":"Je tends les mains vers tes commandements que j'aime, tes volontés, je les médite.","49":"Rappelle-toi ta parole à ton serviteur, dont tu fis mon espoir.","50":"Voici ma consolation dans ma misère: ta promesse me vivifie.","51":"Les superbes m'ont bafoué à plaisir, sur ta loi je n'ai pas fléchi.","52":"Je me rappelle tes jugements d'autrefois, Yahvé, et je me console.","53":"La fureur me prend devant les impies, qui délaissent ta loi.","54":"Cantiques pour moi, que tes volontés, en ma demeure d'étranger.","55":"Je me rappelle dans la nuit ton nom, Yahvé, et j'observe ta loi.","56":"Voici qui est pour moi: garder tes préceptes.","57":"Ma part, ai-je dit, Yahvé, c'est d'observer tes paroles.","58":"De tout coeur, je veux attendrir ta face, pitié pour moi selon ta promesse!","59":"Je fais réflexion sur mes voies et je reviens à ton témoignage.","60":"Je me hâte et je ne retarde d'observer tes commandements.","61":"Les filets des impies m'environnent, je n'oublie pas ta loi.","62":"Je me lève à minuit, te rendant grâce pour tes justes jugements,","63":"allié que je suis de tous ceux qui te craignent et observent tes préceptes.","64":"De ton amour, Yahvé, la terre est pleine, apprends-moi tes volontés.","65":"Tu as fait du bien à ton serviteur, Yahvé, selon ta parole.","66":"Apprends-moi le bon sens et le savoir, car j'ai foi dans tes commandements.","67":"Avant d'être affligé je m'égarais, maintenant j'observe ta promesse.","68":"Toi, le bon, le bienfaisant, apprends-moi tes volontés.","69":"Les superbes m'engluent de mensonge, moi de tout coeur je garde tes préceptes.","70":"Leur coeur est épais comme la graisse, moi, ta loi fait mes délices.","71":"Un bien pour moi, que d'être affligé afin d'apprendre tes volontés.","72":"Un bien pour moi, que la loi de ta bouche, plus que millions d'or et d'argent.","73":"Tes mains m'ont fait et fixé, fais-moi comprendre, j'apprendrai tes commandements.","74":"Qui te craint me voit avec joie, car j'espère en ta parole.","75":"Je sais, Yahvé, qu'ils sont justes, tes jugements, que tu m'affliges avec vérité.","76":"Que ton amour me soit consolation, selon ta promesse à ton serviteur!","77":"Que m'advienne ta tendresse et je vivrai, car ta loi fait mes délices.","78":"Honte aux superbes qui m'accablent de mensonge! moi, je médite tes préceptes.","79":"Que se tournent vers moi ceux qui te craignent et qui savent ton témoignage!","80":"Que mon coeur soit impeccable en tes volontés: pas de honte alors pour moi.","81":"Jusqu'au bout mon âme ira pour ton salut, j'espère en ta parole.","82":"Jusqu'au bout mes yeux pour ta promesse, quand m'auras-tu consolé?","83":"Rendu pareil à une outre qu'on enfume, je n'oublie pas tes volontés.","84":"Combien seront les jours de ton serviteur, quand jugeras-tu mes persécuteurs?","85":"Des superbes me creusent des fosses à l'encontre de ta loi.","86":"Vérité, tous tes commandements: aide-moi, quand le mensonge me persécute.","87":"On viendrait à bout de moi sur terre, sans que je laisse tes préceptes.","88":"Selon ton amour vivifie-moi, je garderai le témoignage de ta bouche.","89":"A jamais, Yahvé, ta parole, immuable aux cieux;","90":"d'âge en âge, ta vérité; tu fixas la terre, elle subsiste;","91":"par tes jugements tout subsiste à ce jour, car toute chose est ta servante.","92":"Si ta loi n'eût fait mes délices, je périssais dans la misère.","93":"Jamais je n'oublierai tes préceptes, par eux tu me vivifies.","94":"Je suis tien, sauve-moi, je cherche tes préceptes.","95":"Que les impies me guettent pour ma perte, je comprends ton témoignage.","96":"De toute perfection j'ai vu le bout: combien large, ton commandement!","97":"Que j'aime ta loi! tout le jour, je la médite.","98":"Plus que mes ennemis tu me rends sage par ton commandement, toujours mien.","99":"Plus que tous mes maîtres j'ai la finesse, ton témoignage, je le médite.","100":"Plus que les anciens j'ai l'intelligence, tous tes préceptes, je les garde.","101":"A tout chemin de mal je soustrais mes pas, pour observer ta parole.","102":"De tes jugements je ne me détourne point, car c'est toi qui m'enseignes.","103":"Qu'elle est douce à mon palais ta promesse, plus que le miel à ma bouche!","104":"Par tes préceptes j'ai l'intelligence et je hais tout chemin de mensonge.","105":"Une lampe sur mes pas, ta parole, une lumière sur ma route.","106":"J'ai juré d'observer, et je tiendrai, tes justes jugements.","107":"Je suis au fond de la misère, Yahvé, vivifie-moi selon ta parole.","108":"Agrée l'offrande de ma bouche, Yahvé, apprends-moi tes jugements.","109":"Mon âme à tout moment entre mes mains, je n'oublie pas ta loi.","110":"Que les impies me tendent un piège, je ne dévie pas de tes préceptes.","111":"Ton témoignage est à jamais mon héritage, il est la joie de mon coeur.","112":"J'infléchis mon coeur à faire tes volontés, récompense pour toujours.","113":"Je hais les coeurs partagés et j'aime ta loi.","114":"Toi mon abri, mon bouclier, j'espère en ta parole.","115":"Détournez-vous de moi, méchants, je veux garder les commandements de mon Dieu.","116":"Sois mon soutien selon ta promesse et je vivrai, ne fais pas honte à mon attente.","117":"Sois mon appui et je serai sauvé, mes yeux sur tes volontés sans relâche.","118":"Tu renverses tous ceux qui sortent de tes volontés, mensonge est leur calcul.","119":"Tu considères comme une rouille tous les impies de la terre, aussi j'aime ton témoignage.","120":"De ton effroi tremble ma chair, sous tes jugements je crains.","121":"Mon action fut jugement et justice, ne me livre pas à mes bourreaux.","122":"A ton serviteur sois allié pour le bien, que les superbes ne me torturent.","123":"Jusqu'au bout vont mes yeux pour ton salut, pour ta promesse de justice.","124":"Agis avec ton serviteur selon ton amour, apprends-moi tes volontés.","125":"Je suis ton serviteur, fais-moi comprendre, et je saurai ton témoignage.","126":"Il est temps d'agir, Yahvé: on a violé ta loi.","127":"Aussi j'aime tes commandements, plus que l'or et que l'or fin.","128":"Aussi je me règle sur tous tes préceptes et je hais tout chemin de mensonge.","129":"Merveille que ton témoignage; aussi mon âme le garde.","130":"Ta parole en se découvrant illumine, et les simples comprennent.","131":"J'ouvre large ma bouche et j'aspire, avide de tes commandements.","132":"Regarde vers moi, pitié pour moi, c'est justice pour les amants de ton nom.","133":"Fixe mes pas dans ta promesse, que ne triomphe de moi le mal.","134":"Rachète-moi de la torture de l'homme, j'observerai tes préceptes.","135":"Pour ton serviteur illumine ta face, apprends-moi tes volontés.","136":"Mes yeux ruissellent de larmes, car on n'observe pas ta loi.","137":"O juste que tu es, Yahvé! Droiture que tes jugements.","138":"Tu imposes comme justice ton témoignage, comme entière vérité.","139":"Mon zèle me consume, car mes oppresseurs oublient ta parole.","140":"Ta promesse est éprouvée entièrement, ton serviteur la chérit.","141":"Chétif que je suis et méprisé, je n'oublie pas tes préceptes.","142":"Justice éternelle que ta justice, vérité que ta loi.","143":"Angoisse, oppression m'ont saisi, tes commandements font mes délices.","144":"Justice éternelle que ton témoignage, fais-moi comprendre et je vivrai.","145":"J'appelle de tout coeur, réponds-moi, Yahvé, je garderai tes volontés.","146":"Je t'appelle, sauve-moi, j'observerai ton témoignage.","147":"Je devance l'aurore et j'implore, j'espère en ta parole.","148":"Mes yeux devancent les veilles pour méditer sur ta promesse.","149":"En ton amour écoute ma voix, Yahvé, en tes jugements vivifie-moi.","150":"Ils s'approchent de l'infamie, mes persécuteurs, ils s'éloignent de ta loi.","151":"Tu es proche, toi, Yahvé, vérité que tous tes commandements.","152":"Dès longtemps, j'ai su de ton témoignage qu'à jamais tu l'as fondé.","153":"Vois ma misère, délivre-moi, car je n'oublie pas ta loi.","154":"Plaide ma cause, défends-moi, en ta promesse vivifie-moi.","155":"Il est loin des impies, le salut, ils ne recherchent pas tes volontés.","156":"Nombreuses tes tendresses, Yahvé, en tes jugements vivifie-moi.","157":"Nombreux mes persécuteurs, mes oppresseurs, je n'ai pas fléchi sur ton témoignage.","158":"J'ai vu les renégats, ils m'écoeurent, ils n'observent pas ta promesse.","159":"Vois si j'aime tes préceptes, Yahvé, en ton amour vivifie-moi.","160":"Vérité, le principe de ta parole! pour l'éternité, tes justes jugements.","161":"Des princes me persécutent sans raison, mon coeur redoute ta parole.","162":"Joie pour moi dans ta promesse, comme à trouver grand butin.","163":"Le mensonge, je le hais, je l'exècre, ta loi, je l'aime.","164":"Sept fois le jour, je te loue pour tes justes jugements.","165":"Grande paix pour les amants de ta loi, pour eux rien n'est scandale.","166":"J'attends ton salut, Yahvé, tes commandements, je les suis.","167":"Mon âme observe ton témoignage, je l'aime entièrement.","168":"J'observe tes préceptes, ton témoignage, toutes mes voies sont devant toi.","169":"Que mon cri soit proche de ta face, Yahvé, par ta parole fais-moi comprendre.","170":"Que ma prière arrive devant ta face, par ta promesse délivre-moi.","171":"Que mes lèvres publient ta louange, car tu m'apprends tes volontés.","172":"Que ma langue redise ta promesse, car tous tes commandements sont justice.","173":"Que ta main me soit en aide, car j'ai choisi tes préceptes.","174":"J'ai désir de ton salut, Yahvé, ta loi fait mes délices.","175":"Que vive mon âme à te louer, tes jugements me soient en aide!","176":"Je m'égare, brebis perdue: viens chercher ton serviteur. Non, je n'ai pas oublié tes commandements."},"124":{"1":"Cantique des montées. De David. Sans Yahvé qui était pour nous -- à Israël de le dire --","2":"sans Yahvé qui était pour nous quand on sauta sur nous,","3":"alors ils nous avalaient tout vifs dans le feu de leur colère.","4":"Alors les eaux nous submergeaient, le torrent passait sur nous,","5":"alors il passait sur notre âme en eaux écumantes.","6":"Béni Yahvé qui n'a point fait de nous la proie de leurs dents!","7":"Notre âme comme un oiseau s'est échappée du filet de l'oiseleur. Le filet s'est rompu et nous avons échappé;","8":"notre secours est dans le nom de Yahvé qui a fait le ciel et la terre."},"125":{"1":"Cantique des montées. Qui s'appuie sur Yahvé ressemble au mont Sion: rien ne l'ébranle, il est stable pour toujours.","2":"Jérusalem! les montagnes l'entourent, ainsi Yahvé entoure son peuple dès maintenant et pour toujours.","3":"Jamais un sceptre impie ne tombera sur la part des justes, de peur que ne tende au crime la main des justes.","4":"Fais du bien, Yahvé, aux gens de bien, qui ont au coeur la droiture.","5":"Mais les tortueux, les dévoyés, qu'il les repousse, Yahvé, avec les malfaisants! Paix sur Israël!"},"126":{"1":"Cantique des montées. Quand Yahvé ramena les captifs de Sion, nous étions comme en rêve;","2":"alors notre bouche s'emplit de rire et nos lèvres de chansons. Alors on disait chez les païens: Merveilles que fit pour eux Yahvé!","3":"Merveilles que fit pour nous Yahvé, nous étions dans la joie.","4":"Ramène, Yahvé, nos captifs comme torrents au Négeb!","5":"Ceux qui sèment dans les larmes moissonnent en chantant.","6":"Il s'en va, il s'en va en pleurant, il porte la semence; il s'en vient, il s'en vient en chantant, il rapporte ses gerbes."},"127":{"1":"Cantique des montées. De Salomon. Si Yahvé ne bâtit la maison, en vain peinent les bâtisseurs; si Yahvé ne garde la ville, en vain la garde veille.","2":"Vanité de vous lever matin, de retarder votre coucher, mangeant le pain des douleurs, quand Lui comble son bien-aimé qui dort.","3":"C'est l'héritage de Yahvé que des fils, récompense, que le fruit des entrailles;","4":"comme flèches en la main du héros, ainsi les fils de la jeunesse.","5":"Heureux l'homme, celui-là qui en a rempli son carquois; point de honte pour eux, quand ils débattent à la porte, avec leurs ennemis."},"128":{"1":"Cantique des montées. Heureux tous ceux qui craignent Yahvé et marchent dans ses voies!","2":"Du labeur de tes mains tu te nourriras, heur et bonheur pour toi!","3":"Ton épouse: une vigne fructueuse au fort de ta maison. Tes fils: des plants d'olivier à l'entour de la table.","4":"Voilà de quels biens sera béni l'homme qui craint Yahvé.","5":"Que Yahvé te bénisse de Sion! Puisses-tu voir Jérusalem dans le bonheur tous les jours de ta vie,","6":"et voir les fils de tes fils! Paix sur Israël!"},"129":{"1":"Cantique des montées. Tant ils m'ont traqué dès ma jeunesse, -- à Israël de le dire --","2":"tant ils m'ont traqué dès ma jeunesse, ils n'ont pas eu le dessus.","3":"Sur mon dos ont labouré les laboureurs, allongeant leurs sillons;","4":"Yahvé le juste a brisé les liens des impies.","5":"Qu'ils soient tous confondus, repoussés, les ennemis de Sion;","6":"qu'ils soient comme l'herbe des toits qui sèche avant qu'on l'arrache!","7":"Le moissonneur n'en remplit pas sa main, ni le lieur, son giron;","8":"et point ne diront les passants: Bénédiction de Yahvé sur vous! Nous vous bénissons au nom de Yahvé."},"130":{"1":"Cantique des montées. Des profondeurs je crie vers toi, Yahvé:","2":"Seigneur, écoute mon appel. Que ton oreille se fasse attentive à l'appel de ma prière!","3":"Si tu retiens les fautes, Yahvé, Seigneur, qui subsistera?","4":"Mais le pardon est près de toi, pour que demeure ta crainte.","5":"J'espère, Yahvé, elle espère, mon âme, en ta parole;","6":"mon âme attend le Seigneur plus que les veilleurs l'aurore; plus que les veilleurs l'aurore,","7":"qu'Israël attende Yahvé! Car près de Yahvé est la grâce, près de lui, l'abondance du rachat;","8":"c'est lui qui rachètera Israël de toutes ses fautes."},"131":{"1":"Cantique des montées. De David. Yahvé, je n'ai pas le coeur fier, ni le regard hautain. Je n'ai pas pris un chemin de grandeurs ni de prodiges qui me dépassent.","2":"Non, je tiens mon âme en paix et silence; comme un petit enfant contre sa mère, comme un petit enfant, telle est mon âme en moi.","3":"Mets ton espoir, Israël, en Yahvé, dès maintenant et à jamais!"},"132":{"1":"Cantique des montées. Garde mémoire à David, Yahvé, de tout son labeur,","2":"du serment qu'il fit à Yahvé, de son voeu au Puissant de Jacob:","3":"\"Point n'entrerai sous la tente, ma maison, point ne monterai sur le lit de mon repos,","4":"point ne donnerai de sommeil à mes yeux et point de répit à mes paupières,","5":"que je ne trouve un lieu pour Yahvé, un séjour au Puissant de Jacob! \"","6":"Voici: on parle d'Elle en Ephrata, nous l'avons découverte aux Champs-du-Bois!","7":"Entrons au lieu où Il séjourne, prosternons-nous devant son marchepied.","8":"Lève-toi, Yahvé, vers ton repos, toi et l'arche de ta force.","9":"Tes prêtres se vêtent de justice, tes fidèles crient de joie.","10":"A cause de David ton serviteur, n'écarte pas la face de ton messie.","11":"Yahvé l'a juré à David, vérité dont jamais il ne s'écarte: \"C'est le fruit sorti de tes entrailles que je mettrai sur le trône fait pour toi.","12":"Si tes fils gardent mon alliance, mon témoignage que je leur ai enseigné, leurs fils eux-mêmes à tout jamais siégeront sur le trône fait pour toi.\"","13":"Car Yahvé a fait choix de Sion, il a désiré ce siège pour lui:","14":"\"C'est ici mon repos à tout jamais, là je siégerai, car je l'ai désiré.","15":"Sa nourriture, je la bénirai de bénédiction ses pauvres, je les rassasierai de pain,","16":"ses prêtres, je les vêtirai de salut et ses fidèles jubileront de joie.","17":"Là, je susciterai une lignée à David, j'apprêterai une lampe pour mon messie;","18":"ses ennemis, je les vêtirai de honte, mais sur lui fleurira son diadème.\""},"133":{"1":"Cantique des montées. De David. Voyez! Qu'il est bon, qu'il est doux d'habiter en frères tous ensemble!","2":"C'est une huile excellente sur la tête, qui descend sur la barbe, qui descend sur la barbe d'Aaron, sur le col de ses tuniques.","3":"C'est la rosée de l'Hermon, qui descend sur les hauteurs de Sion; là, Yahvé a voulu la bénédiction, la vie à jamais."},"134":{"1":"Cantique des montées. Allons! bénissez Yahvé, tous les serviteurs de Yahvé, officiant dans la maison de Yahvé, dans les parvis de la maison de notre Dieu. Dans les nuits","2":"levez vos mains vers le sanctuaire, et bénissez Yahvé.","3":"Que Yahvé te bénisse de Sion, lui qui fit le ciel et la terre!"},"135":{"1":"Alleluia! Louez le nom de Yahvé, louez, serviteurs de Yahvé,","2":"officiant dans la maison de Yahvé, dans les parvis de la maison de notre Dieu.","3":"Louez Yahvé, car il est bon, Yahvé, jouez pour son nom, car il est doux.","4":"C'est Jacob que Yahvé s'est choisi, Israël dont il fit son apanage.","5":"Moi je sais qu'il est grand, Yahvé, que notre Seigneur surpasse tous les dieux.","6":"Tout ce qui plaît à Yahvé, il le fait, au ciel et sur terre, dans les mers et tous les abîmes.","7":"Faisant monter les nuages du bout de la terre, il produit avec les éclairs la pluie, il tire le vent de ses trésors.","8":"Il frappa les premiers-nés d'Egypte depuis l'homme jusqu'au bétail;","9":"il envoya signes et prodiges au milieu de toi, Egypte, sur Pharaon et tous ses serviteurs.","10":"Il frappa des païens en grand nombre, fit périr des rois valeureux,","11":"Sihôn, roi des Amorites, et Og, roi du Bashân, et tous les royaumes de Canaan;","12":"et il donna leur terre en héritage, en héritage à Israël son peuple.","13":"Yahvé, ton nom à jamais! Yahvé, ton souvenir d'âge en âge!","14":"Car Yahvé prononce pour son peuple, il s'émeut pour ses serviteurs.","15":"Les idoles des païens, or et argent, une oeuvre de main d'homme!","16":"elles ont une bouche et ne parlent pas, elles ont des yeux et ne voient pas.","17":"Elles ont des oreilles et n'entendent pas, pas le moindre souffle en leur bouche.","18":"Comme elles, seront ceux qui les firent, quiconque met en elles sa foi.","19":"Maison d'Israël, bénissez Yahvé, maison d'Aaron, bénissez Yahvé,","20":"maison de Lévi, bénissez Yahvé, ceux qui craignent Yahvé, bénissez Yahvé.","21":"Béni soit Yahvé depuis Sion, lui qui habite Jérusalem!"},"136":{"1":"Alleluia! Rendez grâce à Yahvé, car il est bon, car éternel est son amour!","2":"Rendez grâce au Dieu des dieux, car éternel est son amour!","3":"Rendez grâce au Seigneur des seigneurs, car éternel est son amour!","4":"Lui seul a fait des merveilles, car éternel est son amour!","5":"Il fit les cieux avec sagesse car éternel est son amour!","6":"Il affermit la terre sur les eaux, car éternel est son amour!","7":"Il a fait les grands luminaires, car éternel est son amour!","8":"Le soleil pour gouverner sur le jour, car éternel est son amour!","9":"La lune et les étoiles pour gouverner sur la nuit, car éternel est son amour!","10":"Il frappa l'Egypte en ses premiers-nés, car éternel est son amour!","11":"Et de là fit sortir Israël, car éternel est son amour!","12":"A main forte et à bras étendu, car éternel est son amour!","13":"Il sépara en deux parts la mer des Joncs, car éternel est son amour!","14":"Et fit passer Israël en son milieu, car éternel est son amour!","15":"Y culbutant Pharaon et son armée, car éternel est son amour!","16":"Il mena son peuple au désert, car éternel est son amour!","17":"Il frappa des rois puissants, car éternel est son amour!","18":"Fit périr des rois redoutables, car éternel est son amour!","19":"Sihôn, roi des Amorites, car éternel est son amour!","20":"Et Og, roi du Bashân, car éternel est son amour!","21":"Il donna leur terre en héritage, car éternel est son amour!","22":"En héritage à Israël son serviteur, car éternel est son amour!","23":"Il se souvint de nous dans notre abaissement, car éternel est son amour!","24":"Il nous sauva de la main des oppresseurs, car éternel est son amour!","25":"A toute chair il donne le pain, car éternel est son amour!","26":"Rendez grâce au Dieu du ciel, car éternel est son amour!"},"137":{"1":"Au bord des fleuves de Babylone nous étions assis et nous pleurions, nous souvenant de Sion;","2":"aux peupliers d'alentour nous avions pendu nos harpes.","3":"Et c'est là qu'ils nous demandèrent, nos geôliers, des cantiques, nos ravisseurs, de la joie: \"Chantez-nous, disaient-ils, un cantique de Sion.\"","4":"Comment chanterions-nous un cantique de Yahvé sur une terre étrangère?","5":"Si je t'oublie, Jérusalem, que ma droite se dessèche!","6":"Que ma langue s'attache à mon palais si je perds ton souvenir, si je ne mets Jérusalem au plus haut de ma joie!","7":"Souviens-toi, Yahvé, contre les fils d'Edom, du Jour de Jérusalem, quand ils disaient: \"A bas! Rasez jusqu'aux assises! \"","8":"Fille de Babel, qui dois périr, heureux qui te revaudra les maux que tu nous valus,","9":"heureux qui saisira et brisera tes petits contre le roc!"},"138":{"1":"De David. Je te rends grâce, Yahvé, de tout mon coeur, tu as entendu les paroles de ma bouche. Je te chante en présence des anges,","2":"je me prosterne vers ton temple sacré. Je rends grâce à ton nom pour ton amour et ta vérité; ta promesse a même surpassé ton renom.","3":"Le jour où j'ai crié, tu m'exauças, tu as accru la force en mon âme.","4":"Tous les rois de la terre te rendent grâce, Yahvé, car ils entendent les promesses de ta bouche;","5":"ils célèbrent les voies de Yahvé: \"Grande est la gloire de Yahvé!","6":"Sublime, Yahvé! et il voit les humbles et de loin connaît les superbes.\"","7":"Si je marche au milieu des angoisses, tu me fais vivre, à la fureur de mes ennemis; tu étends la main et ta droite me sauve.","8":"Yahvé aura tout fait pour moi; Yahvé, éternel est ton amour, ne délaisse pas l'oeuvre de tes mains."},"139":{"1":"Du maître de chant. De David. Psaume. Yahvé, tu me sondes et me connais;","2":"que je me lève ou m'assoie, tu le sais, tu perces de loin mes pensées;","3":"que je marche ou me couche, tu le sens, mes chemins te sont tous familiers.","4":"La parole n'est pas encore sur ma langue, et voici, Yahvé, tu la sais tout entière;","5":"derrière et devant tu m'enserres, tu as mis sur moi ta main.","6":"Merveille de science qui me dépasse, hauteur où je ne puis atteindre.","7":"Où irai-je loin de ton esprit, où fuirai-je loin de ta face?","8":"Si j'escalade les cieux, tu es là, qu'au shéol je me couche, te voici.","9":"Je prends les ailes de l'aurore, je me loge au plus loin de la mer,","10":"même là, ta main me conduit, ta droite me saisit.","11":"Je dirai: \"Que me presse la ténèbre, que la nuit soit pour moi une ceinture\";","12":"même la ténèbre n'est point ténèbre devant toi et la nuit comme le jour illumine.","13":"C'est toi qui m'as formé les reins, qui m'as tissé au ventre de ma mère;","14":"je te rends grâce pour tant de prodiges: merveille que je suis, merveille que tes oeuvres. Mon âme, tu la connaissais bien,","15":"mes os n'étaient point cachés de toi, quand je fus façonné dans le secret, brodé au profond de la terre.","16":"Mon embryon, tes yeux le voyaient; sur ton livre, ils sont tous inscrits les jours qui ont été fixés, et chacun d'eux y figure.","17":"Mais pour moi, que tes pensées sont difficiles, ô Dieu, que la somme en est imposante!","18":"Je les compte, il en est plus que sable; ai-je fini, je suis encore avec toi.","19":"Si tu voulais, ô Dieu, tuer l'impie! Hommes de sang, allez-vous-en de moi!","20":"Eux qui parlent de toi sournoisement, qui tiennent pour rien tes pensées.","21":"Yahvé, n'ai-je pas en haine qui te hait, en dégoût, ceux qui se dressent contre toi?","22":"Je les hais d'une haine parfaite, ce sont pour moi des ennemis.","23":"Sonde-moi, ô Dieu, connais mon coeur, scrute-moi, connais mon souci;","24":"vois que mon chemin ne soit fatal, conduis-moi sur le chemin d'éternité."},"140":{"1":"Du maître de chant. Psaume de David.","2":"Délivre-moi, Yahvé, des mauvaises gens, contre l'homme de violence défends-moi,","3":"ceux dont le coeur médite le mal, qui tout le jour hébergent la guerre,","4":"qui aiguisent leur langue ainsi qu'un serpent, un venin de vipère sous la lèvre.","5":"Garde-moi, Yahvé, des mains de l'impie, contre l'homme de violence défends-moi, ceux qui méditent de me faire trébucher,","6":"qui tendent un filet sous mes pieds, insolents qui m'ont caché une trappe et des lacets, m'ont posé des pièges au passage.","7":"J'ai dit à Yahvé: C'est toi mon Dieu, entends, Yahvé, le cri de ma prière.","8":"Yahvé mon Seigneur, force de mon salut, tu me couvres la tête au jour du combat.","9":"Ne consens pas, Yahvé, aux désirs des impies, ne fais pas réussir leurs complots. Que sur moi les assiégeants ne dressent","10":"leur tête, que la malice de leurs lèvres les accable;","11":"qu'il pleuve sur eux des charbons de feu, que jetés à l'abîme ils ne se lèvent plus:","12":"que le calomniateur ne tienne plus sur la terre, que le mal pourchasse à mort le violent!","13":"Je sais que Yahvé fera droit aux malheureux, fera justice aux pauvres.","14":"Oui, les justes rendront grâce à ton nom, les saints vivront avec ta face."},"141":{"1":"Psaume de David. Yahvé, je t'appelle, accours vers moi, écoute ma voix qui t'appelle;","2":"que monte ma prière, en encens devant ta face, les mains que j'élève, en offrande du soir!","3":"Etablis, Yahvé, une garde à ma bouche, veille sur la porte de mes lèvres.","4":"Retiens mon coeur de parler mal, de commettre l'impiété en compagnie des malfaisants. Non, je ne goûterai pas à leurs plaisirs!","5":"Que le juste me frappe en ami et me corrige, que l'huile de l'impie jamais n'orne ma tête, car je me compromettrais encore dans leurs méfaits.","6":"Ils sont livrés à l'empire du Rocher, leur juge, eux qui avaient pris plaisir à m'entendre dire:","7":"\"Comme une meule éclatée par terre, nos os sont dispersés à la bouche du shéol.\"","8":"Vers toi, Yahvé, mes yeux, en toi je m'abrite, ne répands pas mon âme;","9":"garde-moi d'être pris au piège qu'on me tend, au traquenard des malfaisants.","10":"Qu'ils tombent, les impies, chacun dans son filet, tandis que moi, je passe."},"142":{"1":"Poème. De David. Quand il était dans la caverne. Prière.","2":"A Yahvé mon cri! J'implore. A Yahvé mon cri! Je supplie.","3":"Je déverse devant lui ma plainte, ma détresse, je la mets devant lui,","4":"alors que le souffle me manque; mais toi, tu connais mon sentier. Sur le chemin où je vais ils m'ont caché un piège.","5":"Regarde à droite et vois, pas un qui me reconnaisse. Le refuge se dérobe à moi, pas un qui ait soin de mon âme.","6":"Je m'écrie vers toi, Yahvé, je dis: Toi, mon abri, ma part dans la terre des vivants!","7":"Sois attentif à ma clameur, je suis à bout de force. Délivre-moi de mes persécuteurs, eux sont plus forts que moi!","8":"Fais sortir de prison mon âme, que je rende grâce à ton nom! Autour de moi les justes feront cercle, à cause du bien que tu m'as fait."},"143":{"1":"Psaume de David. Yahvé, écoute ma prière, prête l'oreille à mes supplications, en ta fidélité réponds-moi, en ta justice;","2":"n'entre pas en jugement avec ton serviteur, nul vivant n'est justifié devant toi.","3":"L'ennemi pourchasse mon âme, contre terre il écrase ma vie; il me fait habiter dans les ténèbres comme ceux qui sont morts à jamais;","4":"le souffle en moi s'éteint, mon coeur au fond de moi s'épouvante.","5":"Je me souviens des jours d'autrefois, je me redis toutes tes oeuvres, sur l'ouvrage de tes mains je médite;","6":"je tends les mains vers toi, mon âme est une terre assoiffée de toi.","7":"Viens vite, réponds-moi, Yahvé, je suis à bout de souffle; ne cache pas loin de moi ta face, je serais de ceux qui descendent à la fosse.","8":"Fais que j'entende au matin ton amour, car je compte sur toi; fais que je sache la route à suivre, car vers toi j'élève mon âme.","9":"Délivre-moi de mes ennemis, Yahvé, près de toi je suis à couvert,","10":"enseigne-moi à faire tes volontés, car c'est toi mon Dieu; que ton souffle bon me conduise par une terre unie.","11":"A cause de ton nom, Yahvé, fais que je vive en ta justice; tire mon âme de l'angoisse,","12":"en ton amour anéantis mes ennemis; détruis tous les oppresseurs de mon âme, car moi je suis ton serviteur."},"144":{"1":"De David. Béni soit Yahvé mon rocher, qui instruit mes mains au combat et mes doigts pour la bataille,","2":"mon amour et ma forteresse, ma citadelle et mon libérateur, mon bouclier, en lui je m'abrite, il range les peuples sous moi.","3":"Yahvé, qu'est donc l'homme, que tu le connaisses, l'être humain, que tu penses à lui?","4":"L'homme est semblable à un souffle, ses jours sont comme l'ombre qui passe.","5":"Yahvé, incline tes cieux et descends, touche les montagnes et qu'elles fument;","6":"fais éclater l'éclair, et les disloque, décoche tes flèches, et les ébranle.","7":"D'en haut tends la main, sauve-moi, tire-moi des grandes eaux, de la main des fils d'étrangers","8":"dont la bouche parle de riens, et la droite est une droite de parjure.","9":"O Dieu, je te chante un chant nouveau, sur la lyre à dix cordes je joue pour toi,","10":"toi qui donnes aux rois la victoire, qui sauves David ton serviteur. De l'épée de malheur","11":"sauve-moi, tire-moi de la main des étrangers dont la bouche parle de riens, et la droite est une droite de parjure.","12":"Voici nos fils comme des plants grandis dès le jeune âge, nos filles, des figures d'angle, image de palais.","13":"Nos greniers remplis, débordants, de fruits de toute espèce, nos brebis, des milliers, des myriades, parmi nos campagnes,","14":"nos bestiaux bien pesants, point de brèche ni de fuite, et point de gémissement sur nos places.","15":"Heureux le peuple où c'est ainsi, heureux le peuple dont Yahvé est le Dieu!"},"145":{"1":"Louange. De David. Je t'exalte, ô Roi mon Dieu, je bénis ton nom toujours et à jamais;","2":"je veux te bénir chaque jour, je louerai ton nom toujours et à jamais;","3":"grand est Yahvé et louable hautement, à sa grandeur point de mesure.","4":"Un âge à l'autre vantera tes oeuvres, fera connaître tes prouesses.","5":"Splendeur de gloire, ton renom! Je me répète le récit de tes merveilles.","6":"On dira ta puissance de terreurs, et moi je raconterai ta grandeur;","7":"on fera mémoire de ton immense bonté, on acclamera ta justice.","8":"Yahvé est tendresse et pitié, lent à la colère et plein d'amour;","9":"il est bon, Yahvé, envers tous, et ses tendresses pour toutes ses oeuvres.","10":"Que toutes tes oeuvres te rendent grâce, Yahvé, que tes amis te bénissent;","11":"qu'ils disent la gloire de ton règne, qu'ils parlent de ta prouesse,","12":"pour faire savoir aux fils d'Adam tes prouesses, la splendeur de gloire de ton règne!","13":"Ton règne, un règne pour tous les siècles, ton empire, pour les âges des âges! Yahvé est vérité en toutes ses paroles, amour en toutes ses oeuvres;","14":"Yahvé retient tous ceux qui tombent, redresse tous ceux qui sont courbés.","15":"Tous ont les yeux sur toi, ils espèrent; tu leur donnes la nourriture en son temps;","16":"toi, tu ouvres la main et rassasies tout vivant à plaisir.","17":"Yahvé est justice en toutes ses voies, amour en toutes ses oeuvres;","18":"proche est Yahvé de ceux qui l'invoquent, de tous ceux qui l'invoquent en vérité.","19":"Le désir de ceux qui le craignent, il le fait, il entend leur cri et les sauve;","20":"Yahvé garde tous ceux qui l'aiment, tous les impies, il les détruira.","21":"Que ma bouche dise la louange de Yahvé, que toute chair bénisse son saint nom, toujours et à jamais!"},"146":{"1":"Alleluia! Loue Yahvé, mon âme!","2":"Je veux louer Yahvé tant que je vis, je veux jouer pour mon Dieu tant que je dure.","3":"Ne mettez point votre foi dans les princes, dans un fils de la glaise, il ne peut sauver!","4":"Il rend le souffle, il retourne à sa glaise, en ce jour-là périssent ses pensées.","5":"Heureux qui a l'appui du Dieu de Jacob et son espoir en Yahvé son Dieu,","6":"lui qui a fait le ciel et la terre, la mer, et tout ce qu'ils renferment! Il garde à jamais la vérité,","7":"il rend justice aux opprimés, il donne aux affamés du pain, Yahvé délie les enchaînés.","8":"Yahvé rend la vue aux aveugles, Yahvé redresse les courbés, Yahvé aime les justes,","9":"Yahvé protège l'étranger, il soutient l'orphelin et la veuve. Mais détourne la voie des impies,","10":"Yahvé règne pour les siècles, ton Dieu, ô Sion, d'âge en âge."},"147":{"1":"Alleluia! Louez Yahvé -- il est bon de chanter, notre Dieu -- douce est la louange.","2":"Bâtisseur de Jérusalem, Yahvé! il rassemble les déportés d'Israël,","3":"lui qui guérit les coeurs brisés et qui bande leurs blessures;","4":"qui compte le nombre des étoiles, et il appelle chacune par son nom.","5":"Il est grand, notre Seigneur, tout-puissant, à son intelligence point de mesure.","6":"Yahvé soutient les humbles, jusqu'à terre il abaisse les impies.","7":"Entonnez pour Yahvé l'action de grâces, jouez pour notre Dieu sur la harpe:","8":"lui qui drape les cieux de nuées, qui prépare la pluie à la terre, qui fait germer l'herbe sur les monts et les plantes au service de l'homme,","9":"qui dispense au bétail sa pâture, aux petits du corbeau qui crient.","10":"Ni la vigueur du cheval ne lui agrée, ni le jarret de l'homme ne lui plaît;","11":"Yahvé se plaît en ceux qui le craignent, en ceux qui espèrent son amour.","12":"Fête Yahvé, Jérusalem, loue ton Dieu, ô Sion!","13":"Il renforça les barres de tes portes, il a chez toi béni tes enfants;","14":"il assure ton sol dans la paix, de la graisse du froment te rassasie.","15":"Il envoie son verbe sur terre, rapide court sa parole;","16":"il dispense la neige comme laine, répand le givre comme cendre.","17":"Il jette sa glace par morceaux: à sa froidure, qui peut tenir?","18":"Il envoie sa parole et fait fondre, il souffle son vent, les eaux coulent.","19":"Il révèle à Jacob sa parole, ses lois et jugements à Israël;","20":"pas un peuple qu'il ait ainsi traité, pas un qui ait connu ses jugements."},"148":{"1":"Alleluia! Louez Yahvé depuis les cieux, louez-le dans les hauteurs,","2":"louez-le, tous ses anges, louez-le, toutes ses armées!","3":"Louez-le, soleil et lune, louez-le, tous les astres de lumière,","4":"louez-le, cieux des cieux, et les eaux de dessus les cieux!","5":"Qu'ils louent le nom de Yahvé: lui commanda, eux furent créés;","6":"il les posa pour toujours et à jamais, sous une loi qui jamais ne passera.","7":"Louez Yahvé depuis la terre, monstres marins, tous les abîmes,","8":"feu et grêle, neige et brume, vent d'ouragan, l'ouvrier de sa parole,","9":"montagnes, toutes les collines, arbre à fruit, tous les cèdres,","10":"bête sauvage, tout le bétail, reptile, et l'oiseau qui vole,","11":"rois de la terre, tous les peuples, princes, tous les juges de la terre,","12":"jeunes hommes, aussi les vierges, les vieillards avec les enfants!","13":"Qu'ils louent le nom de Yahvé: sublime est son nom, lui seul, sa majesté par-dessus terre et ciel!","14":"Il rehausse la vigueur de son peuple, fierté pour tous ses amis, pour les enfants d'Israël, le peuple de ses proches."},"149":{"1":"Alleluia! Chantez à Yahvé un chant nouveau: sa louange dans l'assemblée des siens!","2":"Joie pour Israël en son auteur, pour les fils de Sion, allégresse en leur roi,","3":"louange à son nom par la danse, pour lui, jeu de harpe et de tambour!","4":"Car Yahvé se complaît en son peuple, de salut il pare les humbles,","5":"les siens jubilent de gloire, ils acclament depuis leur place:","6":"les éloges de Dieu à pleine gorge, à pleines mains l'épée à deux tranchants;","7":"pour exercer sur les peuples vengeance, sur les nations le châtiment,","8":"pour lier de chaînes leurs rois, d'entraves de fer leurs notables,","9":"pour leur appliquer la sentence écrite: gloire en soit à tous les siens!"},"150":{"1":"Alleluia! Louez Dieu en son sanctuaire, louez-le au firmament de sa puissance,","2":"louez-le en ses oeuvres de vaillance, louez-le en toute sa grandeur!","3":"Louez-le par l'éclat du cor, louez-le par la harpe et la cithare,","4":"louez-le par la danse et le tambour, louez-le par les cordes et les flûtes,","5":"louez-le par les cymbales sonores, louez-le par les cymbales triomphantes!","6":"Que tout ce qui respire loue Yahvé!"}};